export type Language = 'es' | 'en' | 'fr';

export enum MarketType {
  GENERAL = 'general',
  CRYPTO = 'crypto',
  STOCKS = 'stocks',
  COMMODITIES = 'commodities'
}

export enum Priority {
  STABILITY = 'stability',
  FAST = 'fast'
}

export interface TimeInput {
  h: number;
  d: number;
  w: number;
  m: number;
  y: number;
}

export interface Prediction {
  name: string;
  ticker: string;
  type: string;
  pros: string[];
  cons: string[];
  withdraw: string;
  confidence: number;
}

export interface TickerItem {
  symbol: string;
  price: string;
  change: string;
  isUp: boolean;
}

export interface Translation {
  title: string;
  loading: string;
  predict: string;
  priority: string;
  stability: string;
  fast: string;
  general: string;
  crypto: string;
  stocks: string;
  commodities: string;
  pros: string;
  cons: string;
  withdraw: string;
  hours: string;
  days: string;
  weeks: string;
  months: string;
  years: string;
  confidence: string;
  strategy: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Prediction } from "../types";

export const fetchPredictions = async (
  totalHours: number,
  priority: string,
  type: string,
  lang: string
): Promise<Prediction[]> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) {
      console.warn("API Key not found, using mock data fallback if necessary or failing.");
      throw new Error("API Key is missing.");
    }

    const ai = new GoogleGenAI({ apiKey });

    // Determine horizon string for context
    const horizon = totalHours < 168 ? "short" : totalHours < 8760 ? "medium" : "long";

    const prompt = `
      User Context:
      - Horizon: ${horizon} term (${totalHours} hours total).
      - Priority: ${priority} (0=stability, 100=fast earnings).
      - Market Interest: ${type}.
      - Output Language: ${lang}.

      Task: Generate 5 top investment predictions based on the Knowledge Base.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-latest",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              ticker: { type: Type.STRING },
              type: { type: Type.STRING },
              pros: { type: Type.ARRAY, items: { type: Type.STRING } },
              cons: { type: Type.ARRAY, items: { type: Type.STRING } },
              withdraw: { type: Type.STRING },
              confidence: { type: Type.NUMBER },
            },
            required: ["name", "ticker", "type", "pros", "cons", "withdraw", "confidence"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];

    return JSON.parse(text) as Prediction[];
  } catch (error) {
    console.error("Gemini API Error:", error);
    // Fallback Mock for demo purposes if API fails or key is missing
    return [
      {
        name: "Mock BTC ETF",
        ticker: "BTC",
        type: "Crypto",
        pros: ["High Institutional Inflow", "Halving Supply Shock"],
        cons: ["Regulatory Uncertainty", "High Volatility"],
        withdraw: "18 Months",
        confidence: 85
      }
    ];
  }
};

