export default PredictionCard;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS } from './constants';
import { Language, MarketType, Priority, Prediction, TimeInput } from './types';
import { fetchPredictions } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import { BrainCircuit, Settings, Globe } from 'lucide-react';

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [predictions, setPredictions] = useState<Prediction[]>([]);

  // Inputs
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [priorityVal, setPriorityVal] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  const handlePredict = async () => {
    setLoading(true);
    setPredictions([]); // Clear previous
    const totalHours = 
      (time.h * 1) + 
      (time.d * 24) + 
      (time.w * 168) + 
      (time.m * 720) + 
      (time.y * 8760);

    // Fallback if no time entered
    const safeHours = totalHours === 0 ? 168 : totalHours; 

    const priority = priorityVal > 50 ? Priority.FAST : Priority.STABILITY;

    try {
      const results = await fetchPredictions(safeHours, priority, type, lang);
      setPredictions(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden">
      {/* Background Ambience */}
      <div className="fixed inset-0 bg-[#242325] z-0" />
      <motion.div 
        className="fixed inset-0 z-0 bg-gradient-to-tr from-broker-purple/20 via-broker-pink/10 to-broker-cyan/5 blur-3xl opacity-60 pointer-events-none"
        animate={{ rotate: [-5, 5] }}
        transition={{ duration: 15, repeat: Infinity, repeatType: "mirror" }}
      />

      {/* UI Layer */}
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">GEMINI POWERED ANALYTICS</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          {/* Controls Section */}
          <div className="glass-panel border border-broker-pink/30 p-8 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)]">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">

              {/* Time Inputs */}
              <div className="space-y-4">
                <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2">
                  <ClockIcon /> HORIZON
                </label>
                <div className="grid grid-cols-5 gap-2">
                  {[
                    { k: 'h', l: t.hours }, 
                    { k: 'd', l: t.days }, 
                    { k: 'w', l: t.weeks }, 
                    { k: 'm', l: t.months }, 
                    { k: 'y', l: t.years }
                  ].map(({k, l}) => (
                    <div key={k} className="relative group">
                      <input 
                        type="number" 
                        min="0"
                        placeholder="0"
                        value={(time as any)[k] || ''}
                        onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                        className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none transition-colors placeholder-gray-700"
                      />
                      <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Type & Priority */}
              <div className="space-y-6">
                <div>
                  <label className="text-sm font-bold text-broker-cyan tracking-wider block mb-2">{t.priority}</label>
                  <input 
                    type="range" 
                    min="0" 
                    max="100" 
                    value={priorityVal} 
                    onChange={(e) => setPriorityVal(parseInt(e.target.value))}
                    className="w-full h-2 bg-gradient-to-r from-broker-green to-broker-red appearance-none sharp-edge cursor-pointer" 
                  />
                  <div className="flex justify-between text-xs font-mono mt-2 text-gray-400">
                    <span className={priorityVal <= 50 ? 'text-broker-green font-bold' : ''}>{t.stability}</span>
                    <span className={priorityVal > 50 ? 'text-broker-red font-bold' : ''}>{t.fast}</span>
                  </div>
                </div>

                <div className="grid grid-cols-1">
                  <select 
                    value={type}
                    onChange={(e) => setType(e.target.value as MarketType)}
                    className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer hover:bg-[#1a1a1b]/80"
                  >
                    <option value={MarketType.GENERAL}>{t.general}</option>
                    <option value={MarketType.CRYPTO}>{t.crypto}</option>
                    <option value={MarketType.STOCKS}>{t.stocks}</option>
                    <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                  </select>
                </div>
              </div>
            </div>

            <button 
              onClick={handlePredict}
              disabled={loading}
              className="w-full mt-8 py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(119,17,170,0.5)] flex justify-center items-center gap-3 group"
            >
               {loading ? (
                 <motion.div 
                   animate={{ rotate: 360 }}
                   transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                 >
                   <Settings size={24} />
                 </motion.div>
               ) : (
                 <BrainCircuit size={24} className="group-hover:scale-110 transition-transform" />
               )}
               {loading ? t.loading : t.predict}
            </button>
          </div>

          {/* Results Grid */}
          <div className="grid grid-cols-1 gap-6">
             <AnimatePresence>
                {predictions.map((pred, idx) => (
                  <PredictionCard key={idx} data={pred} t={t} index={idx} />
                ))}
             </AnimatePresence>
             {!loading && predictions.length === 0 && (
               <div className="text-center text-gray-600 font-mono py-20 opacity-50">
                  // WAITING FOR INPUT STREAM...
               </div>
             )}
          </div>

        </main>
      </div>
    </div>
  );
}

