import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS } from './constants';
import { Language, MarketType, Prediction, TimeInput } from './types';
import { fetchPredictions } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame } from 'lucide-react';

// Use a type-casted motion component to bypass environment-specific type conflicts where 'animate' is missing from types
const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [predictions, setPredictions] = useState<Prediction[]>([]);

  // Inputs
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  const handlePredict = async () => {
    setLoading(true);
    setPredictions([]);
    const totalHours = 
      (time.h * 1) + 
      (time.d * 24) + 
      (time.w * 168) + 
      (time.m * 720) + 
      (time.y * 8760);

    const safeHours = totalHours === 0 ? 168 : totalHours; 

    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang);
      setPredictions(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden">
      <div className="fixed inset-0 bg-[#242325] z-0" />
      <MotionDiv 
        className="fixed inset-0 z-0 bg-gradient-to-tr from-broker-purple/20 via-broker-pink/10 to-broker-cyan/5 blur-3xl opacity-60 pointer-events-none"
        animate={{ rotate: [-5, 5] }}
        transition={{ duration: 15, repeat: Infinity, repeatType: "mirror" }}
      />

      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">GEMINI POWERED ANALYTICS</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          <div className="glass-panel border border-broker-pink/30 p-8 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)]">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">

              <div className="space-y-4">
                <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2 uppercase">
                  <ClockIcon /> {t.strategy} / {t.horizon}
                </label>
                <div className="grid grid-cols-5 gap-2">
                  {[
                    { k: 'h', l: t.hours }, 
                    { k: 'd', l: t.days }, 
                    { k: 'w', l: t.weeks }, 
                    { k: 'm', l: t.months }, 
                    { k: 'y', l: t.years }
                  ].map(({k, l}) => (
                    <div key={k} className="relative group">
                      <input 
                        type="number" 
                        min="0"
                        placeholder="0"
                        value={(time as any)[k] || ''}
                        onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                        className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none transition-colors placeholder-gray-700"
                      />
                      <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-6">
                <div className="relative">
                  <div className="flex justify-between items-center mb-4">
                    <label className="text-sm font-bold text-broker-cyan tracking-wider block uppercase">
                       {t.riskIndex}
                    </label>
                    <div className={`flex items-center gap-2 font-mono text-xs font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                      {riskCat.icon} {riskCat.label} ({riskScore})
                    </div>
                  </div>

                  <div className="relative py-4">
                    {/* Visual markers for intervals */}
                    <div className="absolute top-0 left-0 w-full flex justify-between px-1 pointer-events-none">
                       {[0, 25, 50, 75, 100].map(val => (
                         <div key={val} className="flex flex-col items-center">
                            <div className="h-2 w-[1px] bg-white/20 mb-1" />
                            <span className="text-[8px] font-mono text-gray-500">{val}</span>
                         </div>
                       ))}
                    </div>

                    <input 
