const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [predictions, setPredictions] = useState<Prediction[]>([]);

  // Inputs
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', border: 'border-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', border: 'border-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', border: 'border-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', border: 'border-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  const handlePredict = async () => {
    setLoading(true);
    setPredictions([]);
    const totalHours = 
      (time.h * 1) + 
      (time.d * 24) + 
      (time.w * 168) + 
      (time.m * 720) + 
      (time.y * 8760);

    const safeHours = totalHours === 0 ? 168 : totalHours; 

    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang);
      setPredictions(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
