import React from 'react';
import { motion } from 'framer-motion';
import { Prediction, Translation } from '../types';
import { Activity, AlertTriangle, TrendingUp, Clock, Target, ShieldAlert, Scale } from 'lucide-react';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
}

// Use a type-casted motion component to bypass environment-specific type conflicts
const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index }) => {
  const typeLower = data.type.toLowerCase();
  const isCrypto = typeLower.includes('crypto');
  const isStock = typeLower.includes('stock') || typeLower.includes('etf');
  const isIndex = typeLower.includes('index');

  let accentColor = 'text-broker-pink';
  let borderColor = 'border-broker-pink';
  let glowColor = 'shadow-broker-pink/20';
  let bgGradient = 'from-broker-pink/10';

  if (isCrypto) {
    accentColor = 'text-broker-purple';
    borderColor = 'border-broker-purple';
    glowColor = 'shadow-broker-purple/20';
    bgGradient = 'from-broker-purple/10';
  } else if (isStock) {
    accentColor = 'text-broker-cyan';
    borderColor = 'border-broker-cyan';
    glowColor = 'shadow-broker-cyan/20';
    bgGradient = 'from-broker-cyan/10';
  } else if (isIndex) {
    accentColor = 'text-broker-green';
    borderColor = 'border-broker-green';
    glowColor = 'shadow-broker-green/20';
    bgGradient = 'from-broker-green/10';
  }

  return (
    <MotionDiv
      initial={{ opacity: 0, x: -20 }}
      animate={{ opacity: 1, x: 0 }}
      transition={{ delay: index * 0.1 }}
      className={`bg-[#080808] border-l-4 ${borderColor} p-6 sharp-edge relative overflow-hidden group hover:bg-[#111] transition-colors shadow-lg ${glowColor}`}
    >
      {/* Background Gradient Accent */}
      <div className={`absolute top-0 right-0 w-[300px] h-[300px] bg-gradient-to-bl ${bgGradient} to-transparent opacity-20 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none`} />

      <div className="flex justify-between items-start mb-6 relative z-10">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className={`text-[10px] font-black tracking-widest px-2 py-1 bg-white/5 border border-white/10 ${accentColor}`}>
              {data.type.toUpperCase()}
            </span>
            <span className="text-[10px] text-gray-500 font-mono border border-white/5 px-2 py-1">{t.confShort}: {data.confidence}%</span>
          </div>
          <h3 className="text-3xl font-black italic mt-1 text-white tracking-tight">{data.name}</h3>
          <p className="text-xl text-gray-400 font-mono tracking-widest font-bold mt-1">{data.ticker}</p>
        </div>
        <div className="bg-black border border-white/10 p-3 sharp-edge shadow-lg">
          <Activity className={`${accentColor}`} size={24} />
        </div>
      </div>

      {/* Financial Specs Grid - High Contrast */}
      <div className="grid grid-cols-3 gap-4 mb-8 relative z-10">
        <div className="bg-black p-4 sharp-edge border-t-2 border-broker-green shadow-lg">
          <div className="flex items-center gap-2 text-broker-green text-[9px] font-black mb-2 tracking-widest uppercase">
            <Target size={12} /> {t.expectedProfit}
          </div>
          <div className="text-lg md:text-xl font-mono font-bold text-white">{data.expectedProfit}</div>
        </div>
        <div className="bg-black p-4 sharp-edge border-t-2 border-broker-red shadow-lg">
          <div className="flex items-center gap-2 text-broker-red text-[9px] font-black mb-2 tracking-widest uppercase">
            <ShieldAlert size={12} /> {t.expectedLoss}
          </div>
          <div className="text-lg md:text-xl font-mono font-bold text-white">{data.expectedLoss}</div>
        </div>
        <div className="bg-black p-4 sharp-edge border-t-2 border-broker-cyan shadow-lg">
          <div className="flex items-center gap-2 text-broker-cyan text-[9px] font-black mb-2 tracking-widest uppercase">
            <Scale size={12} /> {t.riskRewardRatio}
          </div>
          <div className="text-lg md:text-xl font-mono font-bold text-white">{data.riskRewardRatio}</div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mt-6 text-sm relative z-10">
        <div className="pl-4 border-l border-white/10">
          <h4 className="text-broker-green font-bold mb-3 flex items-center gap-2 text-xs uppercase tracking-wider">
            <TrendingUp size={14} /> {t.pros}
          </h4>
          <ul className="space-y-2">
            {data.pros.map((p, i) => (
              <li key={i} className="text-gray-300 text-xs font-mono flex items-start gap-2">
                <span className="text-broker-green mt-1">▹</span> {p}
              </li>
            ))}
          </ul>
        </div>
        <div className="pl-4 border-l border-white/10">
          <h4 className="text-broker-red font-bold mb-3 flex items-center gap-2 text-xs uppercase tracking-wider">
            <AlertTriangle size={14} /> {t.cons}
          </h4>
          <ul className="space-y-2">
            {data.cons.map((c, i) => (
              <li key={i} className="text-gray-300 text-xs font-mono flex items-start gap-2">
                 <span className="text-broker-red mt-1">▹</span> {c}
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div className="mt-8 pt-4 border-t border-dashed border-white/10 flex items-center justify-between text-broker-cyan font-mono text-sm relative z-10">
        <span className="flex items-center gap-2 text-xs uppercase tracking-widest text-gray-500">
            <Clock size={14} className="text-broker-cyan" /> {t.withdraw}
        </span>
        <span className="font-bold text-black bg-broker-cyan px-4 py-1 sharp-edge text-xs">{data.withdraw}</span>
      </div>

    </MotionDiv>
  );
};

