import React, { useState, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS } from './constants';
import { Language, MarketType, Prediction, TimeInput } from './types';
import { fetchPredictions } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, TrendingUp, Calendar as CalendarIcon, Timer } from 'lucide-react';

// Use a type-casted motion component to bypass environment-specific type conflicts where 'animate' is missing from types
const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [predictions, setPredictions] = useState<Prediction[]>([]);

  // Inputs
  const [isCalendarMode, setIsCalendarMode] = useState(false);
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });

  // Default dates: Start = Today, End = 1 Month from now
  const today = new Date();
  const nextMonth = new Date(today);
  nextMonth.setMonth(today.getMonth() + 1);

  const [dates, setDates] = useState({
    start: today.toISOString().split('T')[0],
    end: nextMonth.toISOString().split('T')[0]
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAuto, setIsAuto] = useState(false);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  // Calculate total hours based on mode
  const getTotalHours = useCallback(() => {
    if (isCalendarMode) {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diffMs = e.getTime() - s.getTime();
      return Math.max(0, Math.ceil(diffMs / (1000 * 60 * 60)));
    } else {
      return (
        (time.h * 1) + 
        (time.d * 24) + 
        (time.w * 168) + 
        (time.m * 720) + 
        (time.y * 8760)
      );
    }
  }, [isCalendarMode, dates, time]);

  // Auto Risk Calculation Effect
  useEffect(() => {
    if (isAuto) {
      const totalHours = getTotalHours();
      let optimalRisk = 50;

      // Standard Financial Planning Logic:
      if (totalHours <= 24) optimalRisk = 80; // Intraday/Scalping
      else if (totalHours <= 168) optimalRisk = 20; // 1 week
      else if (totalHours <= 720) optimalRisk = 35; // 1 month
      else if (totalHours <= 4380) optimalRisk = 50; // 6 months
      else if (totalHours <= 8760) optimalRisk = 65; // 1 year
      else if (totalHours <= 43800) optimalRisk = 80; // 5 years
      else optimalRisk = 90; // 5+ years

      setRiskScore(optimalRisk);
    }
  }, [getTotalHours, isAuto]);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <TrendingUp size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  const handlePredict = async () => {
    setLoading(true);
    setPredictions([]);

    const totalHours = getTotalHours();
    const safeHours = totalHours === 0 ? 168 : totalHours; 

    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang);
      setPredictions(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden">
      <div className="fixed inset-0 bg-[#242325] z-0" />
      <MotionDiv 
        className="fixed inset-0 z-0 bg-gradient-to-tr from-broker-purple/20 via-broker-pink/10 to-broker-cyan/5 blur-3xl opacity-60 pointer-events-none"
        animate={{ rotate: [-5, 5] }}
        transition={{ duration: 15, repeat: Infinity, repeatType: "mirror" }}
      />

      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">GEMINI POWERED ANALYTICS</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          <div className="glass-panel border border-broker-pink/30 p-8 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)]">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">

              {/* Horizon Input */}
              <div className="space-y-4">
                <div className="flex justify-between items-center">
                    <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2 uppercase">
                        <ClockIcon /> {t.horizon}
                    </label>

                    {/* Precise vs Calendar Switch */}
                    <div 
                        onClick={() => setIsCalendarMode(!isCalendarMode)}
                        className="flex items-center gap-2 cursor-pointer transition-colors text-broker-cyan/80 hover:text-broker-cyan"
                    >
                        <span className={`text-[10px] font-mono font-bold ${!isCalendarMode ? 'text-white' : 'text-gray-500'}`}>{t.precise}</span>
                        <div className="w-8 h-4 sharp-edge border border-broker-cyan/50 flex items-center p-0.5 bg-[#1a1a1b]">
                            <motion.div 
                                className="w-2.5 h-2.5 bg-broker-cyan sharp-edge shadow-[0_0_8px_rgba(130,234,255,0.6)]"
                                animate={{ x: isCalendarMode ? 16 : 0 }}
                            />
                        </div>
                        <span className={`text-[10px] font-mono font-bold ${isCalendarMode ? 'text-white' : 'text-gray-500'}`}>{t.calendar}</span>
                    </div>
                </div>

                {isCalendarMode ? (
                   /* Calendar Inputs */
                   <div className="grid grid-cols-2 gap-4">
                      <div className="relative group">
                        <label className="text-[10px] text-gray-500 font-mono mb-1 block uppercase">{t.startDate}</label>
                        <input 
                            type="date"
                            value={dates.start}
                            onChange={(e) => setDates({...dates, start: e.target.value})}
                            className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-white py-3 px-2 text-sm font-mono sharp-edge outline-none transition-colors uppercase"
                        />
                        <CalendarIcon size={14} className="absolute right-2 bottom-4 text-gray-500 pointer-events-none" />
                      </div>
                      <div className="relative group">
                        <label className="text-[10px] text-gray-500 font-mono mb-1 block uppercase">{t.endDate}</label>
                        <input 
                            type="date"
                            value={dates.end}
                            onChange={(e) => setDates({...dates, end: e.target.value})}
                            className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-white py-3 px-2 text-sm font-mono sharp-edge outline-none transition-colors uppercase"
                        />
                        <CalendarIcon size={14} className="absolute right-2 bottom-4 text-gray-500 pointer-events-none" />
                      </div>
                   </div>
                ) : (
                   /* Precise Inputs */
                   <div className="grid grid-cols-5 gap-2">
                    {[
                        { k: 'h', l: t.hours }, 
                        { k: 'd', l: t.days }, 
                        { k: 'w', l: t.weeks }, 
                        { k: 'm', l: t.months }, 
                        { k: 'y', l: t.years }
                    ].map(({k, l}) => (
                        <div key={k} className="relative group">
                        <input 
                            type="number" 
                            min="0"
                            placeholder="0"
                            value={(time as any)[k] || ''}
                            onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                            className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none transition-colors placeholder-gray-700"
                        />
                        <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                        </div>
                    ))}
                   </div>
                )}

              </div>

              {/* Strategy Profile with Auto Switch */}
              <div className="space-y-6">
                <div className="relative">
                  <div className="flex justify-between items-center mb-6">
                    <div className="flex items-center gap-4">
                        <label className="text-sm font-bold text-broker-pink tracking-wider block uppercase flex items-center gap-2">
                            <TrendingUp size={16} /> {t.riskIndex}
                        </label>
                        {/* Auto Switch */}
                        <div 
                          onClick={() => setIsAuto(!isAuto)}
                          className={`flex items-center gap-2 cursor-pointer transition-colors ${isAuto ? 'text-white' : 'text-gray-500'}`}
                        >
                            <div className={`w-8 h-4 sharp-edge border border-current flex items-center p-0.5 ${isAuto ? 'bg-broker-pink border-broker-pink' : 'border-gray-600'}`}>
                                <motion.div 
                                    className="w-2.5 h-2.5 bg-white sharp-edge"
                                    animate={{ x: isAuto ? 16 : 0 }}
                                />
                            </div>
                            <span className="text-[10px] font-mono font-bold">{t.auto}</span>
                        </div>
                    </div>

                    <div className={`flex items-center gap-2 font-mono text-[10px] font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                      {riskCat.icon} {riskCat.label} ({riskScore})
                    </div>
                  </div>

                  <div className={`relative py-4 px-1 ${isAuto ? 'opacity-80' : ''}`}>
                    <input 
                      type="range" 
                      min="0" 
                      max="100" 
                      step="1"
                      disabled={isAuto}
                      value={riskScore} 
                      onChange={(e) => setRiskScore(parseInt(e.target.value))}
                      className={`w-full appearance-none cursor-pointer z-10 focus:outline-none ${isAuto ? 'cursor-not-allowed' : ''}`} 
                    />
                  </div>

                  <div className="flex justify-between text-[10px] font-mono mt-2 uppercase tracking-widest font-bold">
                    <span className="text-broker-green">{t.lowRiskHint}</span>
                    <span className="text-broker-red">{t.highRiskHint}</span>
                  </div>
                </div>

                <div className="grid grid-cols-1">
                  <select 
                    value={type}
                    onChange={(e) => setType(e.target.value as MarketType)}
                    className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer hover:bg-[#1a1a1b]/80"
                  >
                    <option value={MarketType.GENERAL}>{t.general}</option>
                    <option value={MarketType.CRYPTO}>{t.crypto}</option>
                    <option value={MarketType.STOCKS}>{t.stocks}</option>
                    <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                    <option value={MarketType.ETFS}>{t.etfs}</option>
                    <option value={MarketType.INDEXES}>{t.indexes}</option>
                  </select>
                </div>
              </div>
            </div>

            <button 
              onClick={handlePredict}
              disabled={loading}
              className="w-full mt-8 py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(119,17,170,0.5)] flex justify-center items-center gap-3 group"
            >
               {loading ? (
                 <MotionDiv 
                   animate={{ rotate: 360 }}
                   transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
