import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Prediction, MarketType } from "../types";

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string
): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Determine horizon string for context
    const horizon = totalHours < 168 ? "short" : totalHours < 8760 ? "medium" : "long";

    let prompt = "";
    let schemaProperties: any = {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING, description: "Expected profit range e.g. +10% to +15%" },
      expectedLoss: { type: Type.STRING, description: "Expected loss range e.g. -2% to -5%" },
      riskRewardRatio: { type: Type.STRING, description: "Risk to reward ratio e.g. 1:3" },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
    };

    let requiredFields = ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"];

    if (type === MarketType.COMBO) {
      prompt = `
        User Context:
        - Horizon: ${horizon} term (${totalHours} hours total).
        - Risk Index: ${riskScore}/100.
        - Market Interest: Multi-Asset Strategic Combos.
        - Output Language: ${lang}.

        Task: Generate 3 "Super Combos". Each combo must be a diversified basket of EXACTLY 3 distinct assets (can mix Crypto, Stocks, Commodities) that work synergistically for the given Risk Index.

        For each Combo:
        1. Name: Give it a creative strategy name (e.g., "The Inflation Hedge Trio" or "Aggressive Tech Alpha").
        2. Ticker: Use "COMBO-X" as the ticker.
        3. Holdings: You MUST list exactly 3 assets. For each asset, provide the Name, Ticker, and the specific % of capital to allocate (must sum to 100%).
        4. Financials: Provide Expected Profit, Loss, and Risk Ratio for the *entire portfolio combo*.
      `;

      // Add holdings to schema
      schemaProperties.holdings = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            percentage: { type: Type.STRING, description: "Allocation percentage e.g. 40%" }
          },
          required: ["name", "ticker", "percentage"]
        }
      };
      requiredFields.push("holdings");

    } else {
      prompt = `
        User Context:
        - Horizon: ${horizon} term (${totalHours} hours total).
        - Risk Index: ${riskScore}/100.
        - Market Interest: ${type}.
        - Output Language: ${lang}.

        Task: Generate 5 top investment predictions strictly adhering to the Risk Index provided. 
        BE BRUTALLY SPECIFIC. Provide exact tickers, profit targets, and stop loss ranges.
      `;
    }

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: schemaProperties,
            required: requiredFields,
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];

    return JSON.parse(text) as Prediction[];
  } catch (error) {
    console.error("Gemini API Error:", error);
    return [];
  }
};

