// Use a type-casted motion component to bypass environment-specific type conflicts where 'animate' is missing from types
const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [predictions, setPredictions] = useState<Prediction[]>([]);

  // Inputs
  const [isCalendarMode, setIsCalendarMode] = useState(false);
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });

  // Default dates: Start = Today, End = 1 Month from now
  const today = new Date();
  const nextMonth = new Date(today);
  nextMonth.setMonth(today.getMonth() + 1);

  const [dates, setDates] = useState({
    start: today.toISOString().split('T')[0],
    end: nextMonth.toISOString().split('T')[0]
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAuto, setIsAuto] = useState(false);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  // Calculate total hours based on mode
  const getTotalHours = useCallback(() => {
    if (isCalendarMode) {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diffMs = e.getTime() - s.getTime();
      return Math.max(0, Math.ceil(diffMs / (1000 * 60 * 60)));
    } else {
      return (
        (time.h * 1) + 
        (time.d * 24) + 
        (time.w * 168) + 
        (time.m * 720) + 
        (time.y * 8760)
      );
    }
  }, [isCalendarMode, dates, time]);

  // Auto Risk Calculation Effect
  useEffect(() => {
    if (isAuto) {
      const totalHours = getTotalHours();
      let optimalRisk = 50;

      // Standard Financial Planning Logic:
      if (totalHours <= 24) optimalRisk = 80; // Intraday/Scalping
      else if (totalHours <= 168) optimalRisk = 20; // 1 week
      else if (totalHours <= 720) optimalRisk = 35; // 1 month
      else if (totalHours <= 4380) optimalRisk = 50; // 6 months
      else if (totalHours <= 8760) optimalRisk = 65; // 1 year
      else if (totalHours <= 43800) optimalRisk = 80; // 5 years
      else optimalRisk = 90; // 5+ years

      setRiskScore(optimalRisk);
    }
  }, [getTotalHours, isAuto]);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <TrendingUp size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  const handlePredict = async () => {
    setLoading(true);
    setPredictions([]);

    const totalHours = getTotalHours();
    const safeHours = totalHours === 0 ? 168 : totalHours; 

    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang);
      setPredictions(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden">
      <div className="fixed inset-0 bg-[#242325] z-0" />
