                disabled={loading || predictions.length === 0}
                className="flex-1 py-5 bg-black/40 border-2 border-broker-red/50 text-broker-red font-black text-sm tracking-widest sharp-edge hover:bg-broker-red hover:text-white transition-all disabled:opacity-20 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
