          <div className="grid grid-cols-1 gap-6">
             <AnimatePresence mode="popLayout">
                {predictions.map((pred, idx) => (
                  <PredictionCard key={`${idx}-${lang}`} data={pred} t={t} index={idx} />
                ))}
             </AnimatePresence>
             {!loading && predictions.length === 0 && (
               <div className="text-center text-gray-600 font-mono py-20 opacity-50">
                  {t.scanPrompt}
