import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Prediction } from "../types";

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string
): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const horizon = totalHours < 168 ? "short" : totalHours < 8760 ? "medium" : "long";

    const prompt = `
      [REAL-TIME LIVE MARKET ANALYSIS ENABLED]
      User Context:
      - Horizon: ${horizon} term (${totalHours} hours total).
      - Risk Index: ${riskScore}/100.
      - Market Interest: ${type}.
      - Output Language: ${lang}.

      Instruction: 
      1. USE GOOGLE SEARCH to find the LATEST real-time prices, news, and technical indicators for potential candidates.
      2. Analyze recent news from Bloomberg, Reuters, Google Finance, and Yahoo Finance.
      3. Generate 5 specific investment predictions based on THIS MOMENT'S market conditions.
      4. Verify that the asset is currently tradable and check its today's price action.

      ${type === 'super_combo' ? 'IMPORTANT: Use Super Combo mode. Provide exactly 3 holdings per prediction with weight distribution.' : ''}
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        // Enable Google Search Grounding for real-time financial data
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION + "\n\nCRITICAL: You are connected to the internet via Google Search. You MUST use this tool to fetch REAL-TIME prices, news, and market sentiment. Do not rely on training data. Verify every price and percentage change against live sources.",
        responseMimeType: "application/json",
        // Enable deep thinking to simulate complex market scenarios and process search results
        thinkingConfig: { thinkingBudget: 32768 },
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              ticker: { type: Type.STRING },
              type: { type: Type.STRING },
              expectedProfit: { type: Type.STRING },
              expectedLoss: { type: Type.STRING },
              riskRewardRatio: { type: Type.STRING },
              pros: { type: Type.ARRAY, items: { type: Type.STRING } },
              cons: { type: Type.ARRAY, items: { type: Type.STRING } },
              withdraw: { type: Type.STRING },
              confidence: { type: Type.NUMBER },
              holdings: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    name: { type: Type.STRING },
                    ticker: { type: Type.STRING },
                    weight: { type: Type.NUMBER },
                  },
                },
              },
            },
            required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
          },
        },
      },
    });

    const text = response.text;
    if (!text) return [];

    return JSON.parse(text) as Prediction[];
  } catch (error) {
    console.error("Gemini AI Broker Error:", error);
    return [];
  }
};

