                            className="grid grid-cols-5 gap-2 w-full"
                          >
                            {[
                              { k: 'h', l: t.hours }, 
                              { k: 'd', l: t.days }, 
                              { k: 'w', l: t.weeks }, 
                              { k: 'm', l: t.months }, 
                              { k: 'y', l: t.years }
