                                value={dates.end}
                                onChange={(e) => setDates({...dates, end: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light cursor-pointer"
                              />
                            </div>
                          </MotionDiv>
                        )}
                      </div>
                    </div>

                    <div className="space-y-6">
                      <div className="relative">
                        <div className="flex justify-between items-center mb-4">
                          <div className="flex items-center gap-4">
                            <label className="text-sm font-bold text-broker-cyan tracking-wider block uppercase">
                              {t.riskIndex}
                            </label>
                            <button 
                              onClick={() => setIsAutoRisk(!isAutoRisk)}
                              className={`text-[9px] font-black tracking-widest uppercase px-3 py-1 transition-all ${isAutoRisk ? 'bg-broker-green text-black' : 'bg-white/5 border border-white/10 text-gray-400'}`}
                            >
                              {t.autoRisk}
                            </button>
                          </div>
                          <div className={`flex items-center gap-2 font-mono text-xs font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                            {riskCat.icon} {riskCat.label} ({riskScore})
                          </div>
                        </div>

                        <div className="relative py-6">
                          <div className="relative flex items-center h-4">
                            <div className="absolute top-1/2 left-0 w-full h-[1px] bg-white/20 -translate-y-1/2 pointer-events-none" />
                            <div 
                              className="absolute top-1/2 left-0 h-[1px] bg-white -translate-y-1/2 pointer-events-none transition-all duration-100 ease-out" 
                              style={{ width: `${riskScore}%` }}
                            />
                            <input 
                              type="range" 
                              min="0" 
                              max="100" 
                              step="1"
                              disabled={isAutoRisk}
                              value={riskScore} 
                              onChange={(e) => setRiskScore(parseInt(e.target.value))}
                              className={`w-full h-4 bg-transparent appearance-none cursor-pointer relative z-10 focus:outline-none ${isAutoRisk ? 'opacity-30 cursor-not-allowed' : ''}`} 
                            />
                          </div>
                        </div>

                        <div className="flex justify-between text-[10px] font-mono text-gray-400 uppercase tracking-widest font-bold">
                          <span>{t.lowRiskHint}</span>
                          <span>{t.highRiskHint}</span>
                        </div>
                      </div>

                      <div className="grid grid-cols-1">
                        <select 
                          value={type}
                          onChange={(e) => setType(e.target.value as MarketType)}
                          className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer hover:bg-[#1a1a1b]/80"
                        >
                          <option value={MarketType.GENERAL}>{t.general}</option>
                          <option value={MarketType.SUPER_COMBO}>{t.superCombo}</option>
                          <option value={MarketType.CRYPTO}>{t.crypto}</option>
                          <option value={MarketType.STOCKS}>{t.stocks}</option>
                          <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                          <option value={MarketType.ETFS}>{t.etfs}</option>
                          <option value={MarketType.INDEXES}>{t.indexes}</option>
                          <option value={MarketType.BONDS}>{t.bonds}</option>
                          <option value={MarketType.MUTUAL_FUNDS}>{t.mutualFunds}</option>
                        </select>
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-4 mt-8">
                    <button 
                      onClick={handlePredict}
                      disabled={loading}
                      className="flex-[3] py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(119,17,170,0.5)] flex justify-center items-center gap-3 group"
                    >
                      {loading ? (
                        <MotionDiv 
                          animate={{ rotate: 360 }}
                          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        >
                          <Settings size={24} />
                        </MotionDiv>
                      ) : (
                        <BrainCircuit size={24} className="group-hover:scale-110 transition-transform" />
                      )}
                      {loading ? t.loading : t.predict}
                    </button>

                    <button 
                      onClick={handleClear}
                      disabled={loading || predictions.length === 0}
                      className="flex-1 py-5 bg-black/40 border-2 border-broker-red/50 text-broker-red font-black text-sm tracking-widest sharp-edge hover:bg-broker-red hover:text-white transition-all disabled:opacity-20 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
                    >
                      <Trash2 size={18} className="group-hover:scale-110 transition-transform" />
                      {t.clear}
                    </button>
                  </div>
                </MotionDiv>
              ) : (
                // SEARCH MODE UI
                <MotionDiv initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key="search">
                  <div className="flex flex-col gap-6">
                     <div className="relative group">
                        <Search className="absolute top-1/2 left-4 -translate-y-1/2 text-broker-cyan" size={24} />
                        <input 
                           type="text"
                           value={searchQuery}
                           onChange={(e) => setSearchQuery(e.target.value)}
                           onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                           placeholder={t.searchPlaceholder}
                           className="w-full bg-[#1a1a1b] border-2 border-broker-cyan/30 focus:border-broker-cyan text-xl p-6 pl-14 sharp-edge outline-none font-mono text-broker-light placeholder-gray-600 transition-colors"
                        />
                     </div>

                     <div className="flex gap-4">
                        <button 
                          onClick={handleSearch}
                          disabled={loading || !searchQuery.trim()}
                          className="flex-[3] py-5 bg-gradient-to-r from-broker-cyan to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(130,234,255,0.3)] flex justify-center items-center gap-3 group"
                        >
                          {loading ? (
                            <MotionDiv 
                              animate={{ rotate: 360 }}
                              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                            >
                              <Settings size={24} />
                            </MotionDiv>
                          ) : (
                            <Search size={24} className="group-hover:scale-110 transition-transform" />
                          )}
                          {t.searchButton}
                        </button>
                         <button 
                            onClick={handleClear}
                            disabled={loading || predictions.length === 0}
                            className="flex-1 py-5 bg-black/40 border-2 border-broker-red/50 text-broker-red font-black text-sm tracking-widest sharp-edge hover:bg-broker-red hover:text-white transition-all disabled:opacity-20 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
                          >
                            <Trash2 size={18} className="group-hover:scale-110 transition-transform" />
                            {t.clear}
                          </button>
                     </div>
                  </div>
                </MotionDiv>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6">
             <AnimatePresence mode="popLayout">
                {predictions.map((pred, idx) => (
                  <PredictionCard key={`${idx}-${lang}`} data={pred} t={t} index={idx} />
                ))}
             </AnimatePresence>
             {!loading && predictions.length === 0 && (
               <div className="text-center text-gray-600 font-mono py-20 opacity-50">
                  {t.scanPrompt}
               </div>
             )}
          </div>

        </main>
      </div>

      <Dictionary />

      <style>{`
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
          margin-top: 0px; 
        }
        input[type=range]::-moz-range-thumb {
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
