  const isIndex = typeLower.includes('index');
  const isCommodity = typeLower.includes('commodity');
  const isSuperCombo = typeLower.includes('super combo') || typeLower.includes('combo') || !!data.holdings;

  let accentColor = 'text-broker-pink';
