import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION } from "../constants";
import { Prediction, TickerItem } from "../types";

const getSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING },
      expectedLoss: { type: Type.STRING },
      riskRewardRatio: { type: Type.STRING },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER },
          },
        },
      },
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
  },
});

const getTickerSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING },
      price: { type: Type.STRING },
      change: { type: Type.STRING },
      isUp: { type: Type.BOOLEAN },
    },
    required: ["symbol", "price", "change", "isUp"],
  },
});

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      Retrieve the CURRENT REAL-TIME PRICE and 24h CHANGE for the following key market indices and assets using Google Finance data via Google Search:
      1. S&P 500
      2. NASDAQ 100
      3. BTC/USD
      4. ETH/USD
      5. Gold (XAU)
      6. VIX (Volatility)
      7. EUR/USD
      8. Crude Oil (WTI)

      Return a JSON array.
      Format:
      - symbol: Short name (e.g., "S&P 500", "BTC")
      - price: Current price string (e.g., "5,234.10" or "64,000")
      - change: Percentage change string (e.g., "+0.45%", "-1.20%")
      - isUp: boolean (true if change is positive)
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a live market data feed connected to Google Finance. Provide precise, real-time numbers.",
        responseMimeType: "application/json",
        responseSchema: getTickerSchema(),
      },
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text) as TickerItem[];
  } catch (error) {
    console.error("Gemini Market Data Error:", error);
    return [];
  }
};

