import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, BarChart2, Radio } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);

  // Separate state for each tab to persist data
  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);

  // Ticker State
  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  // View Mode: 'predict' or 'search'
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Horizon Input
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Strategy Input
  const [isAutoRisk, setIsAutoRisk] = useState(false);
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  // Derive current predictions based on active tab
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  // Calculate total hours
  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  // Handle Auto Risk Logic
  useEffect(() => {
    if (isAutoRisk) {
      let autoScore = 50;
      if (totalHours < 24) autoScore = 85; // Scalping
      else if (totalHours < 168) autoScore = 65; // Day/Swing
      else if (totalHours < 720) autoScore = 25; // Stability
      else if (totalHours < 43800) autoScore = 50; // Growth
      else autoScore = 90; // Aggressive Growth (5y+)

      setRiskScore(autoScore);
    }
  }, [totalHours, isAutoRisk]);

  // Load Live Ticker Data
  useEffect(() => {
    const initTicker = async () => {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) {
        setTickerData(data);
      }
    };
    initTicker();
  }, []);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const safeHours = totalHours === 0 ? 168 : totalHours; 

    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang);
      setPredictorResults(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [totalHours, riskScore, type, lang]);

  const handleSearch = useCallback(async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [searchQuery, lang]);

  const handleClear = () => {
    if (activePredictions.length === 0) return;
    if (window.confirm(t.confirmClear)) {
      if (viewMode === 'predict') {
        setPredictorResults([]);
      } else {
        setSearchResults([]);
      }
    }
  };

  // Re-fetch only if in predict mode and already have predictions (e.g. language switch)
  useEffect(() => {
    if (viewMode === 'predict' && predictorResults.length > 0 && !loading) {
      handlePredict();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lang]);

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden bg-broker-bg">
      <div className="fixed inset-0 bg-[#242325] z-0" />

      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">GEMINI POWERED ANALYTICS</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          <div className="glass-panel border border-broker-pink/30 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)] overflow-hidden flex flex-col">

            {/* TABS */}
            <div className="flex border-b border-white/10">
              <button 
                onClick={() => setViewMode('predict')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'predict' ? 'bg-broker-pink/20 text-broker-pink' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Radio size={18} /> {t.tabPredictor}
              </button>
              <button 
                onClick={() => setViewMode('search')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Search size={18} /> {t.tabSearch}
              </button>
            </div>

            {/* PANEL CONTENT */}
            <div className="p-8">
              {viewMode === 'predict' ? (
                // PREDICTOR MODE UI
                <MotionDiv initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key="predict">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2 uppercase">
                          {horizonMode === 'precise' ? <Clock size={16} /> : <Calendar size={16} />} 
                          {t.strategy} / {t.horizon}
                        </label>

                        <button 
                          onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')}
                          className="text-[9px] font-black tracking-widest uppercase px-3 py-1 bg-white/5 border border-white/10 hover:bg-white/10 transition-colors flex items-center gap-2"
                        >
                          <SwitchCamera size={10} /> {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>

                      <div className="h-20 flex items-center">
                        {horizonMode === 'precise' ? (
                          <MotionDiv 
                            key="precise"
                            initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }}
                            className="grid grid-cols-5 gap-2 w-full"
                          >
                            {[
                              { k: 'h', l: t.hours }, 
                              { k: 'd', l: t.days }, 
                              { k: 'w', l: t.weeks }, 
                              { k: 'm', l: t.months }, 
                              { k: 'y', l: t.years }
                            ].map(({k, l}) => (
                              <div key={k} className="relative group">
                                <input 
                                  type="number" 
                                  min="0"
                                  placeholder="0"
                                  value={(time as any)[k] || ''}
                                  onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                                  className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none transition-colors placeholder-gray-700 text-broker-light"
                                />
                                <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                              </div>
                            ))}
                          </MotionDiv>
                        ) : (
                          <MotionDiv 
                            key="calendar"
                            initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }}
                            className="grid grid-cols-2 gap-4 w-full"
                          >
                            <div className="relative group">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase tracking-widest">{t.startDate}</label>
                              <input 
                                type="date"
                                value={dates.start}
                                onChange={(e) => setDates({...dates, start: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light cursor-pointer"
                              />
                            </div>
                            <div className="relative group">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase tracking-widest">{t.endDate}</label>
                              <input 
                                type="date"
                                value={dates.end}
                                onChange={(e) => setDates({...dates, end: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light cursor-pointer"
                              />
                            </div>
                          </MotionDiv>
                        )}
                      </div>
                    </div>

                    <div className="space-y-6">
                      <div className="relative">
                        <div className="flex justify-between items-center mb-4">
                          <div className="flex items-center gap-4">
                            <label className="text-sm font-bold text-broker-cyan tracking-wider block uppercase">
                              {t.riskIndex}
                            </label>
                            <button 
                              onClick={() => setIsAutoRisk(!isAutoRisk)}
                              className={`text-[9px] font-black tracking-widest uppercase px-3 py-1 transition-all ${isAutoRisk ? 'bg-broker-green text-black' : 'bg-white/5 border border-white/10 text-gray-400'}`}
                            >
                              {t.autoRisk}
                            </button>
                          </div>
                          <div className={`flex items-center gap-2 font-mono text-xs font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                            {riskCat.icon} {riskCat.label} ({riskScore})
                          </div>
                        </div>

                        <div className="relative py-6">
                          <div className="relative flex items-center h-4">
                            <div className="absolute top-1/2 left-0 w-full h-[1px] bg-white/20 -translate-y-1/2 pointer-events-none" />
                            <div 
                              className="absolute top-1/2 left-0 h-[1px] bg-white -translate-y-1/2 pointer-events-none transition-all duration-100 ease-out" 
                              style={{ width: `${riskScore}%` }}
                            />
                            <input 
                              type="range" 
                              min="0" 
                              max="100" 
                              step="1"
                              disabled={isAutoRisk}
                              value={riskScore} 
                              onChange={(e) => setRiskScore(parseInt(e.target.value))}
                              className={`w-full h-4 bg-transparent appearance-none cursor-pointer relative z-10 focus:outline-none ${isAutoRisk ? 'opacity-30 cursor-not-allowed' : ''}`} 
                            />
                          </div>
                        </div>

                        <div className="flex justify-between text-[10px] font-mono text-gray-400 uppercase tracking-widest font-bold">
                          <span>{t.lowRiskHint}</span>
                          <span>{t.highRiskHint}</span>
                        </div>
                      </div>

                      <div className="grid grid-cols-1">
                        <select 
                          value={type}
                          onChange={(e) => setType(e.target.value as MarketType)}
                          className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer hover:bg-[#1a1a1b]/80"
                        >
                          <option value={MarketType.GENERAL}>{t.general}</option>
                          <option value={MarketType.SUPER_COMBO}>{t.superCombo}</option>
                          <option value={MarketType.CRYPTO}>{t.crypto}</option>
                          <option value={MarketType.STOCKS}>{t.stocks}</option>
                          <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                          <option value={MarketType.ETFS}>{t.etfs}</option>
                          <option value={MarketType.INDEXES}>{t.indexes}</option>
                          <option value={MarketType.BONDS}>{t.bonds}</option>
                          <option value={MarketType.MUTUAL_FUNDS}>{t.mutualFunds}</option>
                        </select>
                      </div>
                    </div>
                  </div>

                  <div className="flex gap-4 mt-8">
                    <button 
                      onClick={handlePredict}
                      disabled={loading}
                      className="flex-[3] py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(119,17,170,0.5)] flex justify-center items-center gap-3 group"
                    >
                      {loading ? (
                        <MotionDiv 
                          animate={{ rotate: 360 }}
                          transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        >
                          <Settings size={24} />
                        </MotionDiv>
                      ) : (
                        <BrainCircuit size={24} className="group-hover:scale-110 transition-transform" />
                      )}
                      {loading ? t.loading : t.predict}
                    </button>

                    <button 
                      onClick={handleClear}
                      disabled={loading || activePredictions.length === 0}
                      className="flex-1 py-5 bg-black/40 border-2 border-broker-red/50 text-broker-red font-black text-sm tracking-widest sharp-edge hover:bg-broker-red hover:text-white transition-all disabled:opacity-20 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
                    >
                      <Trash2 size={18} className="group-hover:scale-110 transition-transform" />
                      {t.clear}
                    </button>
                  </div>
                </MotionDiv>
              ) : (
                // SEARCH MODE UI
                <MotionDiv initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key="search">
                  <div className="flex flex-col gap-6">
                     <div className="relative group">
                        <Search className="absolute top-1/2 left-4 -translate-y-1/2 text-broker-cyan" size={24} />
                        <input 
                           type="text"
                           value={searchQuery}
                           onChange={(e) => setSearchQuery(e.target.value)}
                           onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                           placeholder={t.searchPlaceholder}
                           className="w-full bg-[#1a1a1b] border-2 border-broker-cyan/30 focus:border-broker-cyan text-xl p-6 pl-14 sharp-edge outline-none font-mono text-broker-light placeholder-gray-600 transition-colors"
                        />
                     </div>

                     <div className="flex gap-4">
                        <button 
                          onClick={handleSearch}
                          disabled={loading || !searchQuery.trim()}
                          className="flex-[3] py-5 bg-gradient-to-r from-broker-cyan to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed shadow-[0_0_20px_rgba(130,234,255,0.3)] flex justify-center items-center gap-3 group"
                        >
                          {loading ? (
                            <MotionDiv 
                              animate={{ rotate: 360 }}
                              transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                            >
                              <Settings size={24} />
                            </MotionDiv>
                          ) : (
                            <Search size={24} className="group-hover:scale-110 transition-transform" />
                          )}
                          {t.searchButton}
                        </button>
                         <button 
                            onClick={handleClear}
                            disabled={loading || activePredictions.length === 0}
                            className="flex-1 py-5 bg-black/40 border-2 border-broker-red/50 text-broker-red font-black text-sm tracking-widest sharp-edge hover:bg-broker-red hover:text-white transition-all disabled:opacity-20 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
                          >
                            <Trash2 size={18} className="group-hover:scale-110 transition-transform" />
                            {t.clear}
                          </button>
                     </div>
                  </div>
                </MotionDiv>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6">
             <AnimatePresence mode="popLayout">
                {activePredictions.map((pred, idx) => (
                  <PredictionCard key={`${idx}-${lang}`} data={pred} t={t} index={idx} />
                ))}
             </AnimatePresence>
             {!loading && activePredictions.length === 0 && (
               <div className="text-center text-gray-600 font-mono py-20 opacity-50">
                  {t.scanPrompt}
               </div>
             )}
          </div>

        </main>
      </div>

      <Dictionary />

      <style>{`
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
          margin-top: 0px; 
        }
        input[type=range]::-moz-range-thumb {
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #F31B80;
          border-radius: 0px;
        }
      `}</style>
    </div>
  );
}

export type Language = 'es' | 'en' | 'fr';

export enum MarketType {
  GENERAL = 'general',
  CRYPTO = 'crypto',
  STOCKS = 'stocks',
  COMMODITIES = 'commodities',
  FOREX = 'forex',
  ETFS = 'etfs',
  INDEXES = 'indexes',
  BONDS = 'bonds',
  MUTUAL_FUNDS = 'mutual_funds',
  SUPER_COMBO = 'super_combo'
}

export type HorizonMode = 'precise' | 'calendar';

export interface TimeInput {
  h: number;
  d: number;
  w: number;
  m: number;
  y: number;
}

export interface Holding {
  name: string;
  ticker: string;
  weight: number;
}

export interface Prediction {
  name: string;
  ticker: string;
  type: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  pros: string[];
  cons: string[];
  withdraw: string;
  confidence: number;
  holdings?: Holding[];
}

export interface TickerItem {
  symbol: string;
  price: string;
  change: string;
  isUp: boolean;
}

export interface CorrelationData {
  assetA: string;
  assetB: string;
  correlation: number; // -1 to 1
}

export interface Translation {
  title: string;
  loading: string;
  predict: string;
  priority: string;
  stability: string;
  fast: string;
  general: string;
  crypto: string;
  stocks: string;
  commodities: string;
  forex: string;
  etfs: string;
  indexes: string;
  bonds: string;
  mutualFunds: string;
  superCombo: string;
  pros: string;
  cons: string;
  withdraw: string;
  hours: string;
  days: string;
  weeks: string;
  months: string;
  years: string;
  confidence: string;
  strategy: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  riskIndex: string;
  highlyStable: string;
  moderatelyStable: string;
  moderatelyRisky: string;
  highlyRisky: string;
  horizon: string;
  lowRiskHint: string;
  highRiskHint: string;
  scanPrompt: string;
  confShort: string;
  clear: string;
  confirmClear: string;
  autoRisk: string;
  precise: string;
  calendar: string;
  startDate: string;
  endDate: string;
  portfolioAllocation: string;
  // Search related
  tabPredictor: string;
  tabSearch: string;
  tabMatrix: string;
  searchPlaceholder: string;
  searchButton: string;
  matrixTitle: string;
  matrixDesc: string;
  correlationHigh: string;
  correlationInverse: string;
  correlationNeutral: string;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, CorrelationData } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData, fetchMarketCorrelations } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, BarChart2, Radio, Grid3X3 } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [correlationData, setCorrelationData] = useState<CorrelationData[]>([]);

  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [isAutoRisk, setIsAutoRisk] = useState(false);
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  useEffect(() => {
    if (isAutoRisk) {
      let autoScore = 50;
      if (totalHours < 24) autoScore = 85;
      else if (totalHours < 168) autoScore = 65;
      else if (totalHours < 720) autoScore = 25;
      else if (totalHours < 43800) autoScore = 50;
      else autoScore = 90;
      setRiskScore(autoScore);
    }
  }, [totalHours, isAutoRisk]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally {
      setTickerLoading(false);
    }
  }, []);

  // Poll Google Finance every 60 seconds
  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const marketContextString = useMemo(() => 
    tickerData.map(i => `${i.symbol}: ${i.price} (${i.change})`).join(', '),
    [tickerData]
  );

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const safeHours = totalHours === 0 ? 168 : totalHours; 
    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang, marketContextString);
      setPredictorResults(results);
    } finally {
      setLoading(false);
    }
  }, [totalHours, riskScore, type, lang, marketContextString]);

  const handleSearch = useCallback(async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally {
      setLoading(false);
    }
  }, [searchQuery, lang]);

  const handleClear = () => {
    if (viewMode === 'matrix') {
      setCorrelationData([]);
      loadCorrelations();
      return;
    }
    if (activePredictions.length === 0) return;
    if (window.confirm(t.confirmClear)) {
      viewMode === 'predict' ? setPredictorResults([]) : setSearchResults([]);
    }
  };

  const loadCorrelations = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchMarketCorrelations();
      setCorrelationData(data);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (viewMode === 'matrix' && correlationData.length === 0) loadCorrelations();
  }, [viewMode, correlationData.length, loadCorrelations]);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden bg-broker-bg">
      <div className="fixed inset-0 bg-[#242325] z-0" />

      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">REAL-TIME QUANTUM BROKER</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          <div className="glass-panel border border-broker-pink/30 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)] overflow-hidden flex flex-col">
            <div className="flex border-b border-white/10">
              <button 
                onClick={() => setViewMode('predict')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'predict' ? 'bg-broker-pink/20 text-broker-pink border-b-2 border-broker-pink' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Radio size={18} /> {t.tabPredictor}
              </button>
              <button 
                onClick={() => setViewMode('search')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan border-b-2 border-broker-cyan' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Search size={18} /> {t.tabSearch}
              </button>
              <button 
                onClick={() => setViewMode('matrix')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'matrix' ? 'bg-broker-green/20 text-broker-green border-b-2 border-broker-green' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Grid3X3 size={18} /> {t.tabMatrix}
              </button>
            </div>

            <div className="p-8">
              {viewMode === 'predict' && (
                <MotionDiv initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key="predict">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2 uppercase">
                          {horizonMode === 'precise' ? <Clock size={16} /> : <Calendar size={16} />} 
                          {t.strategy} / {t.horizon}
                        </label>
                        <button 
                          onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')}
                          className="text-[9px] font-black tracking-widest uppercase px-3 py-1 bg-white/5 border border-white/10 hover:bg-white/10 transition-colors flex items-center gap-2"
                        >
                          <SwitchCamera size={10} /> {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>

                      <div className="h-20 flex items-center">
                        {horizonMode === 'precise' ? (
                          <div className="grid grid-cols-5 gap-2 w-full">
                            {[{ k: 'h', l: t.hours }, { k: 'd', l: t.days }, { k: 'w', l: t.weeks }, { k: 'm', l: t.months }, { k: 'y', l: t.years }].map(({k, l}) => (
                              <div key={k} className="relative">
                                <input 
                                  type="number" 
                                  min="0"
                                  placeholder="0"
                                  value={(time as any)[k] || ''}
                                  onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                                  className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none text-broker-light"
                                />
                                <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                              </div>
                            ))}
                          </div>
                        ) : (
                          <div className="grid grid-cols-2 gap-4 w-full">
                            <div className="relative">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase">{t.startDate}</label>
                              <input 
                                type="date"
                                value={dates.start}
                                onChange={(e) => setDates({...dates, start: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light"
                              />
                            </div>
                            <div className="relative">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase">{t.endDate}</label>
                              <input 
                                type="date"
                                value={dates.end}
                                onChange={(e) => setDates({...dates, end: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light"
                              />
                            </div>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-6">
                      <div className="relative">
                        <div className="flex justify-between items-center mb-4">
                          <div className="flex items-center gap-4">
                            <label className="text-sm font-bold text-broker-cyan tracking-wider block uppercase">{t.riskIndex}</label>
                            <button 
                              onClick={() => setIsAutoRisk(!isAutoRisk)}
                              className={`text-[9px] font-black tracking-widest uppercase px-3 py-1 transition-all ${isAutoRisk ? 'bg-broker-green text-black' : 'bg-white/5 border border-white/10 text-gray-400'}`}
                            >
                              {t.autoRisk}
                            </button>
                          </div>
                          <div className={`flex items-center gap-2 font-mono text-xs font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                            {riskCat.icon} {riskCat.label} ({riskScore})
                          </div>
                        </div>
                        <input 
                          type="range" 
                          min="0" max="100" step="1"
                          disabled={isAutoRisk}
                          value={riskScore} 
                          onChange={(e) => setRiskScore(parseInt(e.target.value))}
                          className="w-full h-2 bg-gradient-to-r from-broker-green via-broker-cyan to-broker-red appearance-none sharp-edge cursor-pointer" 
                        />
                      </div>
                      <select 
                        value={type}
                        onChange={(e) => setType(e.target.value as MarketType)}
                        className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer"
                      >
                        <option value={MarketType.GENERAL}>{t.general}</option>
                        <option value={MarketType.SUPER_COMBO}>{t.superCombo}</option>
                        <option value={MarketType.CRYPTO}>{t.crypto}</option>
                        <option value={MarketType.STOCKS}>{t.stocks}</option>
                        <option value={MarketType.FOREX}>{t.forex}</option>
                        <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                        <option value={MarketType.ETFS}>{t.etfs}</option>
                        <option value={MarketType.INDEXES}>{t.indexes}</option>
                        <option value={MarketType.BONDS}>{t.bonds}</option>
                        <option value={MarketType.MUTUAL_FUNDS}>{t.mutualFunds}</option>
                      </select>
                    </div>
                  </div>

                  <button 
                    onClick={handlePredict}
                    disabled={loading}
                    className="w-full mt-8 py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 disabled:opacity-50 flex justify-center items-center gap-3"
                  >
                    {loading ? <Settings size={24} className="animate-spin" /> : <BrainCircuit size={24} />}
                    {loading ? t.loading : t.predict}
                  </button>
                </MotionDiv>
              )}

              {viewMode === 'search' && (
                <div className="flex flex-col gap-6">
                  <div className="relative">
                    <Search className="absolute top-1/2 left-4 -translate-y-1/2 text-broker-cyan" size={24} />
                    <input 
                      type="text" value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                      placeholder={t.searchPlaceholder}
                      className="w-full bg-[#1a1a1b] border-2 border-broker-cyan/30 focus:border-broker-cyan text-xl p-6 pl-14 sharp-edge outline-none font-mono text-broker-light"
                    />
                  </div>
                  <button 
                    onClick={handleSearch}
                    disabled={loading || !searchQuery.trim()}
                    className="w-full py-5 bg-gradient-to-r from-broker-cyan to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge flex justify-center items-center gap-3"
                  >
                    {loading ? <Settings size={24} className="animate-spin" /> : <Search size={24} />}
                    {t.searchButton}
                  </button>
                </div>
              )}

              {viewMode === 'matrix' && <CorrelationHeatmap data={correlationData} t={t} />}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={`${idx}-${lang}`} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Prediction, Translation } from '../types';
import { Activity, AlertTriangle, TrendingUp, Clock, Target, ShieldAlert, Scale, PieChart, Star } from 'lucide-react';
import SmartText from './SmartText';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
}

const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index }) => {
  const typeLower = data.type.toLowerCase();
  const isCrypto = typeLower.includes('crypto');
  const isStock = typeLower.includes('stock');
  const isETF = typeLower.includes('etf');
  const isIndex = typeLower.includes('index');
  const isCommodity = typeLower.includes('commodity');
  const isForex = typeLower.includes('forex') || typeLower.includes('currency') || typeLower.includes('divisa');
  const isSuperCombo = typeLower.includes('super combo') || typeLower.includes('combo') || !!data.holdings;

  let accentColor = 'text-broker-pink';
  let borderColor = 'border-broker-pink';
  let bgGradient = 'hover:bg-black/60';
  let displayType = data.type;

  if (isSuperCombo) {
    // Luxe / Premium Styling for COMBO
    accentColor = 'text-amber-400';
    borderColor = 'border-amber-400';
    bgGradient = 'hover:bg-amber-900/10 bg-gradient-to-br from-amber-500/5 to-transparent';
    displayType = t.superCombo;
  } else if (isCrypto) {
    accentColor = 'text-broker-purple';
    borderColor = 'border-broker-purple';
    displayType = t.crypto;
  } else if (isETF) {
    accentColor = 'text-broker-cyan';
    borderColor = 'border-broker-cyan';
    displayType = t.etfs;
  } else if (isStock) {
    accentColor = 'text-broker-cyan';
    borderColor = 'border-broker-cyan';
    displayType = t.stocks;
  } else if (isIndex) {
    accentColor = 'text-broker-green';
    borderColor = 'border-broker-green';
    displayType = t.indexes;
  } else if (isCommodity) {
    accentColor = 'text-broker-pink';
    borderColor = 'border-broker-pink';
    displayType = t.commodities;
  } else if (isForex) {
    accentColor = 'text-emerald-400';
    borderColor = 'border-emerald-400';
    displayType = t.forex;
  }

  return (
    <MotionDiv
      initial={{ opacity: 0, y: 15 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.08 }}
      className={`glass-panel border-l-4 ${borderColor}/40 p-6 sharp-edge relative overflow-hidden group ${bgGradient} transition-all duration-300 shadow-xl border-r border-t border-b border-white/5 ${isSuperCombo ? 'border-amber-500/20 shadow-[0_0_20px_rgba(245,158,11,0.1)]' : ''}`}
    >
      <div className="flex justify-between items-start mb-6">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className={`text-[9px] font-black px-2 py-0.5 bg-black/40 ${accentColor} uppercase tracking-[0.2em] ${isSuperCombo ? 'bg-amber-400 text-black shadow-[0_0_10px_rgba(245,158,11,0.5)]' : ''}`}>
              {displayType}
            </span>
            <span className="text-[9px] text-gray-400 font-black tracking-widest uppercase">{t.confShort}: {data.confidence}%</span>
          </div>
          <h3 className={`text-2xl font-black italic leading-tight uppercase tracking-tight ${isSuperCombo ? 'text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-amber-400 to-amber-600 drop-shadow-[0_0_5px_rgba(245,158,11,0.3)]' : 'text-broker-light'}`}>{data.name}</h3>
          <p className="text-lg text-gray-400 font-mono tracking-[0.1em] font-bold">{data.ticker}</p>
        </div>
        <div className={`bg-black/40 p-3 sharp-edge border border-white/5 ${isSuperCombo ? 'border-amber-500/30 shadow-[0_0_10px_rgba(245,158,11,0.2)]' : ''}`}>
          {isSuperCombo ? <Star className="text-amber-400 fill-amber-400/20 animate-pulse" size={24} /> : <Activity className={`${accentColor} opacity-70`} size={24} />}
        </div>
      </div>

      {isSuperCombo && data.holdings && (
        <div className="mb-6 p-4 bg-amber-500/5 sharp-edge border border-amber-500/20 space-y-4">
          <div className="flex items-center gap-2 text-[10px] font-black tracking-widest text-amber-200 uppercase opacity-80 mb-2">
            <PieChart size={12} /> {t.portfolioAllocation}
          </div>
          {data.holdings.map((h, i) => (
            <div key={i} className="space-y-1">
              <div className="flex justify-between text-[11px] font-mono">
                <span className="text-amber-100 font-bold">{h.name} <span className="text-amber-500/60 text-[10px]">({h.ticker})</span></span>
                <span className="text-amber-200">{h.weight}%</span>
              </div>
              <div className="w-full h-1 bg-amber-900/30 overflow-hidden">
                <MotionDiv 
                  initial={{ width: 0 }}
                  animate={{ width: `${h.weight}%` }}
                  className="h-full bg-amber-400"
                  transition={{ delay: 0.5 + (i * 0.1), duration: 1 }}
                />
              </div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 mb-6">
        <div className={`bg-black/40 p-3 sharp-edge border border-broker-green/30 group-hover:border-broker-green/60 transition-colors ${isSuperCombo ? 'border-amber-500/20 hover:border-amber-500/50' : ''}`}>
          <div className="flex items-center gap-2 text-broker-green font-black mb-1 tracking-widest uppercase text-[9px]">
            <Target size={11} /> {t.expectedProfit}
          </div>
          <div className="text-xl font-mono font-bold text-broker-light">{data.expectedProfit}</div>
        </div>
        <div className={`bg-black/40 p-3 sharp-edge border border-broker-red/30 group-hover:border-broker-red/60 transition-colors ${isSuperCombo ? 'border-amber-500/20 hover:border-amber-500/50' : ''}`}>
          <div className="flex items-center gap-2 text-broker-red font-black mb-1 tracking-widest uppercase text-[9px]">
            <ShieldAlert size={11} /> {t.expectedLoss}
          </div>
          <div className="text-xl font-mono font-bold text-broker-light">{data.expectedLoss}</div>
        </div>
        <div className={`bg-black/40 p-3 sharp-edge border border-broker-cyan/30 group-hover:border-broker-cyan/60 transition-colors ${isSuperCombo ? 'border-amber-500/20 hover:border-amber-500/50' : ''}`}>
          <div className="flex items-center gap-2 text-broker-cyan font-black mb-1 tracking-widest uppercase text-[9px]">
            <Scale size={11} /> {t.riskRewardRatio}
          </div>
          <div className="text-xl font-mono font-bold text-broker-light">{data.riskRewardRatio}</div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-6 text-sm">
        <div className="bg-black/20 p-4 sharp-edge border-l-2 border-broker-green/40">
          <h4 className="text-broker-green font-black mb-3 flex items-center gap-2 text-[10px] tracking-[0.2em] uppercase opacity-80">
            <TrendingUp size={13} /> {t.pros}
          </h4>
          <ul className="space-y-2">
            {data.pros.map((p, i) => (
              <li key={i} className="text-gray-400 text-[11px] font-mono leading-relaxed">
                • <SmartText text={p} />
              </li>
            ))}
          </ul>
        </div>
        <div className="bg-black/20 p-4 sharp-edge border-l-2 border-broker-red/40">
          <h4 className="text-broker-red font-black mb-3 flex items-center gap-2 text-[10px] tracking-[0.2em] uppercase opacity-80">
            <AlertTriangle size={13} /> {t.cons}
          </h4>
          <ul className="space-y-2">
            {data.cons.map((c, i) => (
              <li key={i} className="text-gray-400 text-[11px] font-mono leading-relaxed">
                • <SmartText text={c} />
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div className="mt-6 pt-4 border-t border-white/5 flex items-center justify-between text-broker-light font-mono text-[9px] tracking-[0.3em] uppercase font-black">
        <span className="flex items-center gap-2 opacity-60">
            <Clock size={12} /> {t.withdraw}
        </span>
        <span className={`bg-black/40 px-4 py-1 sharp-edge border border-white/5 ${isSuperCombo ? 'text-amber-400 border-amber-500/30' : 'text-broker-light'}`}>{data.withdraw}</span>
      </div>

      <div className={`absolute top-0 right-0 w-32 h-full bg-gradient-to-l from-white/2 to-transparent skew-x-12 translate-x-16 group-hover:translate-x-0 transition-transform duration-700 ease-out pointer-events-none opacity-10 ${isSuperCombo ? 'from-amber-400/10' : ''}`} />
    </MotionDiv>
  );
};

export default PredictionCard;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, CorrelationData } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData, fetchMarketCorrelations } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, BarChart2, Radio, Grid3X3 } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [correlationData, setCorrelationData] = useState<CorrelationData[]>([]);

  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [isAutoRisk, setIsAutoRisk] = useState(false);
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  useEffect(() => {
    if (isAutoRisk) {
      let autoScore = 50;
      if (totalHours < 24) autoScore = 85;
      else if (totalHours < 168) autoScore = 65;
      else if (totalHours < 720) autoScore = 25;
      else if (totalHours < 43800) autoScore = 50;
      else autoScore = 90;
      setRiskScore(autoScore);
    }
  }, [totalHours, isAutoRisk]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally {
      setTickerLoading(false);
    }
  }, []);

  // Poll Google Finance every 60 seconds
  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const marketContextString = useMemo(() => 
    tickerData.map(i => `${i.symbol}: ${i.price} (${i.change})`).join(', '),
    [tickerData]
  );

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const safeHours = totalHours === 0 ? 168 : totalHours; 
    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang, marketContextString);
      setPredictorResults(results);
    } finally {
      setLoading(false);
    }
  }, [totalHours, riskScore, type, lang, marketContextString]);

  const handleSearch = useCallback(async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally {
      setLoading(false);
    }
  }, [searchQuery, lang]);

  const handleClear = () => {
    if (viewMode === 'matrix') {
      setCorrelationData([]);
      loadCorrelations();
      return;
    }
    if (activePredictions.length === 0) return;
    if (window.confirm(t.confirmClear)) {
      viewMode === 'predict' ? setPredictorResults([]) : setSearchResults([]);
    }
  };

  const loadCorrelations = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchMarketCorrelations();
      setCorrelationData(data);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (viewMode === 'matrix' && correlationData.length === 0) loadCorrelations();
  }, [viewMode, correlationData.length, loadCorrelations]);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden bg-broker-bg">
      <div className="fixed inset-0 bg-[#242325] z-0" />

      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="p-8 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={40} className="text-broker-pink" />
            <div>
              <h1 className="text-3xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-xs font-mono text-broker-cyan/60 tracking-widest">REAL-TIME QUANTUM BROKER</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             <div className="relative group">
                <Globe size={20} className="text-broker-cyan" />
                <select 
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)}
                  className="absolute inset-0 opacity-0 cursor-pointer"
                >
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
             <span className="text-sm font-mono text-broker-cyan font-bold">{lang.toUpperCase()}</span>
          </div>
        </header>

        <main className="flex-grow container mx-auto px-4 pb-20 max-w-5xl">

          <div className="glass-panel border border-broker-pink/30 sharp-edge mb-12 shadow-[0_0_40px_rgba(243,27,128,0.1)] overflow-hidden flex flex-col">
            <div className="flex border-b border-white/10">
              <button 
                onClick={() => setViewMode('predict')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'predict' ? 'bg-broker-pink/20 text-broker-pink border-b-2 border-broker-pink' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Radio size={18} /> {t.tabPredictor}
              </button>
              <button 
                onClick={() => setViewMode('search')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan border-b-2 border-broker-cyan' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Search size={18} /> {t.tabSearch}
              </button>
              <button 
                onClick={() => setViewMode('matrix')}
                className={`flex-1 py-4 flex items-center justify-center gap-2 font-black italic tracking-widest transition-all ${viewMode === 'matrix' ? 'bg-broker-green/20 text-broker-green border-b-2 border-broker-green' : 'hover:bg-white/5 text-gray-500'}`}
              >
                <Grid3X3 size={18} /> {t.tabMatrix}
              </button>
            </div>

            <div className="p-8">
              {viewMode === 'predict' && (
                <MotionDiv initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key="predict">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <label className="text-sm font-bold text-broker-cyan tracking-wider flex items-center gap-2 uppercase">
                          {horizonMode === 'precise' ? <Clock size={16} /> : <Calendar size={16} />} 
                          {t.strategy} / {t.horizon}
                        </label>
                        <button 
                          onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')}
                          className="text-[9px] font-black tracking-widest uppercase px-3 py-1 bg-white/5 border border-white/10 hover:bg-white/10 transition-colors flex items-center gap-2"
                        >
                          <SwitchCamera size={10} /> {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>

                      <div className="h-20 flex items-center">
                        {horizonMode === 'precise' ? (
                          <div className="grid grid-cols-5 gap-2 w-full">
                            {[{ k: 'h', l: t.hours }, { k: 'd', l: t.days }, { k: 'w', l: t.weeks }, { k: 'm', l: t.months }, { k: 'y', l: t.years }].map(({k, l}) => (
                              <div key={k} className="relative">
                                <input 
                                  type="number" 
                                  min="0"
                                  placeholder="0"
                                  value={(time as any)[k] || ''}
                                  onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})}
                                  className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 focus:border-broker-pink text-center py-3 text-lg font-mono sharp-edge outline-none text-broker-light"
                                />
                                <span className="absolute top-0 right-1 text-[10px] text-gray-500 font-mono">{l}</span>
                              </div>
                            ))}
                          </div>
                        ) : (
                          <div className="grid grid-cols-2 gap-4 w-full">
                            <div className="relative">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase">{t.startDate}</label>
                              <input 
                                type="date"
                                value={dates.start}
                                onChange={(e) => setDates({...dates, start: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light"
                              />
                            </div>
                            <div className="relative">
                              <label className="absolute -top-4 left-0 text-[10px] text-gray-500 font-mono uppercase">{t.endDate}</label>
                              <input 
                                type="date"
                                value={dates.end}
                                onChange={(e) => setDates({...dates, end: e.target.value})}
                                className="w-full bg-[#1a1a1b] border-b-2 border-broker-cyan/30 text-left px-4 py-3 text-sm font-mono sharp-edge outline-none text-broker-light"
                              />
                            </div>
                          </div>
                        )}
                      </div>
                    </div>

                    <div className="space-y-6">
                      <div className="relative">
                        <div className="flex justify-between items-center mb-4">
                          <div className="flex items-center gap-4">
                            <label className="text-sm font-bold text-broker-cyan tracking-wider block uppercase">{t.riskIndex}</label>
                            <button 
                              onClick={() => setIsAutoRisk(!isAutoRisk)}
                              className={`text-[9px] font-black tracking-widest uppercase px-3 py-1 transition-all ${isAutoRisk ? 'bg-broker-green text-black' : 'bg-white/5 border border-white/10 text-gray-400'}`}
                            >
                              {t.autoRisk}
                            </button>
                          </div>
                          <div className={`flex items-center gap-2 font-mono text-xs font-bold ${riskCat.color} bg-black/40 px-3 py-1 sharp-edge border border-current/20`}>
                            {riskCat.icon} {riskCat.label} ({riskScore})
                          </div>
                        </div>

                        {/* CUSTOM SLIDER */}
                        <div className="relative w-full h-6 flex items-center">
                          <div className="absolute left-0 right-0 h-[2px] bg-gradient-to-r from-broker-green via-broker-cyan to-broker-red top-1/2 -translate-y-1/2"></div>
                          <input 
                            type="range" 
                            min="0" max="100" step="1"
                            disabled={isAutoRisk}
                            value={riskScore} 
                            onChange={(e) => setRiskScore(parseInt(e.target.value))}
                            className={`w-full h-full bg-transparent appearance-none cursor-pointer relative z-10 outline-none ${isAutoRisk ? 'opacity-30 cursor-not-allowed' : ''}`} 
                          />
                        </div>

                        <div className="flex justify-between text-[10px] font-mono text-gray-400 uppercase tracking-widest font-bold mt-2">
                          <span>{t.lowRiskHint}</span>
                          <span>{t.highRiskHint}</span>
                        </div>
                      </div>
                      <select 
                        value={type}
                        onChange={(e) => setType(e.target.value as MarketType)}
                        className="w-full bg-[#1a1a1b] border border-broker-purple text-broker-light p-4 sharp-edge outline-none font-mono text-sm uppercase tracking-wider cursor-pointer"
                      >
                        <option value={MarketType.GENERAL}>{t.general}</option>
                        <option value={MarketType.SUPER_COMBO}>{t.superCombo}</option>
                        <option value={MarketType.CRYPTO}>{t.crypto}</option>
                        <option value={MarketType.STOCKS}>{t.stocks}</option>
                        <option value={MarketType.FOREX}>{t.forex}</option>
                        <option value={MarketType.COMMODITIES}>{t.commodities}</option>
                        <option value={MarketType.ETFS}>{t.etfs}</option>
                        <option value={MarketType.INDEXES}>{t.indexes}</option>
                        <option value={MarketType.BONDS}>{t.bonds}</option>
                        <option value={MarketType.MUTUAL_FUNDS}>{t.mutualFunds}</option>
                      </select>
                    </div>
                  </div>

                  <button 
                    onClick={handlePredict}
                    disabled={loading}
                    className="w-full mt-8 py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge hover:opacity-90 disabled:opacity-50 flex justify-center items-center gap-3"
                  >
                    {loading ? <Settings size={24} className="animate-spin" /> : <BrainCircuit size={24} />}
                    {loading ? t.loading : t.predict}
                  </button>
                </MotionDiv>
              )}

              {viewMode === 'search' && (
                <div className="flex flex-col gap-6">
                  <div className="relative">
                    <Search className="absolute top-1/2 left-4 -translate-y-1/2 text-broker-cyan" size={24} />
                    <input 
                      type="text" value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                      placeholder={t.searchPlaceholder}
                      className="w-full bg-[#1a1a1b] border-2 border-broker-cyan/30 focus:border-broker-cyan text-xl p-6 pl-14 sharp-edge outline-none font-mono text-broker-light"
                    />
                  </div>
                  <button 
                    onClick={handleSearch}
                    disabled={loading || !searchQuery.trim()}
                    className="w-full py-5 bg-gradient-to-r from-broker-cyan to-broker-purple text-white font-black italic text-xl tracking-widest sharp-edge flex justify-center items-center gap-3"
                  >
                    {loading ? <Settings size={24} className="animate-spin" /> : <Search size={24} />}
                    {t.searchButton}
                  </button>
                </div>
              )}

              {viewMode === 'matrix' && <CorrelationHeatmap data={correlationData} t={t} />}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={`${idx}-${lang}`} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>

      <Dictionary />

      <style>{`
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
          margin-top: 0px; 
        }
        input[type=range]::-moz-range-thumb {
          height: 12px;
          width: 12px;
          background: #FFFFFF;
          cursor: pointer;
          border: none;
          transform: rotate(45deg);
          box-shadow: 0 0 10px rgba(255, 255, 255, 0.8);
          position: relative;
          z-index: 20;
        }
        input[type=range]::-webkit-slider-runnable-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #F31B80;
          border-radius: 0px;
        }
      `}</style>
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, CorrelationData } from "../types";

const getSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING },
      expectedLoss: { type: Type.STRING },
      riskRewardRatio: { type: Type.STRING },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER },
          },
        },
      },
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
  },
});

const getTickerSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING },
      price: { type: Type.STRING },
      change: { type: Type.STRING },
      isUp: { type: Type.BOOLEAN },
    },
    required: ["symbol", "price", "change", "isUp"],
  },
});

const isRateLimitError = (error: any) => {
  const msg = error?.message || error?.toString() || '';
  return error?.status === 429 || msg.includes('429') || msg.includes('RESOURCE_EXHAUSTED');
};

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      Retrieve the ABSOLUTE CURRENT REAL-TIME PRICE and 24h CHANGE for these global benchmarks using Google Search:
      - S&P 500 (INDEXSP: .INX)
      - NASDAQ 100 (INDEXNASDAQ: NDX)
      - Bitcoin (BTC-USD)
      - Ethereum (ETH-USD)
      - Gold (GC=F)
      - NVIDIA (NASDAQ: NVDA)
      - Tesla (NASDAQ: TSLA)
      - US 10Y Yield (TNX)

      SOURCE MANDATE: Specifically extract data from GOOGLE FINANCE (google.com/finance).
      Return exactly 8 items in a JSON array.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a high-speed data scraper connected to Google Finance. Return only raw numbers and symbols from live search results.",
        responseMimeType: "application/json",
        responseSchema: getTickerSchema(),
      },
    });

    const data = JSON.parse(response.text || '[]');
    if (Array.isArray(data) && data.length > 0) return data as TickerItem[];
    return MOCK_TICKER_DATA;
  } catch (error: any) {
    if (isRateLimitError(error)) {
      console.warn("Gemini Rate Limit (429) hit for Ticker. Using fallback data.");
      return MOCK_TICKER_DATA;
    }
    console.error("Live Sync Error:", error);
    return MOCK_TICKER_DATA;
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  currentMarketContext?: string
): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const horizon = totalHours < 168 ? "short" : totalHours < 8760 ? "medium" : "long";

    const prompt = `
      [DEEP THINKING + GOOGLE FINANCE SYNC]
      Market Context: ${currentMarketContext || 'Fetching live benchmarks...'}
      User Goal: ${horizon} term analysis, Risk Score ${riskScore}/100, Focus: ${type}.
      Output Lang: ${lang}.

      Task: Use Google Search to cross-reference current Google Finance data. 
      Analyze the assets above and find the 5 best opportunities matching the user risk profile.
      Calculate Expected Profit and Stop Loss based on the CURRENT LIVE PRICE found in search.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 },
        responseSchema: getSchema(),
      },
    });

    return JSON.parse(response.text || '[]') as Prediction[];
  } catch (error: any) {
    if (isRateLimitError(error)) {
      console.warn("Gemini Rate Limit (429) hit for Predictions.");
      // Return empty to allow UI to show specific error if needed, or handle gracefully
      return [];
    }
    console.error("Prediction Sync Error:", error);
    return [];
  }
};

export const searchAssets = async (query: string, lang: string): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Search Google Finance for: ${query}. Analyze this asset for a ${lang} speaking user.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 },
        responseSchema: getSchema(),
      },
    });
    return JSON.parse(response.text || '[]') as Prediction[];
  } catch (error) {
    if (isRateLimitError(error)) console.warn("Gemini Rate Limit (429) hit for Search.");
    return [];
  }
};

export const fetchMarketCorrelations = async (): Promise<CorrelationData[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: "Analyze current 30-day correlations between BTC, GOLD, SPX, NDX, DXY using live Google Finance data.",
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              assetA: { type: Type.STRING },
              assetB: { type: Type.STRING },
              correlation: { type: Type.NUMBER },
            },
            required: ["assetA", "assetB", "correlation"],
          },
        },
      },
    });
    return JSON.parse(response.text || '[]') as CorrelationData[];
  } catch (error) {
    if (isRateLimitError(error)) console.warn("Gemini Rate Limit (429) hit for Correlations.");
    return [];
  }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, CorrelationData } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData, fetchMarketCorrelations } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, BarChart2, Radio, Grid3X3 } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [correlationData, setCorrelationData] = useState<CorrelationData[]>([]);

  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
