import { GoogleGenAI, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, CorrelationData } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v1';
const TICKER_CACHE_TTL = 10 * 60 * 1000; // 10 Minutes

const getSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING },
      expectedLoss: { type: Type.STRING },
      riskRewardRatio: { type: Type.STRING },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER },
          },
        },
      },
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
  },
});

const getTickerSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING },
      price: { type: Type.STRING },
      change: { type: Type.STRING },
      isUp: { type: Type.BOOLEAN },
    },
    required: ["symbol", "price", "change", "isUp"],
  },
});

const isRateLimitError = (error: any) => {
  const msg = error?.message || error?.toString() || '';
  return error?.status === 429 || msg.includes('429') || msg.includes('RESOURCE_EXHAUSTED') || msg.includes('Quota exceeded');
};

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  // 1. Try to load from Cache first to prevent 429s on reload
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  let cachedFallback: TickerItem[] | null = null;

  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      cachedFallback = data; // Save stale data for fallback

      // If cache is fresh (less than 10 mins old), use it
      if (Date.now() - timestamp < TICKER_CACHE_TTL) {
        // console.log("Using cached ticker data");
        return data;
      }
    } catch (e) {
      localStorage.removeItem(TICKER_CACHE_KEY);
    }
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `
      Retrieve CURRENT PRICE and 24h CHANGE % for:
      S&P 500, NASDAQ 100, BTC-USD, ETH-USD, Gold (XAU), NVDA, TSLA, US 10Y Yield.
      Source: Google Finance.
      Return JSON array of 8 items.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a data scraper. Return raw numbers.",
        responseMimeType: "application/json",
        responseSchema: getTickerSchema(),
      },
    });

    const data = JSON.parse(response.text || '[]');

    if (Array.isArray(data) && data.length > 0) {
      // Save to cache
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({
        timestamp: Date.now(),
        data: data
      }));
      return data as TickerItem[];
    }

    // If API returned empty, try fallback
    return cachedFallback || MOCK_TICKER_DATA;

  } catch (error: any) {
    if (isRateLimitError(error)) {
      console.warn("Gemini Rate Limit (429) hit for Ticker. Using cached/fallback data.");
      // Return stale cache if available, otherwise mock
      return cachedFallback || MOCK_TICKER_DATA;
    }
    console.error("Live Sync Error:", error);
    return cachedFallback || MOCK_TICKER_DATA;
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  currentMarketContext?: string
): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const horizon = totalHours < 168 ? "short" : totalHours < 8760 ? "medium" : "long";

    const prompt = `
      [DEEP THINKING + GOOGLE FINANCE SYNC]
      Market Context: ${currentMarketContext || 'Fetching live benchmarks...'}
      User Goal: ${horizon} term analysis, Risk Score ${riskScore}/100, Focus: ${type}.
      Output Lang: ${lang}.

      Task: Use Google Search to cross-reference current Google Finance data. 
      Analyze the assets above and find the 5 best opportunities matching the user risk profile.
      Calculate Expected Profit and Stop Loss based on the CURRENT LIVE PRICE found in search.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 },
        responseSchema: getSchema(),
      },
    });

    return JSON.parse(response.text || '[]') as Prediction[];
  } catch (error: any) {
    if (isRateLimitError(error)) {
      console.warn("Gemini Rate Limit (429) hit for Predictions.");
      // Return empty to allow UI to show specific error if needed, or handle gracefully
      return [];
    }
    console.error("Prediction Sync Error:", error);
    return [];
  }
};

