import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, CorrelationData } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData, fetchMarketCorrelations } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, BarChart2, Radio, Grid3X3, Activity } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [correlationData, setCorrelationData] = useState<CorrelationData[]>([]);

  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [isAutoRisk, setIsAutoRisk] = useState(false);
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  useEffect(() => {
    if (isAutoRisk) {
      let autoScore = 50;
      if (totalHours < 24) autoScore = 85;
      else if (totalHours < 168) autoScore = 65;
      else if (totalHours < 720) autoScore = 25;
      else if (totalHours < 43800) autoScore = 50;
      else autoScore = 90;
      setRiskScore(autoScore);
    }
  }, [totalHours, isAutoRisk]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally {
      setTickerLoading(false);
    }
  }, []);

  // Poll Google Finance every 1 minute (60000ms)
  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const marketContextString = useMemo(() => 
    tickerData.map(i => `${i.symbol}: ${i.price} (${i.change})`).join(', '),
    [tickerData]
  );

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const safeHours = totalHours === 0 ? 168 : totalHours; 
    try {
      const results = await fetchPredictions(safeHours, riskScore, type, lang, marketContextString);
      setPredictorResults(results);
    } finally {
      setLoading(false);
    }
  }, [totalHours, riskScore, type, lang, marketContextString]);

  const handleSearch = useCallback(async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally {
      setLoading(false);
    }
  }, [searchQuery, lang]);

  const handleClear = () => {
    if (viewMode === 'matrix') {
      setCorrelationData([]);
      return;
    }
    if (activePredictions.length === 0) return;
    if (window.confirm(t.confirmClear)) {
      viewMode === 'predict' ? setPredictorResults([]) : setSearchResults([]);
    }
  };

  const loadCorrelations = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchMarketCorrelations();
      setCorrelationData(data);
    } finally {
      setLoading(false);
    }
  }, []);

  const getRiskCategory = (score: number) => {
    if (score <= 25) return { label: t.highlyStable, color: 'text-broker-green', icon: <ShieldCheck size={18} /> };
    if (score <= 50) return { label: t.moderatelyStable, color: 'text-broker-cyan', icon: <Zap size={18} /> };
    if (score <= 75) return { label: t.moderatelyRisky, color: 'text-broker-pink', icon: <AlertTriangle size={18} /> };
    return { label: t.highlyRisky, color: 'text-broker-red', icon: <Flame size={18} /> };
  };

  const riskCat = getRiskCategory(riskScore);

  return (
    <div className="min-h-screen relative font-sans text-broker-text overflow-x-hidden bg-broker-bg">
