              <button onClick={() => setViewMode('search')} className={`flex-1 py-3 text-xs font-black tracking-widest uppercase transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan' : 'text-gray-500'}`}>
                {t.tabSearch}
              </button>
              <button onClick={() => setViewMode('matrix')} className={`flex-1 py-3 text-xs font-black tracking-widest uppercase transition-all ${viewMode === 'matrix' ? 'bg-broker-green/20 text-broker-green' : 'text-gray-500'}`}>
                {t.tabMatrix}
              </button>
            </div>

            <div className="p-6">
              {viewMode === 'predict' && (
                <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
