                      <div className="flex justify-between items-center text-[10px] font-black tracking-widest uppercase text-broker-cyan">
                        <span><Clock size={12} className="inline mr-2" /> {t.horizon}</span>
                        <button onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} className="hover:text-white transition-colors">
