      </div>

      {isCombo && data.holdings && (
        <div className="bg-amber-400/5 p-3 border border-amber-400/20 space-y-2">
          <div className="flex items-center gap-2 text-[8px] font-black text-amber-200 uppercase tracking-widest opacity-60">
            <PieChart size={10} /> {t.portfolioAllocation} // POSITIVE CORRELATION PACK
          </div>
          <div className="flex gap-2">
            {data.holdings.map((h, i) => (
              <div key={i} className="flex-1 text-center bg-black/20 p-2 border border-white/5">
                <div className="text-[9px] font-black text-amber-100 uppercase truncate">{h.name}</div>
                <div className="text-[8px] font-mono text-amber-400/60">{h.weight}%</div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="bg-black/40 p-3 border border-broker-green/20">
          <div className="text-[8px] font-black text-broker-green uppercase mb-1 flex items-center gap-1"><Target size={10}/> {t.expectedProfit}</div>
          <div className="text-md font-mono font-bold text-broker-light">{data.expectedProfit}</div>
        </div>
        <div className="bg-black/40 p-3 border border-broker-red/20">
          <div className="text-[8px] font-black text-broker-red uppercase mb-1 flex items-center gap-1"><ShieldAlert size={10}/> {t.expectedLoss}</div>
          <div className="text-md font-mono font-bold text-broker-light">{data.expectedLoss}</div>
        </div>
        <div className="bg-black/40 p-3 border border-broker-cyan/20">
          <div className="text-[8px] font-black text-broker-cyan uppercase mb-1 flex items-center gap-1"><Scale size={10}/> {t.riskRewardRatio}</div>
          <div className="text-md font-mono font-bold text-broker-light">{data.riskRewardRatio}</div>
        </div>
        {data.budgetImpact && (
          <div className="bg-broker-green/10 p-3 border border-broker-green/40">
            <div className="text-[8px] font-black text-broker-green uppercase mb-1 flex items-center gap-1"><Wallet size={10}/> FIN. IMPACT</div>
            <div className="text-md font-mono font-black text-broker-green">{data.budgetImpact.profitUsd}</div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-1.5">
          <span className="text-[8px] font-black text-broker-green opacity-50 uppercase tracking-[0.2em]">{t.pros}</span>
          {data.pros.map((p, i) => <p key={i} className="text-[10px] font-mono text-gray-400 leading-tight">• <SmartText text={p} /></p>)}
        </div>
        <div className="space-y-1.5">
          <span className="text-[8px] font-black text-broker-red opacity-50 uppercase tracking-[0.2em]">{t.cons}</span>
          {data.cons.map((c, i) => <p key={i} className="text-[10px] font-mono text-gray-400 leading-tight">• <SmartText text={c} /></p>)}
        </div>
      </div>

      <div className="flex justify-between items-center text-[8px] font-black uppercase tracking-[0.3em] text-gray-500 pt-2 border-t border-white/5">
        <span>{t.withdraw}</span>
        <span className="text-broker-light">{data.withdraw}</span>
      </div>
    </MotionDiv>
  );
};

