import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, CorrelationData, ComboAssetConfig, Translation } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData, fetchMarketCorrelations } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Trash2, Calendar, Clock, SwitchCamera, Search, Radio, Grid3X3, Activity, Wallet, Layers } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [correlationData, setCorrelationData] = useState<CorrelationData[]>([]);

  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);
  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Budget
  const [budget, setBudget] = useState<number | null>(null);

  // Time
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Combo vs Single
  const [isComboMode, setIsComboMode] = useState(false);
  const [riskScore, setRiskScore] = useState(50);
  const [isAutoRisk, setIsAutoRisk] = useState(false);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally { setTickerLoading(false); }
  }, []);

  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
    try {
      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null,
        context
      );
      setPredictorResults(results);
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings, tickerData]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally { setLoading(false); }
  };

  const updateComboAsset = (idx: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[idx] = { ...next[idx], ...updates };
    setComboSettings(next);
  };

  const riskLabel = (score: number) => {
    if (score <= 30) return t.highlyStable;
    if (score <= 60) return t.moderatelyStable;
    return t.highlyRisky;
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="p-6 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={32} className="text-broker-pink" />
            <h1 className="text-2xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent uppercase">
              {t.title}
            </h1>
          </div>
          <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 bg-black/40 px-3 py-1.5 sharp-edge border border-white/5">
                <Wallet size={16} className="text-broker-green" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-xs font-mono outline-none w-32 text-broker-light"
                />
                <span className="text-[10px] font-black text-gray-500 uppercase">{t.budgetLabel}</span>
             </div>
             <div className="relative group flex items-center gap-2">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-xs font-mono font-black uppercase outline-none">
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-20 max-w-6xl">
          <div className="glass-panel border border-broker-pink/30 sharp-edge mb-8 overflow-hidden">
            <div className="flex border-b border-white/5">
              <button onClick={() => setViewMode('predict')} className={`flex-1 py-3 text-xs font-black tracking-widest uppercase transition-all ${viewMode === 'predict' ? 'bg-broker-pink/20 text-broker-pink' : 'text-gray-500'}`}>
                {t.tabPredictor}
              </button>
              <button onClick={() => setViewMode('search')} className={`flex-1 py-3 text-xs font-black tracking-widest uppercase transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan' : 'text-gray-500'}`}>
                {t.tabSearch}
              </button>
              <button onClick={() => setViewMode('matrix')} className={`flex-1 py-3 text-xs font-black tracking-widest uppercase transition-all ${viewMode === 'matrix' ? 'bg-broker-green/20 text-broker-green' : 'text-gray-500'}`}>
                {t.tabMatrix}
              </button>
            </div>

            <div className="p-6">
              {viewMode === 'predict' && (
                <div className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {/* Time Section */}
                    <div className="space-y-4">
                      <div className="flex justify-between items-center text-[10px] font-black tracking-widest uppercase text-broker-cyan">
                        <span><Clock size={12} className="inline mr-2" /> {t.horizon}</span>
                        <button onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} className="hover:text-white transition-colors">
                          {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>
                      {horizonMode === 'precise' ? (
                        <div className="grid grid-cols-5 gap-1">
                          {['h', 'd', 'w', 'm', 'y'].map((k) => (
                            <input key={k} type="number" placeholder={k.toUpperCase()} value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-[#141415] border-b border-white/10 py-2 text-center text-xs font-mono outline-none focus:border-broker-pink" />
                          ))}
                        </div>
                      ) : (
                        <div className="grid grid-cols-2 gap-2">
                          <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-[#141415] border border-white/5 py-2 px-2 text-[10px] font-mono outline-none" />
                          <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-[#141415] border border-white/5 py-2 px-2 text-[10px] font-mono outline-none" />
                        </div>
                      )}
                    </div>

                    {/* Mode Section */}
                    <div className="md:col-span-2 space-y-4">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black tracking-widest uppercase text-broker-cyan flex items-center gap-2">
                          <Layers size={14} /> {isComboMode ? t.superCombo : t.strategy}
                        </span>
                        <button onClick={() => setIsComboMode(!isComboMode)} className={`text-[9px] font-black tracking-widest uppercase px-3 py-1 sharp-edge transition-all ${isComboMode ? 'bg-broker-pink text-white shadow-[0_0_10px_#F31B80]' : 'bg-white/5 text-gray-500 border border-white/10'}`}>
                          {t.comboMode}
                        </button>
                      </div>

                      {!isComboMode ? (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="bg-[#141415] border border-white/10 p-3 text-xs font-mono uppercase outline-none">
                            {Object.values(MarketType).map(v => <option key={v} value={v}>{t[v as keyof Translation] || v}</option>)}
                          </select>
                          <div className="flex items-center gap-3">
                            <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="flex-grow h-1 bg-white/10 appearance-none cursor-pointer" />
                            <span className="text-[9px] font-mono font-black text-broker-pink w-16 text-right uppercase">{riskLabel(riskScore)}</span>
                          </div>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                          {[0, 1, 2].map(idx => (
                            <div key={idx} className="bg-black/20 p-3 border border-white/5 sharp-edge space-y-2">
                              <span className="text-[8px] font-black text-gray-500 uppercase">{t.assetSlot} 0{idx+1}</span>
                              <select value={comboSettings[idx].type} onChange={(e) => updateComboAsset(idx, { type: e.target.value as MarketType })} className="w-full bg-transparent text-[10px] font-mono uppercase outline-none">
                                {Object.values(MarketType).map(v => <option key={v} value={v}>{t[v as keyof Translation] || v}</option>)}
                              </select>
                              <div className="flex justify-between items-center mt-2">
                                <button onClick={() => updateComboAsset(idx, { isAuto: !comboSettings[idx].isAuto })} className={`text-[8px] font-black px-2 py-0.5 ${comboSettings[idx].isAuto ? 'text-broker-green border border-broker-green/40' : 'text-gray-500'}`}>{t.autoRisk}</button>
                                <input type="range" disabled={comboSettings[idx].isAuto} min="0" max="100" value={comboSettings[idx].risk} onChange={(e) => updateComboAsset(idx, { risk: parseInt(e.target.value) })} className={`w-12 h-0.5 appearance-none ${comboSettings[idx].isAuto ? 'opacity-20' : 'bg-broker-pink'}`} />
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  </div>

                  <button onClick={handlePredict} disabled={loading} className="w-full py-4 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-lg tracking-widest sharp-edge hover:opacity-90 disabled:opacity-50 flex justify-center items-center gap-3">
                    {loading ? <Settings size={20} className="animate-spin" /> : <BrainCircuit size={20} />}
                    {loading ? t.loading : t.predict}
                  </button>
                </div>
              )}

              {viewMode === 'search' && (
                <div className="flex gap-4">
                  <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-black/40 border border-white/10 p-4 text-sm font-mono outline-none focus:border-broker-cyan" />
                  <button onClick={handleSearch} disabled={loading} className="px-10 bg-broker-cyan text-black font-black italic tracking-widest uppercase sharp-edge">{t.searchButton}</button>
                </div>
              )}

              {viewMode === 'matrix' && (
                <div className="py-10">
                   {correlationData.length > 0 ? <CorrelationHeatmap data={correlationData} t={t} /> : <div className="text-center"><button onClick={async () => setCorrelationData(await fetchMarketCorrelations())} className="px-8 py-3 bg-broker-green text-black font-black italic sharp-edge">INITIALIZE QUANTUM MATRIX</button></div>}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

