const getSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING },
      expectedLoss: { type: Type.STRING },
      riskRewardRatio: { type: Type.STRING },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
      budgetImpact: {
        type: Type.OBJECT,
        properties: {
          profitUsd: { type: Type.STRING },
          lossUsd: { type: Type.STRING },
        }
      },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER },
          },
        },
      },
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
  },
});

const getTickerSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING },
      price: { type: Type.STRING },
      change: { type: Type.STRING },
      isUp: { type: Type.BOOLEAN },
    },
    required: ["symbol", "price", "change", "isUp"],
  },
});

const isRateLimitError = (error: any) => {
  const msg = error?.message || error?.toString() || '';
  return error?.status === 429 || msg.includes('429') || msg.includes('RESOURCE_EXHAUSTED');
};

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  let cachedFallback: TickerItem[] | null = null;
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      cachedFallback = data;
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: "Get price and 24h change for: S&P500, NASDAQ, BTC, ETH, Gold, NVDA, TSLA, US10Y.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Market scraper. Output JSON array.",
        responseMimeType: "application/json",
        responseSchema: getTickerSchema(),
      },
    });
    const data = JSON.parse(response.text || '[]');
    if (data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return cachedFallback || MOCK_TICKER_DATA;
  } catch (error) { return cachedFallback || MOCK_TICKER_DATA; }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const comboInfo = comboSettings 
      ? `COMBO MODE: 3 Assets Required. Types: ${comboSettings.map(c => c.type).join(', ')}. Target risks: ${comboSettings.map(c => c.risk).join(', ')}.`
      : `SINGLE MODE: Market: ${type}, Risk: ${riskScore}.`;

    const prompt = `
      Market Context: ${context}
      User Budget: ${budget ? `$${budget}` : 'None'}
      Config: ${comboInfo}
      Horizon: ${totalHours} hours.
      Language: ${lang}.
    `;

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        thinkingConfig: { thinkingBudget: 32768 },
        responseSchema: getSchema(),
      },
    });
    return JSON.parse(response.text || '[]');
  } catch (error) { return []; }
};

export const searchAssets = async (query: string, lang: string): Promise<Prediction[]> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Search and analyze: ${query}. Lang: ${lang}`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: getSchema(),
      },
    });
    return JSON.parse(response.text || '[]');
  } catch (error) { return []; }
};

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, ShieldCheck, Zap, AlertTriangle, Flame, Calendar, Clock, SwitchCamera, Search, Radio, Wallet, Layers, Filter } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // New Budget & Combo State
  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  // Existing inputs
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally { setTickerLoading(false); }
  }, []);

  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
    try {
      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings, tickerData]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg overflow-x-hidden">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="px-6 py-6 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={32} className="text-broker-pink" />
            <h1 className="text-2xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent uppercase">
              {t.title}
            </h1>
          </div>
          <div className="flex items-center gap-6">
             <div className="hidden sm:flex items-center gap-2 bg-black/40 px-3 py-1.5 sharp-edge border border-white/5 group">
                <Wallet size={16} className="text-broker-green group-hover:scale-110 transition-transform" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-xs font-mono outline-none w-24 text-broker-light"
                />
                <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">{t.budgetLabel}</span>
             </div>
             <div className="relative group flex items-center gap-2 cursor-pointer">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-xs font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-20 max-w-5xl">
          <div className="glass-panel border border-white/10 sharp-edge mb-8 overflow-hidden shadow-2xl">
            <div className="flex border-b border-white/5">
              <button onClick={() => setViewMode('predict')} className={`flex-1 py-3 text-[10px] font-black tracking-widest uppercase transition-all ${viewMode === 'predict' ? 'bg-broker-pink/20 text-broker-pink' : 'text-gray-500 hover:text-gray-300'}`}>
                {t.tabPredictor}
              </button>
              <button onClick={() => setViewMode('search')} className={`flex-1 py-3 text-[10px] font-black tracking-widest uppercase transition-all ${viewMode === 'search' ? 'bg-broker-cyan/20 text-broker-cyan' : 'text-gray-500 hover:text-gray-300'}`}>
                {t.tabSearch}
              </button>
            </div>

            <div className="p-6 space-y-8">
              {viewMode === 'predict' ? (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Column 1: Time */}
                    <div className="space-y-3">
                      <div className="flex justify-between items-center text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase">
                        <span className="flex items-center gap-2"><Clock size={12}/> {t.horizon}</span>
                        <button onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} className="hover:text-white transition-colors">
                          {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>
                      {horizonMode === 'precise' ? (
                        <div className="grid grid-cols-5 gap-1">
                          {['h', 'd', 'w', 'm', 'y'].map((k) => (
                            <input key={k} type="number" placeholder={k.toUpperCase()} value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-black/20 border-b border-white/10 p-2 text-center text-xs font-mono outline-none focus:border-broker-pink" />
                          ))}
                        </div>
                      ) : (
                        <div className="grid grid-cols-2 gap-1">
                          <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                          <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                        </div>
                      )}
                    </div>

                    {/* Column 2 & 3: Mode Switcher */}
                    <div className="md:col-span-2 space-y-4">
                      <div className="flex justify-between items-center">
                        <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                           {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} 
                           {isComboMode ? t.superCombo : t.strategy}
                        </span>
                        <button 
                          onClick={() => setIsComboMode(!isComboMode)}
                          className={`text-[9px] font-black px-4 py-1.5 sharp-edge transition-all ${isComboMode ? 'bg-broker-pink text-white shadow-[0_0_15px_rgba(243,27,128,0.4)]' : 'bg-white/5 text-gray-500 border border-white/10 hover:border-white/20'}`}
                        >
                          {t.comboMode}
