  ticker: string;
  weight: number;
}

export interface Prediction {
  name: string;
  ticker: string;
  type: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  pros: string[];
  cons: string[];
  withdraw: string;
  confidence: number;
  holdings?: Holding[];
  budgetImpact?: {
    profitUsd: string;
    lossUsd: string;
  };
}

export interface TickerItem {
  symbol: string;
  price: string;
  change: string;
  isUp: boolean;
}

export interface CorrelationData {
  assetA: string;
  assetB: string;
  correlation: number;
}

export interface Translation {
  title: string;
  loading: string;
  predict: string;
  priority: string;
  stability: string;
  fast: string;
  general: string;
  crypto: string;
  stocks: string;
  commodities: string;
  forex: string;
  etfs: string;
  indexes: string;
  bonds: string;
  mutualFunds: string;
  superCombo: string;
  pros: string;
  cons: string;
  withdraw: string;
  hours: string;
  days: string;
  weeks: string;
  months: string;
  years: string;
  confidence: string;
  strategy: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  riskIndex: string;
  highlyStable: string;
  moderatelyStable: string;
  moderatelyRisky: string;
  highlyRisky: string;
  horizon: string;
  lowRiskHint: string;
  highRiskHint: string;
  scanPrompt: string;
  confShort: string;
  clear: string;
  confirmClear: string;
  autoRisk: string;
  precise: string;
  calendar: string;
  startDate: string;
  endDate: string;
  portfolioAllocation: string;
  tabPredictor: string;
  tabSearch: string;
  tabMatrix: string;
  searchPlaceholder: string;
  searchButton: string;
  matrixTitle: string;
  matrixDesc: string;
  correlationHigh: string;
  correlationInverse: string;
  budgetLabel: string;
  budgetPlaceholder: string;
  comboMode: string;
  assetSlot: string;
  finImpact: string;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import { BrainCircuit, Settings, Globe, Wallet, Calendar, Clock, Layers, Filter, Activity, Search } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);
  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Budget & Combo Refining
  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  // Horizon
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Single mode config
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally { setTickerLoading(false); }
  }, []);

  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
    try {
      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings, tickerData]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="px-6 py-6 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={32} className="text-broker-pink" />
            <h1 className="text-2xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent uppercase">
              {t.title}
            </h1>
          </div>

          <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 bg-black/40 px-3 py-1.5 sharp-edge border border-white/5">
                <Wallet size={16} className="text-broker-green" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-xs font-mono outline-none w-24 text-broker-light"
                />
                <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">{t.budgetLabel}</span>
             </div>

             <div className="flex items-center gap-2">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-xs font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-20 max-w-5xl">
          {/* Navigation Tabs */}
          <div className="flex gap-1 mb-4">
            {[
              { id: 'predict', icon: <BrainCircuit size={14}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={14}/>, label: t.tabSearch },
              { id: 'matrix', icon: <Activity size={14}/>, label: t.tabMatrix }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`px-6 py-2 text-[10px] font-black tracking-widest uppercase flex items-center gap-2 transition-all sharp-edge ${viewMode === tab.id ? 'bg-broker-pink text-white shadow-[0_0_15px_#F31B80]' : 'bg-black/40 text-gray-500 hover:text-gray-300'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="glass-panel border border-white/10 sharp-edge p-6 shadow-2xl">
            {viewMode === 'predict' && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {/* Time Section */}
                  <div className="space-y-3">
                    <div className="flex justify-between items-center text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase">
                      <span className="flex items-center gap-2"><Clock size={12}/> {t.horizon}</span>
                      <button onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} className="hover:text-white transition-colors">
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-1">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <input key={k} type="number" placeholder={k.toUpperCase()} value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-black/20 border-b border-white/10 p-2 text-center text-xs font-mono outline-none focus:border-broker-pink" />
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-1">
                        <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                        <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                      </div>
                    )}
                  </div>

                  {/* Mode Section */}
                  <div className="space-y-3">
                    <div className="flex justify-between items-center text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase">
                       <span className="flex items-center gap-2">
                         {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button onClick={() => setIsComboMode(!isComboMode)} className={`text-[8px] font-black px-3 py-1 transition-all sharp-edge ${isComboMode ? 'bg-broker-pink text-white shadow-[0_0_10px_#F31B80]' : 'bg-white/5 text-gray-500 border border-white/10'}`}>
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex gap-4">
                        <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="flex-1 bg-black/40 border border-white/10 p-2 text-xs font-mono uppercase outline-none cursor-pointer">
                          {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                        </select>
                        <div className="flex-1 flex flex-col justify-center gap-1">
                           <div className="flex justify-between text-[8px] font-black text-broker-pink uppercase">
                             <span>RISK: {riskScore}</span>
                             <span>{riskScore < 30 ? t.highlyStable : riskScore < 70 ? t.moderatelyStable : t.highlyRisky}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1 bg-white/10 appearance-none cursor-pointer" />
                        </div>
                      </div>
                    ) : (
                      <div className="grid grid-cols-3 gap-2">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/5 p-2 sharp-edge space-y-2">
                             <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-transparent text-[9px] font-mono uppercase outline-none cursor-pointer">
                               {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                             </select>
                             <div className="flex justify-between items-center">
                               <button onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} className={`text-[7px] font-black px-1 ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-gray-600'}`}>AUTO</button>
                               <input type="range" disabled={comboSettings[idx].isAuto} min="0" max="100" value={comboSettings[idx].risk} onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} className={`w-8 h-0.5 appearance-none ${comboSettings[idx].isAuto ? 'opacity-20' : 'bg-broker-pink'}`} />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-4 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-lg tracking-[0.2em] sharp-edge hover:opacity-90 disabled:opacity-50 flex justify-center items-center gap-3">
                  {loading ? <Settings size={20} className="animate-spin" /> : <BrainCircuit size={20} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-4">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-black/40 border border-white/10 p-4 text-sm font-mono outline-none focus:border-broker-cyan" />
                <button onClick={handleSearch} disabled={loading} className="px-10 bg-broker-cyan text-black font-black italic tracking-widest uppercase sharp-edge">{t.searchButton}</button>
              </div>
            )}

            {viewMode === 'matrix' && (
              <CorrelationHeatmap data={[]} t={t} /> 
            )}
          </div>

          <div className="mt-8 grid grid-cols-1 gap-4">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import CorrelationHeatmap from './components/CorrelationHeatmap';
import { BrainCircuit, Settings, Globe, Wallet, Calendar, Clock, Layers, Filter, Activity, Search } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);
  const [viewMode, setViewMode] = useState<'predict' | 'search' | 'matrix'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Budget & Combo Refining
  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  // Horizon
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Single mode config
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally { setTickerLoading(false); }
  }, []);

  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
    try {
      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings, tickerData]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  const getRiskLabel = (score: number) => {
    if (score < 30) return t.highlyStable;
    if (score < 70) return t.moderatelyStable;
    return t.highlyRisky;
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="px-6 py-6 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={32} className="text-broker-pink" />
            <h1 className="text-2xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent uppercase">
              {t.title}
