             <div className="flex items-center gap-2">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-xs font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-20 max-w-5xl">
          {/* Navigation Tabs */}
          <div className="flex gap-1 mb-4">
            {[
              { id: 'predict', icon: <BrainCircuit size={14}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={14}/>, label: t.tabSearch },
              { id: 'matrix', icon: <Activity size={14}/>, label: t.tabMatrix }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`px-6 py-2 text-[10px] font-black tracking-widest uppercase flex items-center gap-2 transition-all sharp-edge ${viewMode === tab.id ? 'bg-broker-pink text-white shadow-[0_0_15px_#F31B80]' : 'bg-black/40 text-gray-500 hover:text-gray-300'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="glass-panel border border-white/10 sharp-edge p-6 shadow-2xl">
            {viewMode === 'predict' && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  {/* Time Section */}
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                      <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                        <Clock size={12}/> {t.horizon}
                      </span>
                      <button 
                        onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                        className="text-[9px] font-black px-4 py-1.5 transition-all sharp-edge border border-broker-cyan/40 text-broker-cyan hover:bg-broker-cyan/10 uppercase tracking-widest"
                      >
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-1">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <div key={k} className="flex flex-col gap-1">
                            <span className="text-[7px] text-center font-black text-gray-600 uppercase">{k}</span>
                            <input type="number" placeholder="0" value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-black/20 border-b border-white/10 p-2 text-center text-xs font-mono outline-none focus:border-broker-pink" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-2">
                        <div className="flex flex-col gap-1">
                           <span className="text-[7px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                        </div>
                        <div className="flex flex-col gap-1">
                           <span className="text-[7px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/20 border border-white/5 p-2 text-[10px] font-mono outline-none" />
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Mode Section */}
                  <div className="space-y-4">
                    <div className="flex justify-between items-center">
                       <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                         {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[9px] font-black px-4 py-1.5 transition-all sharp-edge border ${isComboMode ? 'bg-broker-pink border-broker-pink text-white shadow-[0_0_10px_#F31B80]' : 'border-white/20 text-gray-500 hover:text-gray-300'} uppercase tracking-widest`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col sm:flex-row gap-6 bg-black/20 p-4 border border-white/5 sharp-edge">
                        <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="flex-1 bg-black/40 border border-white/10 p-3 text-xs font-mono uppercase outline-none cursor-pointer">
                          {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                        </select>
                        <div className="flex-1 flex flex-col justify-center gap-1">
                           <div className="flex justify-between text-[8px] font-black text-broker-pink uppercase tracking-[0.1em]">
                             <span>RISK: {riskScore}</span>
                             <span>{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1 bg-white/10 appearance-none cursor-pointer" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-2">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/5 p-3 sharp-edge flex flex-col sm:flex-row gap-4 items-center">
                             <div className="w-full sm:w-1/3">
                                <span className="text-[7px] font-black text-gray-600 uppercase block mb-1">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black/40 border border-white/10 p-2 text-[10px] font-mono uppercase outline-none cursor-pointer">
                                  {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full sm:w-2/3 flex flex-col justify-center gap-1">
                               <div className="flex justify-between items-end mb-1">
                                 <div className="flex gap-2">
                                   <button 
                                     onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                     className={`text-[8px] font-black px-2 py-0.5 sharp-edge border transition-colors ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500'}`}
                                   >
                                     {t.autoRisk}
                                   </button>
                                 </div>
                                 <span className={`text-[8px] font-black uppercase ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>
                                   RISK: {comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}
                                 </span>
                               </div>
                               <input 
                                 type="range" 
                                 disabled={comboSettings[idx].isAuto} 
                                 min="0" 
                                 max="100" 
                                 value={comboSettings[idx].risk} 
                                 onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                 className={`w-full h-1 appearance-none transition-opacity ${comboSettings[idx].isAuto ? 'opacity-20 bg-gray-600' : 'bg-broker-pink cursor-pointer'}`} 
                               />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-5 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-[0.3em] sharp-edge hover:opacity-90 disabled:opacity-50 flex justify-center items-center gap-4 shadow-xl">
                  {loading ? <Settings size={24} className="animate-spin" /> : <BrainCircuit size={24} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-4">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-black/40 border border-white/10 p-4 text-sm font-mono outline-none focus:border-broker-cyan" />
                <button onClick={handleSearch} disabled={loading} className="px-10 bg-broker-cyan text-black font-black italic tracking-widest uppercase sharp-edge">{t.searchButton}</button>
              </div>
            )}

            {viewMode === 'matrix' && (
              <CorrelationHeatmap data={[]} t={t} /> 
            )}
          </div>

          <div className="mt-8 grid grid-cols-1 gap-4">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

export type Language = 'es' | 'en' | 'fr';

export enum MarketType {
  GENERAL = 'general',
  CRYPTO = 'crypto',
  STOCKS = 'stocks',
  COMMODITIES = 'commodities',
  FOREX = 'forex',
  ETFS = 'etfs',
  INDEXES = 'indexes',
  BONDS = 'bonds',
  MUTUAL_FUNDS = 'mutual_funds'
}

export type HorizonMode = 'precise' | 'calendar';

export interface TimeInput {
  h: number;
  d: number;
  w: number;
  m: number;
  y: number;
}

export interface ComboAssetConfig {
  type: MarketType;
  risk: number;
  isAuto: boolean;
}

export interface Holding {
  name: string;
  ticker: string;
  weight: number;
}

export interface Prediction {
  name: string;
  ticker: string;
  type: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  pros: string[];
  cons: string[];
  withdraw: string;
  confidence: number;
  holdings?: Holding[];
  budgetImpact?: {
    profitUsd: string;
    lossUsd: string;
  };
}

export interface TickerItem {
  symbol: string;
  price: string;
  change: string;
  isUp: boolean;
}

export interface Translation {
  title: string;
  loading: string;
  predict: string;
  priority: string;
  stability: string;
  fast: string;
  general: string;
  crypto: string;
  stocks: string;
  commodities: string;
  forex: string;
  etfs: string;
  indexes: string;
  bonds: string;
  mutualFunds: string;
  superCombo: string;
  pros: string;
  cons: string;
  withdraw: string;
  hours: string;
  days: string;
  weeks: string;
  months: string;
  years: string;
  confidence: string;
  strategy: string;
  expectedProfit: string;
  expectedLoss: string;
  riskRewardRatio: string;
  riskIndex: string;
  highlyStable: string;
  moderatelyStable: string;
  moderatelyRisky: string;
  highlyRisky: string;
  horizon: string;
  lowRiskHint: string;
  highRiskHint: string;
  scanPrompt: string;
  confShort: string;
  clear: string;
  confirmClear: string;
  autoRisk: string;
  precise: string;
  calendar: string;
  startDate: string;
  endDate: string;
  portfolioAllocation: string;
  tabPredictor: string;
  tabSearch: string;
  searchPlaceholder: string;
  searchButton: string;
  budgetLabel: string;
  budgetPlaceholder: string;
  comboMode: string;
  assetSlot: string;
  finImpact: string;
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS, MOCK_TICKER_DATA } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, TickerItem, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Ticker from './components/Ticker';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, Wallet, Calendar, Clock, Layers, Filter, Activity, Search } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [tickerLoading, setTickerLoading] = useState(false);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [tickerData, setTickerData] = useState<TickerItem[]>(MOCK_TICKER_DATA);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Budget & Combo Refining
  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  // Horizon
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Single mode config
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const refreshTicker = useCallback(async () => {
    setTickerLoading(true);
    try {
      const data = await fetchLiveMarketData();
      if (data && data.length > 0) setTickerData(data);
    } finally { setTickerLoading(false); }
  }, []);

  useEffect(() => {
    refreshTicker();
    const interval = setInterval(refreshTicker, 60000);
    return () => clearInterval(interval);
  }, [refreshTicker]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
    try {
      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings, tickerData]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    try {
      const results = await searchAssets(searchQuery, lang);
      setSearchResults(results);
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  const getRiskLabel = (score: number) => {
    if (score < 30) return t.highlyStable;
    if (score < 70) return t.moderatelyStable;
    return t.highlyRisky;
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">
        <Ticker data={tickerData} onRefresh={refreshTicker} isLoading={tickerLoading} />

        <header className="px-6 py-6 flex justify-between items-center max-w-7xl mx-auto w-full">
          <div className="flex items-center gap-3">
            <BrainCircuit size={32} className="text-broker-pink" />
            <h1 className="text-2xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light to-broker-cyan bg-clip-text text-transparent uppercase">
              {t.title}
            </h1>
          </div>

          <div className="flex items-center gap-6">
             <div className="flex items-center gap-2 bg-black/40 px-3 py-1.5 sharp-edge border border-white/5 group">
                <Wallet size={16} className="text-broker-green group-hover:scale-110 transition-transform" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-xs font-mono outline-none w-24 text-broker-light"
                />
                <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest">{t.budgetLabel}</span>
             </div>

             <div className="flex items-center gap-2">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-xs font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es">ES</option>
                  <option value="en">EN</option>
                  <option value="fr">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-20 max-w-5xl">
          {/* Navigation Tabs */}
          <div className="flex gap-1 mb-4">
            {[
              { id: 'predict', icon: <BrainCircuit size={14}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={14}/>, label: t.tabSearch },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`px-8 py-3 text-[10px] font-black tracking-widest uppercase flex items-center gap-2 transition-all sharp-edge ${viewMode === tab.id ? 'bg-broker-pink text-white shadow-[0_0_15px_#F31B80]' : 'bg-black/40 text-gray-500 hover:text-gray-300'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="glass-panel border border-white/10 sharp-edge p-6 shadow-2xl">
            {viewMode === 'predict' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                  {/* Time Section */}
                  <div className="space-y-4">
                    <div className="flex justify-between items-center mb-2">
                      <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                        <Clock size={12}/> {t.horizon}
                      </span>
                      <button 
                        onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                        className="text-[9px] font-black px-6 py-2 transition-all sharp-edge border border-broker-cyan/40 text-broker-cyan hover:bg-broker-cyan/10 uppercase tracking-widest"
                      >
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-1">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <div key={k} className="flex flex-col gap-1">
                            <span className="text-[8px] text-center font-black text-gray-600 uppercase tracking-tighter">{k}</span>
                            <input type="number" placeholder="0" value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-black/30 border-b border-white/10 p-2 text-center text-xs font-mono outline-none focus:border-broker-pink transition-all" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-3">
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/30 border border-white/10 p-2.5 text-[10px] font-mono outline-none focus:border-broker-pink transition-all" />
                        </div>
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/30 border border-white/10 p-2.5 text-[10px] font-mono outline-none focus:border-broker-pink transition-all" />
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Mode Section */}
                  <div className="space-y-4">
                    <div className="flex justify-between items-center mb-2">
                       <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                         {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[9px] font-black px-6 py-2 transition-all sharp-edge border ${isComboMode ? 'bg-broker-pink border-broker-pink text-white shadow-[0_0_15px_rgba(243,27,128,0.5)]' : 'border-white/20 text-gray-500 hover:text-gray-300 hover:border-white/30'} uppercase tracking-widest`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col sm:flex-row gap-6 bg-black/30 p-5 border border-white/10 sharp-edge animate-in fade-in duration-300">
                        <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="flex-1 bg-black/50 border border-white/20 p-3 text-xs font-mono uppercase outline-none cursor-pointer focus:border-broker-cyan">
                          {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                        </select>
                        <div className="flex-1 flex flex-col justify-center gap-1.5">
                           <div className="flex justify-between text-[9px] font-black text-broker-pink uppercase tracking-[0.1em]">
                             <span>RISK: {riskScore}</span>
                             <span>{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1 bg-white/10 appearance-none cursor-pointer accent-broker-pink" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-3 animate-in slide-in-from-top-4 duration-500">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/10 p-4 sharp-edge flex flex-col sm:flex-row gap-6 items-center hover:border-broker-pink/30 transition-colors">
                             <div className="w-full sm:w-2/5">
                                <span className="text-[8px] font-black text-gray-600 uppercase block mb-1.5 tracking-tighter">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black/50 border border-white/20 p-2.5 text-[10px] font-mono uppercase outline-none cursor-pointer focus:border-broker-pink">
                                  {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full sm:w-3/5 flex flex-col justify-center gap-1.5 pt-2 sm:pt-4">
                               <div className="flex justify-between items-end">
                                 <button 
                                   onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                   className={`text-[8px] font-black px-3 py-1 sharp-edge border transition-all ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500 hover:text-gray-300'}`}
                                 >
                                   {t.autoRisk}
                                 </button>
                                 <span className={`text-[8px] font-black uppercase tracking-widest ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>
                                   RISK: {comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}
                                 </span>
                               </div>
                               <input 
                                 type="range" 
                                 disabled={comboSettings[idx].isAuto} 
                                 min="0" 
                                 max="100" 
                                 value={comboSettings[idx].risk} 
                                 onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                 className={`w-full h-1 appearance-none transition-all ${comboSettings[idx].isAuto ? 'opacity-20 bg-gray-600' : 'bg-broker-pink cursor-pointer'}`} 
                               />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-6 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-[0.4em] sharp-edge hover:opacity-95 disabled:opacity-50 flex justify-center items-center gap-4 shadow-2xl transition-all active:scale-[0.99]">
                  {loading ? <Settings size={26} className="animate-spin" /> : <BrainCircuit size={26} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-4 p-2 animate-in fade-in zoom-in-95 duration-300">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-black/40 border border-white/10 p-5 text-sm font-mono outline-none focus:border-broker-cyan transition-all" />
                <button onClick={handleSearch} disabled={loading} className="px-12 bg-broker-cyan text-black font-black italic tracking-widest uppercase sharp-edge hover:opacity-90 active:scale-95 transition-all shadow-[0_0_15px_rgba(130,234,255,0.4)]">{t.searchButton}</button>
              </div>
            )}
          </div>

          <div className="mt-10 grid grid-cols-1 gap-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

import { GoogleGenAI, Type, GenerateContentParameters } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, ComboAssetConfig } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v1';
const TICKER_CACHE_TTL = 50 * 1000;

// Helper to delay execution
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper to handle retries for API calls
async function callWithRetry(
  params: GenerateContentParameters,
  maxRetries: number = 3
): Promise<any> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let delay = 2000; // Start with 2s delay

  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await ai.models.generateContent(params);
      return response;
    } catch (error: any) {
      const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');

      if (isQuota && i < maxRetries - 1) {
        console.warn(`Quota exceeded. Retrying in ${delay}ms... (Attempt ${i + 1}/${maxRetries})`);
        await sleep(delay);
        delay *= 2; // Exponential backoff
        continue;
      }
      throw error; // Re-throw if not a quota error or out of retries
    }
  }
}

const getSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING },
      ticker: { type: Type.STRING },
      type: { type: Type.STRING },
      expectedProfit: { type: Type.STRING },
      expectedLoss: { type: Type.STRING },
      riskRewardRatio: { type: Type.STRING },
      pros: { type: Type.ARRAY, items: { type: Type.STRING } },
      cons: { type: Type.ARRAY, items: { type: Type.STRING } },
      withdraw: { type: Type.STRING },
      confidence: { type: Type.NUMBER },
      budgetImpact: {
        type: Type.OBJECT,
        properties: {
          profitUsd: { type: Type.STRING },
          lossUsd: { type: Type.STRING },
        }
      },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER },
          },
        },
      },
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"],
  },
});

const getTickerSchema = () => ({
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING },
      price: { type: Type.STRING },
      change: { type: Type.STRING },
      isUp: { type: Type.BOOLEAN },
    },
    required: ["symbol", "price", "change", "isUp"],
  },
});

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  let cachedFallback: TickerItem[] | null = null;
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      cachedFallback = data;
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const response = await callWithRetry({
      model: "gemini-3-pro-preview",
      contents: "Get price and 24h change for: S&P500, NASDAQ, BTC, ETH, Gold, NVDA, TSLA, US10Y.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Market scraper. Output JSON array.",
        responseMimeType: "application/json",
        responseSchema: getTickerSchema(),
      },
    });
    const data = JSON.parse(response.text || '[]');
    if (data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return cachedFallback || MOCK_TICKER_DATA;
  } catch (error) { 
    console.error("Ticker fetch failed:", error);
    return cachedFallback || MOCK_TICKER_DATA; 
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  const comboInfo = comboSettings 
    ? `COMBO MODE: 3 Assets Required. Types: ${comboSettings.map(c => c.type).join(', ')}. Target risks: ${comboSettings.map(c => c.risk).join(', ')}.`
    : `SINGLE MODE: Market: ${type}, Risk: ${riskScore}.`;

  const prompt = `
    Market Context: ${context}
    User Budget: ${budget ? `$${budget}` : 'None'}
    Config: ${comboInfo}
    Horizon: ${totalHours} hours.
    Language: ${lang}.
  `;

  const response = await callWithRetry({
    model: "gemini-3-pro-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      thinkingConfig: { thinkingBudget: 32768 },
      responseSchema: getSchema(),
    },
  });
  return JSON.parse(response.text || '[]');
};

export const searchAssets = async (query: string, lang: string): Promise<Prediction[]> => {
  const response = await callWithRetry({
    model: "gemini-3-pro-preview",
    contents: `Search and analyze: ${query}. Lang: ${lang}`,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: getSchema(),
    },
  });
  return JSON.parse(response.text || '[]');
};

