import { GoogleGenAI, Type, GenerateContentParameters } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, ComboAssetConfig } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v1';
const TICKER_CACHE_TTL = 90 * 1000; // Increased cache time to reduce frequency of calls

// Helper to delay execution
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper to handle retries for API calls
async function callWithRetry(
  params: GenerateContentParameters,
  maxRetries: number = 4
): Promise<any> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let delay = 3000; // Increased start delay to 3s

  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await ai.models.generateContent(params);
      return response;
    } catch (error: any) {
      const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');

      if (isQuota && i < maxRetries - 1) {
        console.warn(`Quota exceeded. Retrying in ${delay}ms... (Attempt ${i + 1}/${maxRetries})`);
        await sleep(delay);
        delay *= 2; // Exponential backoff
        continue;
      }
      throw error; 
    }
  }
}

const getSchema = () => ({
