                      <div className="grid grid-cols-2 gap-3">
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/30 border border-white/10 p-2.5 text-[10px] font-mono outline-none focus:border-broker-pink transition-all" />
                        </div>
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/30 border border-white/10 p-2.5 text-[10px] font-mono outline-none focus:border-broker-pink transition-all" />
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Mode Section */}
                  <div className="space-y-4">
                    <div className="flex justify-between items-center mb-2">
                       <span className="text-[10px] font-black tracking-[0.2em] text-broker-cyan uppercase flex items-center gap-2">
                         {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[9px] font-black px-6 py-2 transition-all sharp-edge border ${isComboMode ? 'bg-broker-pink border-broker-pink text-white shadow-[0_0_15px_rgba(243,27,128,0.5)]' : 'border-white/20 text-gray-500 hover:text-gray-300 hover:border-white/30'} uppercase tracking-widest`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col sm:flex-row gap-6 bg-black/30 p-5 border border-white/10 sharp-edge animate-in fade-in duration-300">
                        <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="flex-1 bg-black/50 border border-white/20 p-3 text-xs font-mono uppercase outline-none cursor-pointer focus:border-broker-cyan">
                          {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                        </select>
                        <div className="flex-1 flex flex-col justify-center gap-1.5">
                           <div className="flex justify-between text-[9px] font-black text-broker-pink uppercase tracking-[0.1em]">
                             <span>RISK: {riskScore}</span>
                             <span>{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1 bg-white/10 appearance-none cursor-pointer accent-broker-pink" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-3 animate-in slide-in-from-top-4 duration-500">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/10 p-4 sharp-edge flex flex-col sm:flex-row gap-6 items-center hover:border-broker-pink/30 transition-colors">
                             <div className="w-full sm:w-2/5">
                                <span className="text-[8px] font-black text-gray-600 uppercase block mb-1.5 tracking-tighter">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black/50 border border-white/20 p-2.5 text-[10px] font-mono uppercase outline-none cursor-pointer focus:border-broker-pink">
                                  {Object.values(MarketType).map(m => <option key={m} value={m}>{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full sm:w-3/5 flex flex-col justify-center gap-1.5 pt-2 sm:pt-4">
                               <div className="flex justify-between items-end">
                                 <button 
                                   onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                   className={`text-[8px] font-black px-3 py-1 sharp-edge border transition-all ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500 hover:text-gray-300'}`}
                                 >
                                   {t.autoRisk}
                                 </button>
                                 <span className={`text-[8px] font-black uppercase tracking-widest ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>
                                   RISK: {comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}
                                 </span>
                               </div>
                               <input 
                                 type="range" 
                                 disabled={comboSettings[idx].isAuto} 
                                 min="0" 
                                 max="100" 
                                 value={comboSettings[idx].risk} 
                                 onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                 className={`w-full h-1 appearance-none transition-all ${comboSettings[idx].isAuto ? 'opacity-20 bg-gray-600' : 'bg-broker-pink cursor-pointer'}`} 
                               />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-6 bg-gradient-to-r from-broker-pink to-broker-purple text-white font-black italic text-xl tracking-[0.4em] sharp-edge hover:opacity-95 disabled:opacity-50 flex justify-center items-center gap-4 shadow-2xl transition-all active:scale-[0.99]">
                  {loading ? <Settings size={26} className="animate-spin" /> : <BrainCircuit size={26} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-4 p-2 animate-in fade-in zoom-in-95 duration-300">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-black/40 border border-white/10 p-5 text-sm font-mono outline-none focus:border-broker-cyan transition-all" />
                <button onClick={handleSearch} disabled={loading} className="px-12 bg-broker-cyan text-black font-black italic tracking-widest uppercase sharp-edge hover:opacity-90 active:scale-95 transition-all shadow-[0_0_15px_rgba(130,234,255,0.4)]">{t.searchButton}</button>
              </div>
            )}
          </div>

          <div className="mt-10 grid grid-cols-1 gap-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>
          </div>
        </main>
      </div>
      <Dictionary />
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Dictionary from './components/Dictionary';
import { BrainCircuit, Settings, Globe, Wallet, Clock, Layers, Filter, Search, AlertCircle, X } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  // Budget & Combo Refining
  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  // Horizon
  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  // Single mode config
  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      // Fetch live context right before prediction to ensure fresh data
      const tickerData = await fetchLiveMarketData();
      const context = tickerData.map(i => `${i.symbol}: ${i.price} (${i.change})`).join(', ');

      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } catch (err: any) {
      const msg = err?.message || '';
      if (msg.includes('429') || msg.includes('quota')) {
        setError(lang === 'es' ? 'Límite de cuota excedido. Por favor, espera un momento.' : 'Quota limit exceeded. Please wait a moment.');
      } else {
        setError(lang === 'es' ? 'Error al generar predicciones.' : 'Error generating predictions.');
      }
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      // Also provide context to search for better analysis
      const tickerData = await fetchLiveMarketData();
      const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');

      const results = await searchAssets(`${searchQuery}. Market context: ${context}`, lang);
      setSearchResults(results);
    } catch (err: any) {
      const msg = err?.message || '';
      if (msg.includes('429') || msg.includes('quota')) {
        setError(lang === 'es' ? 'Límite de cuota excedido.' : 'Quota limit exceeded.');
      } else {
        setError(lang === 'es' ? 'Error en la búsqueda.' : 'Search error.');
      }
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  const getRiskLabel = (score: number) => {
    if (score < 30) return t.highlyStable;
    if (score < 70) return t.moderatelyStable;
    return t.highlyRisky;
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-broker-bg overflow-x-hidden">
      <div className="fixed inset-0 bg-[#1a1a1b] z-0" />
      <div className="relative z-10 flex flex-col min-h-screen">

        <header className="px-6 py-10 flex flex-col md:flex-row justify-between items-center max-w-7xl mx-auto w-full gap-6">
          <div className="flex items-center gap-4">
            <div className="p-3 bg-broker-pink/10 border border-broker-pink/30 sharp-edge">
              <BrainCircuit size={40} className="text-broker-pink shadow-[0_0_15px_rgba(243,27,128,0.4)]" />
            </div>
            <div>
              <h1 className="text-4xl font-black italic tracking-tighter bg-gradient-to-r from-broker-light via-broker-cyan to-broker-pink bg-clip-text text-transparent uppercase leading-none">
                {t.title}
              </h1>
              <div className="flex items-center gap-2 mt-1">
                <div className="w-2 h-2 rounded-full bg-broker-green animate-pulse" />
                <span className="text-[10px] font-black font-mono text-gray-500 uppercase tracking-[0.3em]">Neural Engine Active</span>
              </div>
            </div>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-6">
             <div className="flex items-center gap-3 bg-black/40 px-4 py-2.5 sharp-edge border border-white/10 group hover:border-broker-green/50 transition-colors">
                <Wallet size={18} className="text-broker-green group-hover:scale-110 transition-transform" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-sm font-mono outline-none w-28 text-broker-light placeholder:text-gray-700"
                />
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest border-l border-white/10 pl-3">{t.budgetLabel}</span>
             </div>

             <div className="flex items-center gap-3 bg-black/40 px-4 py-2.5 sharp-edge border border-white/10">
                <Globe size={18} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-sm font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es" className="bg-broker-bg">ES</option>
                  <option value="en" className="bg-broker-bg">EN</option>
                  <option value="fr" className="bg-broker-bg">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 pb-24 max-w-5xl">
          {/* Error Notification */}
          <AnimatePresence>
            {error && (
              <motion.div
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                className="mb-8"
              >
                <div className="bg-broker-red/10 border-l-4 border-broker-red p-5 sharp-edge flex items-center justify-between backdrop-blur-md">
                  <div className="flex items-center gap-4 text-broker-red">
                    <AlertCircle size={24} />
                    <span className="text-sm font-black uppercase tracking-widest">{error}</span>
                  </div>
                  <button onClick={() => setError(null)} className="p-2 hover:bg-broker-red/20 transition-colors sharp-edge">
                    <X size={20} className="text-broker-red" />
                  </button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Tab Navigation */}
          <div className="flex gap-1 mb-6">
            {[
              { id: 'predict', icon: <BrainCircuit size={16}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={16}/>, label: t.tabSearch },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`flex-1 md:flex-none md:px-12 py-4 text-[11px] font-black tracking-[0.3em] uppercase flex items-center justify-center gap-3 transition-all sharp-edge border-t border-x ${viewMode === tab.id ? 'bg-broker-pink text-white border-broker-pink shadow-[0_-5px_25px_rgba(243,27,128,0.3)]' : 'bg-black/40 text-gray-500 border-white/5 hover:text-gray-300 hover:bg-black/60'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="glass-panel border border-white/10 sharp-edge p-8 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)]">
            {viewMode === 'predict' && (
              <div className="space-y-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-16">
                  {/* Time Section */}
                  <div className="space-y-6">
                    <div className="flex justify-between items-center border-b border-white/10 pb-3">
                      <span className="text-[11px] font-black tracking-[0.3em] text-broker-cyan uppercase flex items-center gap-3">
                        <Clock size={16} className="text-broker-cyan" /> {t.horizon}
                      </span>
                      <button 
                        onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                        className="text-[10px] font-black px-4 py-2 transition-all sharp-edge border border-broker-cyan/30 text-broker-cyan hover:bg-broker-cyan/10 uppercase tracking-widest"
                      >
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-2">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <div key={k} className="flex flex-col gap-2">
                            <span className="text-[9px] text-center font-black text-gray-600 uppercase tracking-widest">{k}</span>
                            <input type="number" placeholder="0" value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-black/30 border border-white/5 p-3 text-center text-sm font-mono outline-none focus:border-broker-pink focus:bg-black/50 transition-all sharp-edge" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-4">
                        <div className="flex flex-col gap-2">
                           <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-black/30 border border-white/5 p-3.5 text-xs font-mono outline-none focus:border-broker-pink focus:bg-black/50 transition-all sharp-edge text-broker-light" />
                        </div>
                        <div className="flex flex-col gap-2">
                           <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest pl-1">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-black/30 border border-white/5 p-3.5 text-xs font-mono outline-none focus:border-broker-pink focus:bg-black/50 transition-all sharp-edge text-broker-light" />
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Mode Section */}
                  <div className="space-y-6">
                    <div className="flex justify-between items-center border-b border-white/10 pb-3">
                       <span className="text-[11px] font-black tracking-[0.3em] text-broker-cyan uppercase flex items-center gap-3">
                         {isComboMode ? <Layers size={18}/> : <Filter size={18}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[10px] font-black px-5 py-2 transition-all sharp-edge border ${isComboMode ? 'bg-broker-pink border-broker-pink text-white shadow-[0_0_20px_rgba(243,27,128,0.5)]' : 'border-white/20 text-gray-500 hover:text-gray-300 hover:border-white/40'} uppercase tracking-widest`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col gap-6 bg-black/20 p-6 border border-white/5 sharp-edge animate-in fade-in zoom-in-95 duration-500">
                        <div className="flex flex-col gap-2">
                          <span className="text-[9px] font-black text-gray-600 uppercase tracking-widest">ASSET CLASS</span>
                          <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="w-full bg-black/50 border border-white/10 p-4 text-xs font-mono uppercase outline-none cursor-pointer focus:border-broker-cyan transition-colors sharp-edge">
                            {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-broker-bg">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                          </select>
                        </div>
                        <div className="flex flex-col gap-3">
                           <div className="flex justify-between text-[10px] font-black uppercase tracking-[0.2em]">
                             <span className="text-broker-pink">RISK THRESHOLD: {riskScore}</span>
                             <span className="text-white/60">{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1.5 bg-white/10 appearance-none cursor-pointer accent-broker-pink sharp-edge" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-3 animate-in slide-in-from-top-4 duration-500">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/5 p-5 sharp-edge flex flex-col md:flex-row gap-8 items-center hover:border-broker-pink/40 transition-all group">
                             <div className="w-full md:w-2/5">
                                <span className="text-[9px] font-black text-gray-600 uppercase block mb-2 tracking-widest">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black/50 border border-white/10 p-3 text-[11px] font-mono uppercase outline-none cursor-pointer focus:border-broker-pink sharp-edge group-hover:border-broker-pink/20">
                                  {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-broker-bg">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full md:w-3/5 flex flex-col justify-center gap-3">
                               <div className="flex justify-between items-end">
                                 <button 
                                   onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                   className={`text-[9px] font-black px-4 py-1.5 sharp-edge border transition-all ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500 hover:text-gray-300'}`}
                                 >
                                   {t.autoRisk}
                                 </button>
                                 <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>
                                   {comboSettings[idx].isAuto ? 'DYNAMIC' : `RISK: ${comboSettings[idx].risk}`}
                                 </span>
                               </div>
                               <input 
                                 type="range" 
                                 disabled={comboSettings[idx].isAuto} 
                                 min="0" 
                                 max="100" 
                                 value={comboSettings[idx].risk} 
                                 onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                 className={`w-full h-1 appearance-none transition-all ${comboSettings[idx].isAuto ? 'opacity-10 bg-gray-700' : 'bg-broker-pink/50 cursor-pointer accent-broker-pink'}`} 
                               />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-8 bg-gradient-to-r from-broker-pink via-broker-purple to-broker-pink bg-[length:200%_auto] animate-[gradient_5s_linear_infinite] text-white font-black italic text-2xl tracking-[0.5em] sharp-edge hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50 disabled:scale-100 flex justify-center items-center gap-6 shadow-[0_15px_40px_-5px_rgba(243,27,128,0.4)] transition-all uppercase">
                  {loading ? <Settings size={32} className="animate-spin" /> : <BrainCircuit size={32} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
