    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION + " Quantitative search and risk assessment module. JSON ONLY.",
    },
  });

  // Extract mandatory Search Grounding chunks
  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = chunks
    .filter((c: any) => c.web)
    .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

  const data = extractJson(response.text || '[]');
  if (Array.isArray(data)) {
    return data.map(item => ({ ...item, groundingSources: sources }));
  }
  return data;
};

