                           <div className="flex justify-between text-[10px] font-black uppercase tracking-[0.2em]">
                             <span className="text-broker-pink">RISK THRESHOLD: {riskScore}</span>
                             <span className="text-white/60">{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1.5 bg-white/10 appearance-none cursor-pointer accent-broker-pink sharp-edge" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-3 animate-in slide-in-from-top-4 duration-500">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/30 border border-white/5 p-5 sharp-edge flex flex-col md:flex-row gap-8 items-center hover:border-broker-pink/40 transition-all group">
                             <div className="w-full md:w-2/5">
                                <span className="text-[9px] font-black text-gray-600 uppercase block mb-2 tracking-widest">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black/50 border border-white/10 p-3 text-[11px] font-mono uppercase outline-none cursor-pointer focus:border-broker-pink sharp-edge group-hover:border-broker-pink/20">
                                  {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-broker-bg">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full md:w-3/5 flex flex-col justify-center gap-3">
                               <div className="flex justify-between items-end">
                                 <button 
                                   onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                   className={`text-[9px] font-black px-4 py-1.5 sharp-edge border transition-all ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500 hover:text-gray-300'}`}
                                 >
                                   {t.autoRisk}
                                 </button>
                                 <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>
                                   {comboSettings[idx].isAuto ? 'DYNAMIC' : `RISK: ${comboSettings[idx].risk}`}
                                 </span>
                               </div>
                               <input 
                                 type="range" 
                                 disabled={comboSettings[idx].isAuto} 
                                 min="0" 
                                 max="100" 
                                 value={comboSettings[idx].risk} 
                                 onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                 className={`w-full h-1 appearance-none transition-all ${comboSettings[idx].isAuto ? 'opacity-10 bg-gray-700' : 'bg-broker-pink/50 cursor-pointer accent-broker-pink'}`} 
                               />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-8 bg-gradient-to-r from-broker-pink via-broker-purple to-broker-pink bg-[length:200%_auto] animate-[gradient_5s_linear_infinite] text-white font-black italic text-2xl tracking-[0.5em] sharp-edge hover:scale-[1.01] active:scale-[0.99] disabled:opacity-50 disabled:scale-100 flex justify-center items-center gap-6 shadow-[0_15px_40px_-5px_rgba(243,27,128,0.4)] transition-all uppercase">
                  {loading ? <Settings size={32} className="animate-spin" /> : <BrainCircuit size={32} />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex flex-col md:flex-row gap-4 p-4 animate-in fade-in zoom-in-95 duration-500">
                <div className="relative flex-grow">
                  <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-gray-500" size={20} />
                  <input 
                    type="text" 
                    value={searchQuery} 
                    onChange={(e) => setSearchQuery(e.target.value)} 
                    onKeyDown={(e) => e.key === 'Enter' && handleSearch()} 
                    placeholder={t.searchPlaceholder} 
                    className="w-full bg-black/40 border border-white/10 py-6 pl-16 pr-8 text-lg font-mono outline-none focus:border-broker-cyan focus:bg-black/60 transition-all sharp-edge shadow-inner" 
                  />
                </div>
                <button 
                  onClick={handleSearch} 
                  disabled={loading} 
                  className="px-16 py-6 bg-broker-cyan text-black font-black italic tracking-[0.3em] text-lg uppercase sharp-edge hover:bg-white active:scale-95 transition-all shadow-[0_0_30px_rgba(130,234,255,0.3)] disabled:opacity-50"
                >
                  {loading ? <Settings size={24} className="animate-spin" /> : t.searchButton}
                </button>
              </div>
            )}
          </div>

          <div className="mt-16 grid grid-cols-1 gap-10">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>

            {activePredictions.length === 0 && !loading && (
              <div className="py-32 text-center border-2 border-dashed border-white/5 sharp-edge">
                <Activity size={48} className="text-gray-800 mx-auto mb-6 opacity-20" />
                <p className="text-[11px] font-black text-gray-700 uppercase tracking-[0.5em]">System Idle // Awaiting Input</p>
              </div>
            )}
          </div>
        </main>
      </div>

      <Dictionary />

      <style>{`
        @keyframes gradient {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
      `}</style>
    </div>
  );
}

import React, { useState, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Dictionary from './components/Dictionary';
import { Zap, Target, Globe, Wallet, Clock, Layers, Filter, Search, ShieldCheck, X, Activity, Fingerprint, Crown } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [riskScore, setRiskScore] = useState(50);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const activePredictions = viewMode === 'predict' ? predictorResults : searchResults;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const handlePredict = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = tickerData.map(i => `${i.symbol}: ${i.price} (${i.change})`).join(', ');

      const results = await fetchPredictions(
        totalHours || 168, 
        riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(results);
    } catch (err: any) {
      setError(err?.message || 'Error');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ');
      const results = await searchAssets(`${searchQuery}. Context: ${context}`, lang);
      setSearchResults(results);
    } catch (err: any) {
      setError('Error');
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  const getRiskLabel = (score: number) => {
    if (score < 30) return t.highlyStable;
    if (score < 70) return t.moderatelyStable;
    return t.highlyRisky;
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-[#080809] overflow-x-hidden selection:bg-broker-pink selection:text-white">
      {/* Texture Overlay */}
      <div className="fixed inset-0 pointer-events-none z-[100] opacity-[0.03] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]" />

      <div className="relative z-10 flex flex-col min-h-screen">
        <header className="px-8 py-12 flex flex-col md:flex-row justify-between items-center max-w-7xl mx-auto w-full gap-8 border-b border-white/5">
          <div className="flex items-center gap-6">
            <div className="relative">
              <div className="absolute inset-0 bg-broker-cyan blur-[20px] opacity-20 animate-pulse" />
              <div className="relative p-4 bg-black border border-white/10 sharp-edge">
                <Crown size={32} className="text-broker-cyan shadow-[0_0_15px_rgba(130,234,255,0.6)]" />
              </div>
            </div>
            <div>
              <h1 className="text-5xl font-black italic tracking-[-0.05em] leading-none uppercase bg-gradient-to-br from-white via-gray-400 to-gray-700 bg-clip-text text-transparent">
                {t.title}
              </h1>
              <p className="text-[10px] font-black font-mono text-broker-cyan/60 uppercase tracking-[0.5em] mt-2 flex items-center gap-2">
                <ShieldCheck size={12} /> VERIFIED QUANTUM ORACLE v4.0
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center justify-center gap-8">
             <div className="flex items-center gap-4 bg-white/[0.03] px-6 py-3 sharp-edge border border-white/5 hover:border-broker-green/40 transition-all group shadow-inner">
                <Wallet size={20} className="text-broker-green group-hover:scale-110 transition-transform" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-lg font-mono outline-none w-32 text-broker-light placeholder:text-gray-800"
                />
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest border-l border-white/10 pl-4">{t.budgetLabel}</span>
             </div>

             <div className="flex items-center gap-4 bg-white/[0.03] px-6 py-3 sharp-edge border border-white/5">
                <Globe size={20} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-lg font-mono font-black uppercase outline-none cursor-pointer">
                  <option value="es" className="bg-[#0D0D0E]">ES</option>
                  <option value="en" className="bg-[#0D0D0E]">EN</option>
                  <option value="fr" className="bg-[#0D0D0E]">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-6 pb-32 max-w-5xl pt-12">
          <AnimatePresence>
            {error && (
              <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mb-10">
                <div className="bg-broker-red/5 border-l-2 border-broker-red p-6 sharp-edge flex items-center justify-between backdrop-blur-3xl shadow-2xl">
                  <div className="flex items-center gap-5 text-broker-red">
                    <Activity size={24} className="animate-pulse" />
                    <span className="text-[11px] font-black uppercase tracking-[0.2em]">{error}</span>
                  </div>
                  <X size={20} onClick={() => setError(null)} className="cursor-pointer hover:text-white" />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="flex gap-1 mb-1">
            {[
              { id: 'predict', icon: <Fingerprint size={16}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={16}/>, label: t.tabSearch },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`flex-1 md:flex-none md:px-14 py-5 text-[11px] font-black tracking-[0.4em] uppercase flex items-center justify-center gap-4 transition-all sharp-edge ${viewMode === tab.id ? 'bg-white text-black shadow-[0_0_30px_rgba(255,255,255,0.1)]' : 'bg-white/[0.02] text-gray-600 border border-white/5 hover:text-white hover:bg-white/[0.05]'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="bg-white/[0.01] border border-white/10 sharp-edge p-10 shadow-2xl backdrop-blur-xl">
            {viewMode === 'predict' && (
              <div className="space-y-12">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-20">
                  {/* Time Section */}
                  <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-white/5 pb-4">
                      <span className="text-[11px] font-black tracking-[0.4em] text-broker-cyan uppercase flex items-center gap-4">
                        <Clock size={18} /> {t.horizon}
                      </span>
                      <button 
                        onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                        className="text-[10px] font-black px-6 py-2 transition-all sharp-edge border border-white/10 text-gray-400 hover:text-white hover:border-white/20 uppercase tracking-widest"
                      >
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-3">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <div key={k} className="flex flex-col gap-3">
                            <span className="text-[10px] text-center font-black text-gray-700 uppercase">{k}</span>
                            <input type="number" value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-white/[0.02] border border-white/5 p-4 text-center text-lg font-mono outline-none focus:border-broker-pink focus:bg-white/[0.05] transition-all sharp-edge text-white" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-6">
                        <div className="flex flex-col gap-3">
                           <span className="text-[10px] font-black text-gray-700 uppercase tracking-widest">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-white/[0.02] border border-white/5 p-5 text-sm font-mono outline-none focus:border-broker-pink transition-all sharp-edge text-white" />
                        </div>
                        <div className="flex flex-col gap-3">
                           <span className="text-[10px] font-black text-gray-700 uppercase tracking-widest">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-white/[0.02] border border-white/5 p-5 text-sm font-mono outline-none focus:border-broker-pink transition-all sharp-edge text-white" />
                        </div>
                      </div>
                    )}
                  </div>

                  {/* Profile Section */}
                  <div className="space-y-8">
                    <div className="flex justify-between items-center border-b border-white/5 pb-4">
                       <span className="text-[11px] font-black tracking-[0.4em] text-broker-cyan uppercase flex items-center gap-4">
                         {isComboMode ? <Layers size={20}/> : <Filter size={20}/>} 
                         {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[10px] font-black px-6 py-2 transition-all sharp-edge border ${isComboMode ? 'bg-broker-pink border-broker-pink text-white shadow-[0_0_20px_rgba(243,27,128,0.4)]' : 'border-white/10 text-gray-500 hover:text-white hover:border-white/30'} uppercase tracking-widest`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col gap-10 bg-white/[0.02] p-8 border border-white/5 sharp-edge">
                        <div className="flex flex-col gap-4">
                          <span className="text-[10px] font-black text-gray-700 uppercase tracking-widest">ASSET CLASS</span>
                          <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="w-full bg-black border border-white/10 p-5 text-sm font-mono uppercase outline-none cursor-pointer focus:border-broker-cyan transition-colors sharp-edge text-white">
                            {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-black">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                          </select>
                        </div>
                        <div className="flex flex-col gap-4">
                           <div className="flex justify-between text-[11px] font-black uppercase tracking-[0.3em]">
                             <span className="text-broker-pink">LEVERAGE: {riskScore}</span>
                             <span className="text-gray-500">{getRiskLabel(riskScore)}</span>
                           </div>
                           <input type="range" min="0" max="100" value={riskScore} onChange={(e) => setRiskScore(parseInt(e.target.value))} className="w-full h-1 bg-white/10 appearance-none cursor-pointer accent-broker-pink" />
                        </div>
                      </div>
                    ) : (
                      <div className="flex flex-col gap-4">
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-white/[0.02] border border-white/5 p-6 sharp-edge flex flex-col md:flex-row gap-10 items-center group hover:bg-white/[0.04] transition-all">
                             <div className="w-full md:w-1/3">
                                <span className="text-[9px] font-black text-gray-700 uppercase block mb-3 tracking-widest">{t.assetSlot} {idx+1}</span>
                                <select value={comboSettings[idx].type} onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} className="w-full bg-black border border-white/10 p-4 text-[11px] font-mono uppercase outline-none cursor-pointer group-hover:border-broker-pink/40 transition-colors sharp-edge text-white">
                                  {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-black">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                                </select>
                             </div>
                             <div className="w-full md:w-2/3 flex flex-col justify-center gap-4">
                               <div className="flex justify-between items-end">
                                 <button onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} className={`text-[9px] font-black px-4 py-2 sharp-edge border transition-all ${comboSettings[idx].isAuto ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-600'}`}>{t.autoRisk}</button>
                                 <span className={`text-[11px] font-black uppercase tracking-[0.3em] ${comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}`}>{comboSettings[idx].isAuto ? 'OPTIMAL' : `RISK: ${comboSettings[idx].risk}`}</span>
                               </div>
                               <input type="range" disabled={comboSettings[idx].isAuto} min="0" max="100" value={comboSettings[idx].risk} onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} className={`w-full h-[2px] appearance-none transition-all ${comboSettings[idx].isAuto ? 'opacity-10 bg-white/20' : 'bg-broker-pink/50 cursor-pointer accent-broker-pink'}`} />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handlePredict} disabled={loading} className="w-full py-10 bg-white text-black font-black italic text-4xl tracking-[0.6em] sharp-edge hover:bg-broker-cyan transition-all disabled:opacity-50 flex justify-center items-center gap-8 group">
                  {loading ? <Activity size={40} className="animate-spin" /> : <Zap size={40} className="group-hover:scale-110 transition-transform" />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex flex-col md:flex-row gap-6 p-6">
                <div className="relative flex-grow">
                  <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-gray-700" size={24} />
                  <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="w-full bg-black border border-white/10 py-8 pl-20 pr-10 text-xl font-mono outline-none focus:border-broker-cyan focus:bg-white/[0.02] transition-all sharp-edge shadow-inner text-white" />
                </div>
                <button onClick={handleSearch} disabled={loading} className="px-20 py-8 bg-broker-cyan text-black font-black italic tracking-[0.4em] text-xl uppercase sharp-edge hover:bg-white transition-all shadow-[0_0_40px_rgba(130,234,255,0.2)] disabled:opacity-50">{loading ? '...' : t.searchButton}</button>
              </div>
            )}
          </div>

          <div className="mt-20 space-y-16">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>

            {activePredictions.length === 0 && !loading && (
              <div className="py-40 text-center opacity-20 border-t border-white/5 pt-20">
                <Target size={64} className="mx-auto mb-8 text-gray-800" />
                <p className="text-[12px] font-black text-gray-700 uppercase tracking-[0.8em]">AWAITING TARGET INPUT // STANDBY</p>
              </div>
            )}
          </div>
        </main>
      </div>

      <Dictionary />
    </div>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Prediction, Translation } from '../types';
import { Target, ShieldCheck, Scale, PieChart, Star, Wallet, TrendingUp, AlertTriangle, TrendingDown, ExternalLink, ArrowUpRight } from 'lucide-react';
import SmartText from './SmartText';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
}

const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index }) => {
  const isCombo = !!data.holdings;
