import { GoogleGenAI, GenerateContentParameters } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, ComboAssetConfig } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v1';
const TICKER_CACHE_TTL = 30 * 1000; // Shorter TTL for context accuracy

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Robustly extract JSON from a potentially messy text response.
 */
function extractJson(text: string): any {
  if (!text) return [];
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match && match[1]) {
      try {
        return JSON.parse(match[1]);
      } catch (e2) {
        console.error("Failed to parse extracted JSON block:", e2);
      }
    }
    const firstBracket = Math.min(
      text.indexOf('{') === -1 ? Infinity : text.indexOf('{'),
      text.indexOf('[') === -1 ? Infinity : text.indexOf('[')
    );
    const lastBracket = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));

    if (firstBracket !== Infinity && lastBracket !== -1 && lastBracket > firstBracket) {
      try {
        return JSON.parse(text.substring(firstBracket, lastBracket + 1));
      } catch (e3) {
        console.error("Failed to parse bracket-sliced text:", e3);
      }
    }
    return [];
  }
}

async function callWithRetry(
  params: GenerateContentParameters,
  maxRetries: number = 3
): Promise<any> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let delay = 2000;

  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await ai.models.generateContent(params);
      return response;
    } catch (error: any) {
      const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');

      if (isQuota && i < maxRetries - 1) {
        await sleep(delay);
        delay *= 2;
        continue;
      }
      throw error; 
    }
  }
}

/**
 * Scrapes live data using Google Search to provide fresh context for AI predictions.
 */
export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const response = await callWithRetry({
      model: "gemini-3-flash-preview",
      contents: "Return a RAW JSON array of current price and 24h change (%) for: S&P500, NASDAQ, BTC, ETH, Gold, NVDA, TSLA, US10Y. Format: [{symbol, price, change, isUp}]. No Markdown.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Quant Scraper. Return ONLY valid JSON array. No backticks.",
      },
    });

    const data = extractJson(response.text || '[]');
    if (Array.isArray(data) && data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return Array.isArray(data) ? data : MOCK_TICKER_DATA;
  } catch (error) { 
    console.error("Live context scrape failed:", error);
    return MOCK_TICKER_DATA; 
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  const comboInfo = comboSettings 
    ? `COMBO MODE ACTIVATED: Analyze as a correlated set. 3 Assets Required. Types: ${comboSettings.map(c => c.type).join(', ')}. Target risks: ${comboSettings.map(c => c.risk).join(', ')}.`
    : `SINGLE ASSET MODE: Market: ${type}, Risk Profile: ${riskScore}/100.`;

  const prompt = `
    CURRENT MARKET SNAPSHOT: ${context}

    USER CONFIGURATION:
    - Language: ${lang}
    - Speculative Capital: ${budget ? `$${budget} USD` : 'Indeterminate'}
    - Prediction Horizon: ${totalHours} hours
    - Strategy Constraints: ${comboInfo}

    TASK: Generate high-precision market predictions based on the above constraints and real-time news data.
  `;

  const response = await callWithRetry({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION + " Provide exactly 5 predictions in a JSON array. High volatility awareness required.",
      thinkingConfig: { thinkingBudget: 4000 },
    },
  });

  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = chunks
    .filter((c: any) => c.web)
    .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

  let data = extractJson(response.text || '[]');

  // Ensure we return an array
  if (!Array.isArray(data)) {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
       // Check if AI returned { "predictions": [...] }
       const possibleArray = data.predictions || data.results || data.items || Object.values(data).find(v => Array.isArray(v));
       if (Array.isArray(possibleArray)) {
         data = possibleArray;
       } else {
         data = [data]; // Wrap single object in array
       }
    } else {
      data = [];
    }
  }

  return data.map((item: any) => ({ 
    ...item, 
    groundingSources: sources,
    pros: Array.isArray(item.pros) ? item.pros : [],
    cons: Array.isArray(item.cons) ? item.cons : []
  }));
};

