                                 <button onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} className={`px-2 py-0.5 border ${comboSettings[idx].isAuto ? 'border-broker-green text-broker-green' : 'border-white/10 text-gray-600'}`}>{t.autoRisk}</button>
                                 <span className={comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}>{comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}</span>
                               </div>
                               <input type="range" disabled={comboSettings[idx].isAuto} min="0" max="100" value={comboSettings[idx].risk} onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} className="w-full h-[1px] accent-broker-pink disabled:opacity-10" />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>

                <button onClick={handleExecute} disabled={loading} className="w-full py-4 bg-white text-black font-black text-lg tracking-widest sharp-edge hover:bg-broker-cyan transition-all disabled:opacity-50 flex justify-center items-center gap-4 group">
                  {loading ? <Activity size={20} className="animate-spin" /> : <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform" />}
                  {loading ? t.loading : t.predict}
                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-2">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-white/5 border border-white/10 p-4 text-sm font-mono outline-none focus:border-broker-cyan sharp-edge" />
                <button onClick={handleSearch} disabled={loading} className="px-8 bg-broker-cyan text-black font-black tracking-widest text-xs uppercase sharp-edge hover:bg-white transition-all disabled:opacity-50">{loading ? '...' : t.searchButton}</button>
              </div>
            )}
          </div>

          <div className="mt-12 space-y-6">
            <AnimatePresence mode="popLayout">
              {Array.isArray(activePredictions) && activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>

            {(!Array.isArray(activePredictions) || activePredictions.length === 0) && !loading && (
              <div className="py-20 text-center opacity-10 border-t border-white/5">
                <ShieldCheck size={48} className="mx-auto mb-4 text-white" />
                <p className="text-[10px] font-black uppercase tracking-[0.5em]">System Idle // Ready for Input</p>
              </div>
            )}
          </div>
        </main>
      </div>

      <Dictionary />
    </div>
  );
}

import { GoogleGenAI, GenerateContentParameters, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, ComboAssetConfig } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v2';
const TICKER_CACHE_TTL = 30 * 1000;

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

/**
 * Robustly extract JSON from a potentially messy text response.
 */
function extractJson(text: string): any {
  if (!text) return [];
  try {
    // Attempt direct parse first
    return JSON.parse(text);
  } catch (e) {
    // Fallback to regex for code blocks
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match && match[1]) {
      try {
        return JSON.parse(match[1]);
      } catch (e2) {}
    }
    // Deep fallback for raw brackets
    const firstBracket = Math.min(
      text.indexOf('{') === -1 ? Infinity : text.indexOf('{'),
      text.indexOf('[') === -1 ? Infinity : text.indexOf('[')
    );
    const lastBracket = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));

    if (firstBracket !== Infinity && lastBracket !== -1 && lastBracket > firstBracket) {
      try {
        return JSON.parse(text.substring(firstBracket, lastBracket + 1));
      } catch (e3) {}
    }
    return [];
  }
}

async function callWithRetry(
  params: GenerateContentParameters,
  maxRetries: number = 3
): Promise<any> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let delay = 2000;

  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await ai.models.generateContent(params);
      return response;
    } catch (error: any) {
      const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');

      if (isQuota && i < maxRetries - 1) {
        await sleep(delay);
        delay *= 2;
        continue;
      }
      throw error; 
    }
  }
}

/**
 * Schema for Prediction objects to ensure field mapping is consistent.
 */
const predictionSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING, description: "Full descriptive name of the asset or strategy." },
      ticker: { type: Type.STRING, description: "Market symbol (e.g. BTC, NVDA, XAU)." },
      type: { type: Type.STRING, description: "Asset class (CRYPTO, STOCK, etc)." },
      expectedProfit: { type: Type.STRING, description: "Projected yield (e.g. +15.4%)." },
      expectedLoss: { type: Type.STRING, description: "Projected risk/stop loss (e.g. -4.2%)." },
      riskRewardRatio: { type: Type.STRING, description: "R/R ratio string (e.g. 1:3.5)." },
      pros: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of growth catalysts." },
      cons: { type: Type.ARRAY, items: { type: Type.STRING }, description: "List of risk factors." },
      withdraw: { type: Type.STRING, description: "Exit action (e.g. SELL, HOLD, BUY)." },
      confidence: { type: Type.NUMBER, description: "Trust percentage (0-100)." },
      budgetImpact: {
        type: Type.OBJECT,
        properties: {
          profitUsd: { type: Type.STRING, description: "Projected USD profit." },
          lossUsd: { type: Type.STRING, description: "Projected USD max loss." }
        },
        required: ["profitUsd", "lossUsd"]
      }
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"]
  }
};

/**
 * Scrapes live data using Google Search to provide fresh context for AI predictions.
 */
export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const response = await callWithRetry({
      model: "gemini-3-flash-preview",
      contents: "Return a RAW JSON array of current price and 24h change (%) for: S&P500, NASDAQ, BTC, ETH, Gold, NVDA, TSLA, US10Y. Format: [{symbol, price, change, isUp}]. No Markdown.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Quant Scraper. Return ONLY valid JSON array. No backticks.",
      },
    });

    const data = extractJson(response.text || '[]');
    if (Array.isArray(data) && data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return Array.isArray(data) ? data : MOCK_TICKER_DATA;
  } catch (error) { 
    console.error("Live context scrape failed:", error);
    return MOCK_TICKER_DATA; 
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  const comboInfo = comboSettings 
    ? `COMBO MODE ACTIVATED: Analyze as a correlated set. 3 Assets Required. Types: ${comboSettings.map(c => c.type).join(', ')}. Target risks: ${comboSettings.map(c => c.risk).join(', ')}.`
    : `SINGLE ASSET MODE: Market: ${type}, Risk Profile: ${riskScore}/100.`;

  const prompt = `
    CURRENT MARKET SNAPSHOT: ${context}
    LANGUAGE: ${lang}
    BUDGET: ${budget ? `$${budget} USD` : 'NONE'}
    HORIZON: ${totalHours} HOURS
    CONSTRAINTS: ${comboInfo}

    TASK: Generate 5 quantitative predictions in the specified JSON format.
  `;

  const response = await callWithRetry({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION + " High-precision JSON output required. Follow schema strictly.",
      responseMimeType: "application/json",
      responseSchema: predictionSchema,
      thinkingConfig: { thinkingBudget: 4000 },
    },
  });

  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = chunks
    .filter((c: any) => c.web)
    .map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

  let data = extractJson(response.text || '[]');

  if (!Array.isArray(data)) {
    data = data.predictions || data.results || [data];
  }

  return Array.isArray(data) ? data.map((item: any) => ({ 
    ...item, 
    groundingSources: sources,
    pros: Array.isArray(item.pros) ? item.pros : [],
    cons: Array.isArray(item.cons) ? item.cons : []
  })) : [];
};

