import React, { useState, useCallback, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS, COLORS } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Dictionary from './components/Dictionary';
import { Activity, Globe, Wallet, Clock, Layers, Filter, Search, ShieldCheck, X, Command, Cpu, ArrowRight } from 'lucide-react';

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [budget, setBudget] = useState<number | null>(null);
  const [isComboMode, setIsComboMode] = useState(false);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 0, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAutoRiskStandard, setIsAutoRiskStandard] = useState(false);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  const activePredictionsRaw = viewMode === 'predict' ? predictorResults : searchResults;

  // Requirement: Only show results with trust = 75% or higher
  const activePredictions = useMemo(() => {
    return (Array.isArray(activePredictionsRaw) ? activePredictionsRaw : [])
      .filter(p => (p.confidence || 0) >= 75);
  }, [activePredictionsRaw]);

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      return Math.max(0, Math.floor((e.getTime() - s.getTime()) / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const handleExecute = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = Array.isArray(tickerData) ? tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ') : '';

      const results = await fetchPredictions(
        totalHours || 168, 
        isAutoRiskStandard ? 'AUTO' : riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError(err?.message || 'Execution failed');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, isAutoRiskStandard, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const results = await searchAssets(`${searchQuery}`, lang);
      setSearchResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError('Search Error');
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-[#141415] selection:bg-broker-pink selection:text-white">
      <div className="relative z-10 flex flex-col min-h-screen">
        <header className="px-6 py-4 flex justify-between items-center max-w-6xl mx-auto w-full border-b border-white/5 bg-[#141415]/80 backdrop-blur-md sticky top-0 z-50">
          <div className="flex items-center gap-3">
            <Cpu size={24} className="text-broker-cyan" />
            <h1 className="text-xl font-black italic tracking-tight uppercase text-white">
              {t.title}
            </h1>
          </div>

          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 sharp-edge border border-white/5">
                <Wallet size={14} className="text-broker-green" />
                <input 
                  type="number" 
                  value={budget || ''}
                  onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                  placeholder={t.budgetPlaceholder}
                  className="bg-transparent text-xs font-mono outline-none w-20 text-white placeholder:text-gray-600"
                />
                <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest pl-2 border-l border-white/10">{t.budgetLabel}</span>
             </div>

             <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 sharp-edge border border-white/5">
                <Globe size={14} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer">
                  <option value="es" className="bg-[#141415]">ES</option>
                  <option value="en" className="bg-[#141415]">EN</option>
                  <option value="fr" className="bg-[#141415]">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 py-8 max-w-4xl">
          <AnimatePresence>
            {error && (
              <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mb-6">
                <div className="bg-broker-red/10 border border-broker-red/30 p-4 sharp-edge flex items-center justify-between">
                  <span className="text-[10px] font-black uppercase tracking-widest text-broker-red">{error}</span>
                  <X size={16} onClick={() => setError(null)} className="cursor-pointer text-broker-red" />
                </div>
