                className={`flex-1 py-3 text-[10px] font-black tracking-widest uppercase flex items-center justify-center gap-2 transition-all sharp-edge border-t border-x ${viewMode === tab.id ? 'bg-[#242325] text-white border-white/10 shadow-sm' : 'bg-transparent text-gray-600 border-transparent hover:text-white'}`}
