          <div className="bg-[#242325] border border-white/10 sharp-edge p-6 shadow-xl">
            {viewMode === 'predict' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-4">
                    <div className="flex justify-between items-center border-b border-white/5 pb-2">
                      <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2">
                        <Clock size={14} /> {t.horizon}
                      </span>
                      <button 
                        onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                        className="text-[8px] font-black px-2 py-1 text-gray-500 hover:text-white border border-white/10 sharp-edge"
                      >
                        {horizonMode === 'precise' ? t.calendar : t.precise}
                      </button>
                    </div>
                    {horizonMode === 'precise' ? (
                      <div className="grid grid-cols-5 gap-2">
                        {['h', 'd', 'w', 'm', 'y'].map((k) => (
                          <div key={k} className="flex flex-col gap-1">
                            <span className="text-[8px] text-center font-black text-gray-700 uppercase">{k}</span>
                            <input type="number" value={(time as any)[k] || ''} onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} className="bg-white/5 border border-white/5 p-2 text-center text-xs font-mono outline-none focus:border-broker-pink sharp-edge" />
                          </div>
                        ))}
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-3">
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-700 uppercase">{t.startDate}</span>
                           <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-xs font-mono outline-none focus:border-broker-pink sharp-edge text-white" />
                        </div>
                        <div className="flex flex-col gap-1">
                           <span className="text-[8px] font-black text-gray-700 uppercase">{t.endDate}</span>
                           <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-xs font-mono outline-none focus:border-broker-pink sharp-edge text-white" />
                        </div>
                      </div>
                    )}
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between items-center border-b border-white/5 pb-2">
                       <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2">
                         {isComboMode ? <Layers size={14}/> : <Filter size={14}/>} {isComboMode ? t.superCombo : t.strategy}
                       </span>
                       {/* Requirement: Make combo mode selector highlight as active standard option */}
                       <button 
                         onClick={() => setIsComboMode(!isComboMode)} 
                         className={`text-[8px] font-black px-3 py-1 border transition-all duration-300 sharp-edge ${isComboMode ? 'bg-broker-cyan border-broker-cyan text-black shadow-[0_0_15px_rgba(130,234,255,0.4)]' : 'border-white/20 text-white hover:bg-white/10'}`}
                       >
                         {t.comboMode}
                       </button>
                    </div>

                    {!isComboMode ? (
                      <div className="grid grid-cols-1 gap-4 bg-white/5 p-4 sharp-edge">
                        <select value={type} onChange={(e) => setType(e.target.value as MarketType)} className="w-full bg-black/40 border border-white/10 p-2.5 text-xs font-mono uppercase outline-none cursor-pointer sharp-edge">
                          {Object.values(MarketType).map(m => <option key={m} value={m} className="bg-[#1A1A1C]">{t[m as keyof typeof t] || m.toUpperCase()}</option>)}
                        </select>
                        <div className="flex flex-col gap-2">
                           <div className="flex justify-between items-end text-[8px] font-black uppercase">
                             <div className="flex flex-col gap-1">
                                <span className="text-broker-pink">RISK INDEX: {isAutoRiskStandard ? 'AUTO' : riskScore}</span>
                                <span className="text-gray-600">THROTTLE</span>
                             </div>
                             {/* Requirement: Add AUTO to standard mode */}
                             <button 
                               onClick={() => setIsAutoRiskStandard(!isAutoRiskStandard)} 
                               className={`px-3 py-1 border transition-all ${isAutoRiskStandard ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500'}`}
                             >
                               {t.autoRisk}
