                             onChange={(e) => setRiskScore(parseInt(e.target.value))} 
                             className={`w-full h-1 bg-white/10 appearance-none transition-all ${isAutoRiskStandard ? 'opacity-20' : 'cursor-pointer accent-broker-pink'}`} 
