                </button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-2">
                <input type="text" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSearch()} placeholder={t.searchPlaceholder} className="flex-grow bg-white/5 border border-white/10 p-4 text-sm font-mono outline-none focus:border-broker-cyan sharp-edge" />
                <button onClick={handleSearch} disabled={loading} className="px-8 bg-broker-cyan text-black font-black tracking-widest text-xs uppercase sharp-edge hover:bg-white transition-all disabled:opacity-50">{loading ? '...' : t.searchButton}</button>
              </div>
            )}
          </div>

          <div className="mt-12 space-y-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} />
              ))}
            </AnimatePresence>

            {activePredictions.length === 0 && !loading && (
              <div className="py-20 text-center opacity-10 border-t border-white/5">
                <ShieldCheck size={48} className="mx-auto mb-4 text-white" />
                <p className="text-[10px] font-black uppercase tracking-[0.5em]">System Idle // Filter Active (Trust >= 75%)</p>
              </div>
            )}
          </div>
        </main>
      </div>

      <Dictionary />
    </div>
  );
}

import React from 'react';
