import { Prediction, Translation } from '../types';
import { ShieldCheck, Scale, PieChart, Star, Wallet, TrendingUp, AlertTriangle, TrendingDown, ExternalLink, ArrowUpRight, Activity } from 'lucide-react';
import SmartText from './SmartText';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
}

const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index }) => {
  const isCombo = !!data.holdings && Array.isArray(data.holdings) && data.holdings.length > 0;
