            <PieChart size={12} /> PORTFOLIO ALLOCATION
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {data.holdings.map((h, i) => (
              <div key={i} className="bg-white/5 p-3 border border-white/5 sharp-edge">
                <div className="text-[9px] font-black text-gray-400 uppercase truncate mb-1">{h.name}</div>
                <div className="flex justify-between items-center">
                  <span className="text-[8px] font-mono text-gray-600">{h.ticker}</span>
                  <span className="text-lg font-mono font-black text-white">{h.weight}%</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
        {[
          { label: t.expectedProfit, val: data.expectedProfit || '---', color: 'text-broker-green', icon: <TrendingUp size={12}/> },
          { label: t.expectedLoss, val: data.expectedLoss || '---', color: 'text-broker-red', icon: <TrendingDown size={12}/> },
          { label: t.riskRewardRatio, val: data.riskRewardRatio || '---', color: 'text-broker-cyan', icon: <Scale size={12}/> },
          { label: t.finImpact, val: data.budgetImpact?.profitUsd || '---', color: 'text-white', icon: <Wallet size={12}/> }
