      </div>

      {data.groundingSources && data.groundingSources.length > 0 && (
        <div className="mb-8 p-3 bg-black/60 border border-white/5 sharp-edge">
          <div className="text-[8px] font-black text-gray-600 uppercase tracking-widest mb-2 flex items-center gap-2">
            <ShieldCheck size={12} /> VERIFIED DATA SOURCES
          </div>
          <div className="flex flex-wrap gap-2">
            {data.groundingSources.map((source, i) => (
              <a key={i} href={source.uri} target="_blank" rel="noopener noreferrer" className="text-[9px] font-mono text-gray-500 hover:text-broker-cyan transition-colors bg-white/5 px-2 py-1 flex items-center gap-1 border border-white/5">
                {source.title ? source.title.substring(0, 30) : 'Source'}... <ArrowUpRight size={8} />
              </a>
            ))}
          </div>
