      )}

      <div className="flex justify-between items-center pt-4 border-t border-white/5">
        <span className="text-[9px] font-black uppercase tracking-[0.4em] text-gray-700">EXECUTION // READY</span>
        <button className={`px-8 py-2 text-[10px] font-black tracking-widest uppercase sharp-edge transition-all ${isCombo ? 'bg-[#FFD700] text-black' : 'bg-white text-black hover:bg-broker-cyan'}`}>
          {safeWithdraw}
        </button>
