            <div className="flex items-center gap-2">
              <span className="text-[8px] text-gray-500 font-black uppercase">TRUST</span>
              <div className="w-16 h-[2px] bg-white/5 overflow-hidden">
                <motion.div 
                   initial={{ width: 0 }} 
                   animate={{ width: `${data.confidence || 0}%` }} 
                   transition={{ duration: 1.5, delay: index * 0.1 + 0.5 }}
                   className={`h-full ${isCombo ? 'bg-[#FFD700]' : 'bg-broker-cyan'}`} 
                />
              </div>
              <span className={`text-[8px] font-mono font-black ${accentColor}`}>{data.confidence || 0}%</span>
