          <div key={i} className="bg-black/30 p-3 border border-white/5 transition-all hover:bg-black/50">
            <div className={`text-[8px] font-black uppercase flex items-center gap-2 mb-1 ${stat.color} opacity-60`}>
              {stat.icon} {stat.label}
            </div>
            <div className="text-xl font-mono font-black text-white">{stat.val}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-8">
        <div className="bg-black/20 p-4 border border-white/5 border-l-broker-green transition-all hover:border-white/10">
          <h4 className="text-broker-green text-[9px] font-black mb-3 flex items-center gap-2 uppercase tracking-widest">
            <TrendingUp size={14}/> {t.pros}
