              <a key={i} href={source.uri} target="_blank" rel="noopener noreferrer" className="text-[9px] font-mono text-gray-500 hover:text-broker-cyan transition-colors bg-white/5 px-2 py-1 flex items-center gap-1 border border-white/5">
                {source.title ? source.title.substring(0, 30) : 'Source'}... <ArrowUpRight size={8} />
