        </div>
      )}

      <div className="flex justify-between items-center pt-4 border-t border-white/5">
        <span className="text-[9px] font-black uppercase tracking-[0.4em] text-gray-700">EXECUTION // READY</span>
        <motion.button 
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className={`px-8 py-2 text-[10px] font-black tracking-widest uppercase sharp-edge transition-all ${isCombo ? 'bg-[#FFD700] text-black hover:shadow-[0_0_15px_rgba(255,215,0,0.4)]' : 'bg-white text-black hover:bg-broker-cyan hover:shadow-[0_0_15px_rgba(130,234,255,0.4)]'}`}
        >
          {safeWithdraw}
        </motion.button>
      </div>
