import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Dictionary from './components/Dictionary';
import { Activity, Globe, Wallet, Clock, Filter, Search, ShieldCheck, X, Command, Cpu, ArrowRight } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [budget, setBudget] = useState<number | null>(null);
  const [comboSettings, setComboSettings] = useState<ComboAssetConfig[]>([
    { type: MarketType.STOCKS, risk: 50, isAuto: true },
    { type: MarketType.CRYPTO, risk: 50, isAuto: true },
    { type: MarketType.COMMODITIES, risk: 50, isAuto: true }
  ]);

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 24, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAutoRiskStandard, setIsAutoRiskStandard] = useState(true);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];

  const isComboMode = type === MarketType.COMBO;

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const autoRiskCalculated = useMemo(() => {
    if (totalHours <= 24) return 85; 
    if (totalHours <= 168) return 65; 
    if (totalHours <= 720) return 50; 
    if (totalHours <= 4320) return 30; 
    return 15; 
  }, [totalHours]);

  useEffect(() => {
    if (isAutoRiskStandard) {
      setRiskScore(autoRiskCalculated);
    }
  }, [autoRiskCalculated, isAutoRiskStandard]);

  const activePredictionsRaw = viewMode === 'predict' ? predictorResults : searchResults;

  const activePredictions = useMemo(() => {
    return (Array.isArray(activePredictionsRaw) ? activePredictionsRaw : [])
      .filter(p => (p.confidence || 0) >= 75);
  }, [activePredictionsRaw]);

  const handleExecute = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = Array.isArray(tickerData) ? tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ') : '';

      const results = await fetchPredictions(
        totalHours || 24, 
        isAutoRiskStandard ? 'AUTO' : riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError(err?.message || 'Execution failed');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, isAutoRiskStandard, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const results = await searchAssets(`${searchQuery}`, lang);
      setSearchResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError('Search Error');
