import { GoogleGenAI, GenerateContentParameters, Type } from "@google/genai";
import { SYSTEM_INSTRUCTION, MOCK_TICKER_DATA } from "../constants";
import { Prediction, TickerItem, ComboAssetConfig } from "../types";

const TICKER_CACHE_KEY = 'ai_broker_ticker_v3';
const TICKER_CACHE_TTL = 30 * 1000;

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

function extractJson(text: string): any {
  if (!text) return [];
  try {
    return JSON.parse(text);
  } catch (e) {
    const match = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (match && match[1]) {
      try {
        return JSON.parse(match[1]);
      } catch (e2) {}
    }
    const firstBracket = Math.min(
      text.indexOf('{') === -1 ? Infinity : text.indexOf('{'),
      text.indexOf('[') === -1 ? Infinity : text.indexOf('[')
    );
    const lastBracket = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));

    if (firstBracket !== Infinity && lastBracket !== -1 && lastBracket > firstBracket) {
      try {
        return JSON.parse(text.substring(firstBracket, lastBracket + 1));
      } catch (e3) {}
    }
    return [];
  }
}

async function callWithRetry(
  params: GenerateContentParameters,
  maxRetries: number = 3
): Promise<any> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  let delay = 2000;

  for (let i = 0; i < maxRetries; i++) {
    try {
      const response = await ai.models.generateContent(params);
      return response;
    } catch (error: any) {
      const isQuota = error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED');

      if (isQuota && i < maxRetries - 1) {
        await sleep(delay);
        delay *= 2;
        continue;
      }
      throw error; 
    }
  }
}

const predictionSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      name: { type: Type.STRING, description: "Full descriptive name of the strategy." },
      ticker: { type: Type.STRING, description: "Main ticker or 'COMBO'." },
      type: { type: Type.STRING, description: "Asset class." },
      expectedProfit: { type: Type.STRING, description: "Yield percentage." },
      expectedLoss: { type: Type.STRING, description: "Risk percentage." },
      riskRewardRatio: { type: Type.STRING, description: "R/R ratio." },
      pros: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Alpha factors." },
      cons: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Beta factors." },
      withdraw: { type: Type.STRING, description: "Exit action. MUST NOT BE 'BUY'. Use 'SELL', 'HOLD', or 'CLOSE'." },
      confidence: { type: Type.NUMBER, description: "Trust percentage (0-100)." },
      holdings: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            ticker: { type: Type.STRING },
            weight: { type: Type.NUMBER, description: "Percentage of budget (0-100)." }
          },
          required: ["name", "ticker", "weight"]
        },
        description: "List of exactly 3 correlated assets for COMBO mode."
      },
      budgetImpact: {
        type: Type.OBJECT,
        properties: {
          profitUsd: { type: Type.STRING },
          lossUsd: { type: Type.STRING }
        },
        required: ["profitUsd", "lossUsd"]
      }
    },
    required: ["name", "ticker", "type", "expectedProfit", "expectedLoss", "riskRewardRatio", "pros", "cons", "withdraw", "confidence"]
  }
};

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const response = await callWithRetry({
      model: "gemini-3-flash-preview",
      contents: "Return a JSON array of current market data for top global assets across all classes (Indices, Commodities, Crypto, Forex). No backticks.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Global Quant Scraper. JSON array only.",
      },
    });

    const data = extractJson(response.text || '[]');
    if (Array.isArray(data) && data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return Array.isArray(data) ? data : MOCK_TICKER_DATA;
  } catch (error) { 
    return MOCK_TICKER_DATA; 
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number | string,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  const isCombo = type === 'combo';
  const comboInfo = comboSettings 
    ? `COMBO MODE (3-in-1 GLOBAL STRATEGY): Analyze a correlated set of 3 specific assets from any global market. Types: ${comboSettings.map(c => c.type).join(', ')}. Weights per asset must sum to 100%.`
    : `SINGLE ASSET MODE: Market: ${type}, Risk Profile: ${riskScore === 'AUTO' ? 'OPTIMAL/AUTO' : riskScore + '/100'}.`;

  const prompt = `
    GLOBAL MARKET CONTEXT: ${context}
    LANG: ${lang}
    BUDGET: ${budget ? `$${budget}` : 'N/A'}
    HORIZON: ${totalHours}h
    PROFILE: ${comboInfo}

    TASK: Scan all global activities across all exchanges and asset classes.
    GENERATE 5 PREDICTIONS. 
    MANDATORY: NEVER use 'BUY' for the 'withdraw' field. Use 'SELL' or 'HOLD' or 'CLOSE' only.
    MANDATORY: In COMBO mode, each prediction MUST include a 'holdings' array of EXACTLY 3 assets with weight percentages.
    MANDATORY: Trust/Confidence must be >= 75% for high-quality signals.
  `;

  const response = await callWithRetry({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION + " Strictly JSON. 'withdraw' MUST NOT BE 'BUY'. IN COMBO MODE, EACH CARD IS A 3-IN-1 STRATEGY.",
      responseMimeType: "application/json",
      responseSchema: predictionSchema,
      thinkingConfig: { thinkingBudget: 4000 },
    },
  });

  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = chunks.filter((c: any) => c.web).map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

  let data = extractJson(response.text || '[]');
  if (!Array.isArray(data)) data = data.predictions || [data];

  return Array.isArray(data) ? data.map((item: any) => ({ 
    ...item, 
    groundingSources: sources,
    pros: Array.isArray(item.pros) ? item.pros : [],
    cons: Array.isArray(item.cons) ? item.cons : []
  })) : [];
};

export const searchAssets = async (query: string, lang: string): Promise<Prediction[]> => {
  const response = await callWithRetry({
    model: "gemini-3-flash-preview",
    contents: `Deep Global Search: ${query}. Lang: ${lang}. Current international market context verified. MANDATORY: 'withdraw' MUST NOT BE 'BUY'.`,
    config: {
