  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const autoRiskCalculated = useMemo(() => {
    if (totalHours <= 24) return 85; 
    if (totalHours <= 168) return 65; 
    if (totalHours <= 720) return 50; 
    if (totalHours <= 4320) return 30; 
    return 15; 
  }, [totalHours]);

  useEffect(() => {
    if (isAutoRiskStandard) {
      setRiskScore(autoRiskCalculated);
    }
  }, [autoRiskCalculated, isAutoRiskStandard]);

  const activePredictionsRaw = viewMode === 'predict' ? predictorResults : searchResults;

  const activePredictions = useMemo(() => {
    return (Array.isArray(activePredictionsRaw) ? activePredictionsRaw : [])
      .filter(p => (p.confidence || 0) >= 75);
  }, [activePredictionsRaw]);

  const handleExecute = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = Array.isArray(tickerData) ? tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ') : '';

      const results = await fetchPredictions(
        totalHours || 24, 
        isAutoRiskStandard ? 'AUTO' : riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings : null, 
        context
      );
      setPredictorResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError(err?.message || 'Execution failed');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, isAutoRiskStandard, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const results = await searchAssets(`${searchQuery}`, lang);
      setSearchResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError('Search Error');
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<ComboAssetConfig>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-[#141415] selection:bg-broker-pink selection:text-white overflow-x-hidden">
      <div className="relative z-10 flex flex-col min-h-screen">
        <header className="px-6 py-4 flex justify-between items-center max-w-6xl mx-auto w-full border-b border-white/5 bg-[#141415]/80 backdrop-blur-md sticky top-0 z-50">
          <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="flex items-center gap-3">
            <Cpu size={24} className="text-broker-cyan" />
            <h1 className="text-xl font-black italic tracking-tight uppercase text-white font-sans">
              {t.title}
            </h1>
          </motion.div>

          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 sharp-edge border border-white/5">
                <Globe size={14} className="text-broker-cyan" />
                <select value={lang} onChange={(e) => setLang(e.target.value as Language)} className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer font-sans">
                  <option value="es" className="bg-[#141415]">ES</option>
                  <option value="en" className="bg-[#141415]">EN</option>
                  <option value="fr" className="bg-[#141415]">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="container mx-auto px-4 py-8 max-w-4xl">
          <AnimatePresence>
            {error && (
              <motion.div initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="mb-6">
                <div className="bg-broker-red/10 border border-broker-red/30 p-4 sharp-edge flex items-center justify-between">
                  <span className="text-[10px] font-black uppercase tracking-widest text-broker-red font-sans">{error}</span>
                  <X size={16} onClick={() => setError(null)} className="cursor-pointer text-broker-red" />
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <div className="flex mb-1">
            {[
              { id: 'predict', icon: <Command size={14}/>, label: t.tabPredictor },
              { id: 'search', icon: <Search size={14}/>, label: t.tabSearch },
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setViewMode(tab.id as any)}
                className={`flex-1 py-3 text-[10px] font-black tracking-widest uppercase flex items-center justify-center gap-2 transition-all sharp-edge border-t border-x font-sans ${viewMode === tab.id ? 'bg-[#242325] text-white border-white/10 shadow-sm' : 'bg-transparent text-gray-600 border-transparent hover:text-white'}`}
              >
                {tab.icon} {tab.label}
              </button>
            ))}
          </div>

          <div className="bg-[#242325] border border-white/10 sharp-edge p-6 shadow-xl">
            {viewMode === 'predict' && (
              <div className="space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                  <div className="space-y-6">
                    <div className="space-y-4">
                      <div className="flex justify-between items-center border-b border-white/5 pb-2">
                        <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
                          <Clock size={14} /> {t.horizon}
                        </span>
                        <button 
                          onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                          className="text-[8px] font-black px-2 py-1 text-gray-500 hover:text-white border border-white/10 sharp-edge transition-all font-sans"
                        >
                          {horizonMode === 'precise' ? t.calendar : t.precise}
                        </button>
                      </div>
                      {horizonMode === 'precise' ? (
                        <div className="grid grid-cols-5 gap-2">
                          {['h', 'd', 'w', 'm', 'y'].map((k) => (
                            <div key={k} className="flex flex-col gap-1">
                              <span className="text-[8px] text-center font-black text-gray-700 uppercase font-sans">{k}</span>
                              <input 
                                type="number" 
                                value={(time as any)[k] || ''} 
                                onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} 
                                className="bg-white/5 border border-white/5 p-2 text-center text-xs font-mono num-font outline-none focus:border-broker-pink/50 focus:shadow-[0_0_10px_rgba(243,27,128,0.1)] sharp-edge text-white transition-all shimmer-focus" 
                              />
                            </div>
                          ))}
                        </div>
                      ) : (
                        <div className="grid grid-cols-2 gap-3">
                          <div className="flex flex-col gap-1">
                            <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.startDate}</span>
                            <input type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-xs font-mono num-font outline-none focus:border-broker-pink/50 sharp-edge text-white transition-all shimmer-focus" />
                          </div>
                          <div className="flex flex-col gap-1">
                            <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.endDate}</span>
                            <input type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-xs font-mono num-font outline-none focus:border-broker-pink/50 sharp-edge text-white transition-all shimmer-focus" />
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Budget Box below Time Box */}
                    <div className="space-y-2">
                      <span className="text-[9px] font-black tracking-widest text-broker-green uppercase flex items-center gap-2 font-sans">
                        <Wallet size={14} /> {t.budgetLabel}
                      </span>
                      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex items-center gap-2 bg-white/5 px-4 py-3 sharp-edge border border-white/5 focus-within:border-broker-green/50 focus-within:shadow-[0_0_10px_rgba(29,240,150,0.1)] transition-all">
                        <span className="text-xs font-mono text-broker-green">$</span>
                        <input 
                          type="number" 
                          value={budget || ''}
                          onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                          placeholder={t.budgetPlaceholder}
                          className="bg-transparent text-sm font-mono num-font outline-none w-full text-white placeholder:text-gray-700 shimmer-focus"
                        />
                      </motion.div>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <div className="flex justify-between items-center border-b border-white/5 pb-2">
                       <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
                         <Filter size={14}/> {t.strategy}
                       </span>
                    </div>

                    <div className="grid grid-cols-1 gap-4 bg-white/5 p-4 sharp-edge relative overflow-hidden">
                      <div className="flex flex-col gap-2">
                         <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.priority}</span>
                         <select 
                            value={type} 
                            onChange={(e) => setType(e.target.value as MarketType)} 
                            className={`w-full bg-black/40 border p-2.5 text-xs font-sans uppercase outline-none cursor-pointer sharp-edge transition-all ${isComboMode ? 'border-broker-cyan shadow-[0_0_15px_rgba(130,234,255,0.2)]' : 'border-white/10'}`}
                          >
                           {Object.values(MarketType).map(m => (
                             <option key={m} value={m} className="bg-[#1A1A1C]">
                               {t[m as keyof typeof t] || m.toUpperCase()}
                             </option>
                           ))}
                         </select>
                      </div>

                      {!isComboMode ? (
                        <div className="flex flex-col gap-3">
                           <div className="flex justify-between items-end text-[8px] font-black uppercase font-sans">
                             <div className="flex flex-col gap-1">
                                <span className="text-broker-pink">RISK INDEX: <span className="num-font font-mono">{isAutoRiskStandard ? 'AUTO' : riskScore}</span></span>
                                <span className="text-gray-600">THROTTLE</span>
                             </div>
                             <button 
                               onClick={() => setIsAutoRiskStandard(!isAutoRiskStandard)} 
                               className={`px-3 py-1 border transition-all duration-300 sharp-edge font-sans ${isAutoRiskStandard ? 'bg-broker-green border-broker-green text-black shadow-[0_0_10px_rgba(29,240,150,0.3)]' : 'border-white/10 text-gray-500'}`}
                             >
                               {t.autoRisk}
                             </button>
                           </div>
                           <input 
                             type="range" 
                             disabled={isAutoRiskStandard} 
                             min="0" max="100" 
                             value={riskScore} 
                             onChange={(e) => setRiskScore(parseInt(e.target.value))} 
                             className={`w-full h-1 appearance-none transition-all ${isAutoRiskStandard ? 'bg-broker-cyan shadow-[0_0_15px_rgba(130,234,255,0.8)] cursor-default' : 'bg-white/10 cursor-pointer accent-broker-pink'}`} 
                           />
                        </div>
                      ) : (
                        <motion.div 
                          initial={{ opacity: 0, height: 0 }} 
                          animate={{ opacity: 1, height: 'auto' }} 
                          className="space-y-2 border-t border-white/5 pt-3 mt-1"
                        >
                          {[0,1,2].map(idx => (
                            <div key={idx} className="bg-black/20 border border-white/5 p-2 sharp-edge flex items-center gap-3">
                               <select 
                                 value={comboSettings[idx].type} 
                                 onChange={(e) => updateComboSlot(idx, { type: e.target.value as MarketType })} 
                                 className="bg-black/40 border border-white/10 p-1 text-[8px] font-sans uppercase outline-none w-20"
                               >
                                 {Object.values(MarketType).filter(m => m !== MarketType.COMBO).map(m => (
                                   <option key={m} value={m} className="bg-[#1A1A1C]">{t[m as keyof typeof t] || m.toUpperCase()}</option>
                                 ))}
                               </select>
                               <div className="flex-grow flex flex-col gap-1">
                                 <div className="flex justify-between items-center text-[7px] font-black font-sans">
                                   <button 
                                      onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                      className={`px-1.5 py-0.5 border ${comboSettings[idx].isAuto ? 'border-broker-green text-broker-green' : 'border-white/10 text-gray-600'}`}
                                    >
                                      {t.autoRisk}
                                    </button>
                                   <span className={comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}><span className="num-font font-mono">{comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}</span></span>
                                 </div>
                                 <input 
                                    type="range" 
                                    disabled={comboSettings[idx].isAuto} 
                                    min="0" max="100" 
                                    value={comboSettings[idx].risk} 
                                    onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                    className={`w-full h-[1px] ${comboSettings[idx].isAuto ? 'bg-broker-green shadow-[0_0_10px_rgba(29,240,150,0.6)]' : 'bg-white/10 accent-broker-pink'}`} 
                                  />
                               </div>
                            </div>
                          ))}
                        </motion.div>
                      )}
                    </div>
                  </div>
                </div>

                <motion.button 
                  onClick={handleExecute} 
                  disabled={loading} 
                  animate={!loading ? { scale: [1, 1.01, 1], shadow: ["0 0 0px rgba(255,255,255,0)", "0 0 10px rgba(255,255,255,0.05)", "0 0 0px rgba(255,255,255,0)"] } : {}}
                  transition={{ repeat: Infinity, duration: 4 }}
                  whileTap={{ scale: 0.98 }}
                  className="w-full py-4 bg-white text-black font-black text-lg tracking-widest sharp-edge hover:bg-broker-cyan transition-all disabled:opacity-50 flex justify-center items-center gap-4 group font-sans"
                >
                  {loading ? <Activity size={20} className="animate-spin" /> : <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform" />}
                  {loading ? t.loading : t.predict}
                </motion.button>
              </div>
            )}

            {viewMode === 'search' && (
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)} 
                  onKeyDown={(e) => e.key === 'Enter' && handleSearch()} 
                  placeholder={t.searchPlaceholder} 
                  className="flex-grow bg-white/5 border border-white/10 p-4 text-sm font-sans outline-none focus:border-broker-cyan/50 focus:shadow-[0_0_15px_rgba(130,234,255,0.05)] sharp-edge transition-all text-white shimmer-focus" 
                />
                <button 
                  onClick={handleSearch} 
                  disabled={loading} 
                  className="px-8 bg-broker-cyan text-black font-black tracking-widest text-xs uppercase sharp-edge hover:bg-white transition-all disabled:opacity-50 font-sans"
                >
                  {loading ? '...' : t.searchButton}
                </button>
              </div>
            )}
          </div>

          <div className="mt-12 space-y-6">
            <AnimatePresence mode="popLayout">
              {activePredictions.map((pred, idx) => (
                <PredictionCard key={idx} data={pred} t={t} index={idx} loading={loading} />
              ))}
            </AnimatePresence>

            {activePredictions.length === 0 && !loading && (
              <motion.div initial={{ opacity: 0 }} animate={{ opacity: 0.1 }} className="py-20 text-center border-t border-white/5">
                <ShieldCheck size={48} className="mx-auto mb-4 text-white" />
                <p className="text-[10px] font-black uppercase tracking-[0.5em] font-sans">System Idle // Trust Filter (>= 75%)</p>
              </motion.div>
            )}
          </div>
        </main>
      </div>

      <Dictionary />
    </div>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Prediction, Translation } from '../types';
import { ShieldCheck, Scale, PieChart, Star, Wallet, TrendingUp, AlertTriangle, TrendingDown, ArrowUpRight, Activity } from 'lucide-react';
import SmartText from './SmartText';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
  loading?: boolean;
}

const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index, loading = false }) => {
  const isCombo = !!data.holdings && Array.isArray(data.holdings) && data.holdings.length > 0;
  const accentColor = isCombo ? 'text-[#FFD700]' : 'text-broker-cyan';
  const borderColor = isCombo ? 'border-[#FFD700]/30' : 'border-broker-cyan/30';
  const bgColor = isCombo ? 'bg-[#FFD700]/[0.02]' : 'bg-broker-cyan/[0.02]';

  const safeWithdraw = (data.withdraw || 'HOLD').toUpperCase() === 'BUY' ? 'HOLD' : (data.withdraw || 'HOLD').toUpperCase();

  return (
    <MotionDiv
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ 
        type: 'spring',
        stiffness: 90,
        damping: 18,
        delay: index * 0.1 
      }}
      className={`relative ${bgColor} border-l-2 ${borderColor} border-y border-r border-white/5 p-6 sharp-edge shadow-lg group hover:bg-[#242325] transition-all duration-500`}
    >
      <div className="flex flex-col md:flex-row justify-between items-start mb-6 gap-6">
        <div className="space-y-2 flex-grow">
          <div className="flex flex-wrap items-center gap-3">
            <span className={`text-[8px] font-black px-2 py-0.5 bg-black border border-white/5 ${accentColor} uppercase tracking-widest font-sans`}>
              {data.type}
            </span>
            <div className="flex items-center gap-2">
              <span className="text-[8px] text-gray-500 font-black uppercase font-sans">TRUST</span>
              <div className="w-16 h-[2px] bg-white/5 overflow-hidden">
                <motion.div 
                   initial={{ width: 0 }} 
                   animate={{ width: `${data.confidence || 0}%` }} 
                   transition={{ duration: 1.5, delay: index * 0.1 + 0.5 }}
                   className={`h-full ${isCombo ? 'bg-[#FFD700]' : 'bg-broker-cyan'}`} 
                />
              </div>
              <span className={`text-[8px] font-mono num-font font-black ${accentColor}`}>{data.confidence || 0}%</span>
            </div>
            <div className="flex items-center gap-2 bg-white/5 px-2 py-0.5 border border-white/5">
              <span className="text-[8px] text-gray-500 font-black uppercase font-sans">EXIT</span>
              <span className={`text-[8px] font-black uppercase font-sans ${safeWithdraw === 'SELL' ? 'text-broker-red' : 'text-broker-green'}`}>
                {safeWithdraw}
              </span>
            </div>
          </div>
          <div>
            <h3 className="text-2xl md:text-3xl font-black italic text-white uppercase tracking-tighter leading-none font-sans">
              {data.name || 'Global Strategy'}
            </h3>
            <p className="text-[10px] font-mono num-font text-gray-600 font-black tracking-widest mt-1 uppercase">
              {data.ticker || '---'} // MARKET SECTOR ANALYZED
            </p>
          </div>
        </div>

        <div className="p-3 border border-white/10 sharp-edge bg-black/40 hidden md:block">
           {isCombo ? <Star size={24} className="text-[#FFD700]" /> : <Activity size={24} className="text-broker-cyan" />}
        </div>
      </div>

      {isCombo && Array.isArray(data.holdings) && (
        <div className="mb-6 p-5 bg-black/40 border-y border-white/5 sharp-edge">
          <div className="flex items-center gap-2 text-[9px] font-black text-[#FFD700] uppercase tracking-widest mb-4 pb-2 border-b border-[#FFD700]/10 font-sans">
            <PieChart size={14} /> 3-IN-1 COMBO STRATEGY // GLOBAL DIVERSIFICATION
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {data.holdings.slice(0, 3).map((h, i) => (
              <div key={i} className="bg-white/5 p-4 border border-white/5 sharp-edge relative group/slot transition-all hover:bg-white/10">
                <div className="absolute top-0 right-0 p-1">
                  <span className="text-[7px] text-gray-700 font-black">SLOT {i+1}</span>
                </div>
                <div className="text-[10px] font-black text-white uppercase truncate mb-2 font-sans">{h.name}</div>
                <div className="flex flex-col gap-1">
                  <div className="flex justify-between items-end">
                    <span className="text-[9px] font-mono num-font text-broker-cyan font-bold">{h.ticker}</span>
                    <div className="flex flex-col items-end">
                      <span className="text-[7px] text-gray-600 uppercase font-sans">WEIGHT</span>
                      <span className="text-xl font-mono num-font font-black text-white">{h.weight}%</span>
                    </div>
                  </div>
                  <div className="w-full h-[1px] bg-white/5 mt-2 overflow-hidden">
                    <motion.div 
                      initial={{ width: 0 }}
                      animate={{ width: `${h.weight}%` }}
                      transition={{ duration: 1.2, delay: 0.5 + (i * 0.2) }}
                      className="h-full bg-broker-cyan" 
                    />
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-8">
        {[
          { label: t.expectedProfit, val: data.expectedProfit || '---', color: 'text-broker-green', icon: <TrendingUp size={12}/> },
          { label: t.expectedLoss, val: data.expectedLoss || '---', color: 'text-broker-red', icon: <TrendingDown size={12}/> },
          { label: t.riskRewardRatio, val: data.riskRewardRatio || '---', color: 'text-broker-cyan', icon: <Scale size={12}/> },
          { label: t.finImpact, val: data.budgetImpact?.profitUsd || '---', color: 'text-white', icon: <Wallet size={12}/> }
        ].map((stat, i) => (
          <div key={i} className="bg-black/30 p-3 border border-white/5 transition-all hover:bg-black/50">
            <div className={`text-[8px] font-black uppercase flex items-center gap-2 mb-1 ${stat.color} opacity-60 font-sans`}>
              {stat.icon} {stat.label}
            </div>
            <div className="text-lg font-mono num-font font-black text-white">{stat.val}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 mb-8">
        <div className="bg-black/20 p-4 border border-white/5 border-l-broker-green transition-all hover:border-white/10">
          <h4 className="text-broker-green text-[9px] font-black mb-3 flex items-center gap-2 uppercase tracking-widest font-sans">
            <TrendingUp size={14}/> {t.pros}
          </h4>
          <div className="space-y-2">
            {(data.pros || []).map((p, i) => (
              <p key={i} className="text-[11px] font-sans text-gray-400 leading-tight pl-4 relative">
                <span className="absolute left-0 top-0 text-broker-green font-mono num-font">»</span>
                <SmartText text={p} />
              </p>
            ))}
          </div>
        </div>

        <div className="bg-black/20 p-4 border border-white/5 border-l-broker-red transition-all hover:border-white/10">
          <h4 className="text-broker-red text-[9px] font-black mb-3 flex items-center gap-2 uppercase tracking-widest font-sans">
            <AlertTriangle size={14}/> {t.cons}
          </h4>
          <div className="space-y-2">
            {(data.cons || []).map((c, i) => (
              <p key={i} className="text-[11px] font-sans text-gray-400 leading-tight pl-4 relative">
                <span className="absolute left-0 top-0 text-broker-red font-mono num-font">»</span>
                <SmartText text={c} />
              </p>
            ))}
          </div>
        </div>
      </div>

      {data.groundingSources && data.groundingSources.length > 0 && (
        <div className="mb-4 p-3 bg-black/60 border border-white/5 sharp-edge">
          <div className="text-[8px] font-black text-gray-600 uppercase tracking-widest mb-2 flex items-center gap-2 font-sans">
            <ShieldCheck size={12} /> VERIFIED GLOBAL SOURCES
          </div>
          <div className="flex flex-wrap gap-2">
            {data.groundingSources.map((source, i) => (
              <a key={i} href={source.uri} target="_blank" rel="noopener noreferrer" className="text-[9px] font-sans text-gray-500 hover:text-broker-cyan transition-colors bg-white/5 px-2 py-1 flex items-center gap-1 border border-white/5">
                {source.title ? source.title.substring(0, 30) : 'Source'}... <ArrowUpRight size={8} />
              </a>
            ))}
          </div>
        </div>
      )}

      <div className="flex justify-between items-center pt-4 border-t border-white/5">
        <div className="flex items-center gap-2">
          <div className={`w-2 h-2 rounded-full ${loading ? 'bg-broker-cyan animate-pulse' : 'bg-broker-green'}`} />
          <span className="text-[9px] font-black uppercase tracking-[0.4em] text-gray-700 font-sans">SYSTEM ACTIVE // GLOBAL SCAN READY</span>
        </div>
        <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest font-sans flex items-center gap-2">
          {t.confShort}: <span className={`num-font ${accentColor}`}>{data.confidence}%</span>
        </div>
      </div>
    </MotionDiv>
  );
};

