const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');
  const [marketData, setMarketData] = useState<TickerItem[]>(MOCK_TICKER_DATA);

  const [budget, setBudget] = useState<number | null>(null);

  // AI now selects the types for COMBO, user only controls risk profile for the 3 slots
  const [comboSettings, setComboSettings] = useState<Omit<ComboAssetConfig, 'type'>[]>([
    { risk: 50, isAuto: true },
    { risk: 50, isAuto: true },
    { risk: 50, isAuto: true }
  ]);

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 24, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAutoRiskStandard, setIsAutoRiskStandard] = useState(true);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const isComboMode = type === MarketType.COMBO;

  // Alphabetise Market Types for the dropdown
  const sortedMarketTypes = useMemo(() => {
    return Object.values(MarketType).sort((a, b) => {
      const labelA = (t[a as keyof typeof t] || a).toUpperCase();
      const labelB = (t[b as keyof typeof t] || b).toUpperCase();
      return labelA.localeCompare(labelB, lang);
    });
  }, [t, lang]);

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  useEffect(() => {
    const loadTickers = async () => {
      const data = await fetchLiveMarketData();
      setMarketData(data);
    };
    loadTickers();
    const interval = setInterval(loadTickers, 30000);
    return () => clearInterval(interval);
  }, []);

  const autoRiskCalculated = useMemo(() => {
    if (totalHours <= 24) return 85; 
    if (totalHours <= 168) return 65; 
    if (totalHours <= 720) return 50; 
    if (totalHours <= 4320) return 30; 
    return 15; 
  }, [totalHours]);

  useEffect(() => {
    if (isAutoRiskStandard) {
      setRiskScore(autoRiskCalculated);
    }
  }, [autoRiskCalculated, isAutoRiskStandard]);

  const activePredictionsRaw = viewMode === 'predict' ? predictorResults : searchResults;
  const activePredictions = useMemo(() => {
    return (Array.isArray(activePredictionsRaw) ? activePredictionsRaw : [])
      .filter(p => (p.confidence || 0) >= 75);
  }, [activePredictionsRaw]);

  const handleExecute = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = Array.isArray(tickerData) ? tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ') : '';

      const results = await fetchPredictions(
        totalHours || 24, 
        isAutoRiskStandard ? 'AUTO' : riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? comboSettings.map(s => ({ ...s, type: MarketType.GENERAL })) : null, 
        context
      );
      setPredictorResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError(err?.message || 'Execution failed');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, isAutoRiskStandard, type, lang, budget, isComboMode, comboSettings]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const results = await searchAssets(`${searchQuery}`, lang);
      setSearchResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError('Search Error');
    } finally { setLoading(false); }
  };

  const updateComboSlot = (index: number, updates: Partial<Omit<ComboAssetConfig, 'type'>>) => {
    const next = [...comboSettings];
    next[index] = { ...next[index], ...updates };
    setComboSettings(next);
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-[#141415] selection:bg-broker-pink selection:text-white overflow-x-hidden">
      <div className="relative z-10 flex flex-col min-h-screen">
        <header className="px-6 py-4 flex justify-between items-center max-w-full mx-auto w-full border-b border-white/5 bg-[#141415]/80 backdrop-blur-md sticky top-0 z-50">
          <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="flex items-center gap-3">
            <Cpu size={24} className="text-broker-cyan" />
            <h1 className="text-xl font-black italic tracking-tight uppercase text-white font-sans">
              {t.title} <span className="text-[10px] text-gray-500 font-black tracking-[0.3em] ml-4 hidden md:inline">V4.5 GLOBAL TERMINAL</span>
            </h1>
          </motion.div>

          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 bg-white/5 px-3 py-1.5 sharp-edge border border-white/5">
                <Globe size={14} className="text-broker-cyan" />
                <select 
                  disabled={loading}
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)} 
                  className="bg-transparent text-[10px] font-black uppercase outline-none cursor-pointer font-sans disabled:opacity-50"
                >
                  <option value="es" className="bg-[#141415]">ES</option>
                  <option value="en" className="bg-[#141415]">EN</option>
                  <option value="fr" className="bg-[#141415]">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="flex-grow p-4 md:p-6 lg:p-8 flex flex-col lg:flex-row gap-6 max-w-[1920px] mx-auto w-full">

          <aside className="lg:w-[320px] flex-shrink-0 space-y-6">
            <div className="bg-[#242325] border border-white/10 sharp-edge p-6 shadow-xl relative overflow-hidden">
              <div className="absolute top-0 left-0 w-1 h-full bg-broker-cyan" />
              <div className="flex items-center gap-2 mb-6 border-b border-white/5 pb-2">
                <Settings size={14} className="text-gray-500" />
                <span className="text-[10px] font-black tracking-widest text-gray-400 uppercase font-sans">TERMINAL CONFIG</span>
              </div>

              <div className={`space-y-8 ${loading ? 'pointer-events-none opacity-60' : ''}`}>
                <div className="space-y-4">
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
                      <Clock size={14} /> {t.horizon}
                    </span>
                    <button 
                      disabled={loading}
                      onClick={() => setHorizonMode(horizonMode === 'precise' ? 'calendar' : 'precise')} 
                      className="text-[8px] font-black px-2 py-1 text-gray-500 hover:text-white border border-white/10 sharp-edge transition-all font-sans disabled:opacity-50"
                    >
                      {horizonMode === 'precise' ? t.calendar : t.precise}
                    </button>
                  </div>
                  {horizonMode === 'precise' ? (
                    <div className="grid grid-cols-5 gap-1.5">
                      {['h', 'd', 'w', 'm', 'y'].map((k) => (
                        <div key={k} className="flex flex-col gap-1">
                          <span className="text-[8px] text-center font-black text-gray-700 uppercase font-sans">{k}</span>
                          <input 
                            disabled={loading}
                            type="number" 
                            value={(time as any)[k] || ''} 
                            onChange={(e) => setTime({...time, [k]: parseInt(e.target.value) || 0})} 
                            className="bg-white/5 border border-white/5 p-2 text-center text-[10px] font-mono num-font outline-none focus:border-broker-pink/50 focus:shadow-[0_0_10px_rgba(243,27,128,0.1)] sharp-edge text-white transition-all shimmer-focus disabled:opacity-50" 
                          />
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="space-y-3">
                      <div className="flex flex-col gap-1">
                        <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.startDate}</span>
                        <input disabled={loading} type="date" value={dates.start} onChange={(e) => setDates({...dates, start: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-[10px] font-mono num-font outline-none focus:border-broker-pink/50 sharp-edge text-white transition-all shimmer-focus disabled:opacity-50" />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.endDate}</span>
                        <input disabled={loading} type="date" value={dates.end} onChange={(e) => setDates({...dates, end: e.target.value})} className="bg-white/5 border border-white/5 p-2 text-[10px] font-mono num-font outline-none focus:border-broker-pink/50 sharp-edge text-white transition-all shimmer-focus disabled:opacity-50" />
                      </div>
                    </div>
                  )}
                </div>

                <div className="space-y-3">
                  <span className="text-[9px] font-black tracking-widest text-broker-green uppercase flex items-center gap-2 font-sans">
                    <Wallet size={14} /> {t.budgetLabel}
                  </span>
                  <div className="flex items-center gap-2 bg-white/5 px-4 py-3 sharp-edge border border-white/5 focus-within:border-broker-green/50 focus-within:shadow-[0_0_10px_rgba(29,240,150,0.1)] transition-all">
                    <span className="text-xs font-mono text-broker-green">$</span>
                    <input 
                      disabled={loading}
                      type="number" 
                      value={budget || ''}
                      onChange={(e) => setBudget(parseFloat(e.target.value) || null)}
                      placeholder={t.budgetPlaceholder}
                      className="bg-transparent text-sm font-mono num-font outline-none w-full text-white placeholder:text-gray-700 shimmer-focus disabled:opacity-50"
                    />
                  </div>
                </div>

                <div className="space-y-4">
                  <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
                    <Filter size={14}/> {t.strategy}
                  </span>
                  <div className="space-y-4">
                    <div className="flex flex-col gap-2">
                       <span className="text-[8px] font-black text-gray-700 uppercase font-sans">{t.priority}</span>
                       <select 
                          disabled={loading}
                          value={type} 
                          onChange={(e) => setType(e.target.value as MarketType)} 
                          className={`w-full bg-black/40 border p-2.5 text-[10px] font-sans uppercase outline-none cursor-pointer sharp-edge transition-all disabled:opacity-50 ${isComboMode ? 'border-broker-cyan shadow-[0_0_15px_rgba(130,234,255,0.2)]' : 'border-white/10'}`}
                        >
                         {sortedMarketTypes.map(m => (
                           <option key={m} value={m} className="bg-[#1A1A1C]">
                             {t[m as keyof typeof t] || m.toUpperCase()}
                           </option>
                         ))}
                       </select>
                    </div>

                    {!isComboMode ? (
                      <div className="flex flex-col gap-3">
                         <div className="flex justify-between items-end text-[8px] font-black uppercase font-sans">
                           <div className="flex flex-col gap-1">
                              <span className="text-broker-pink">RISK INDEX: <span className="num-font font-mono">{isAutoRiskStandard ? 'AUTO' : riskScore}</span></span>
                           </div>
                           <button 
                             disabled={loading}
                             onClick={() => setIsAutoRiskStandard(!isAutoRiskStandard)} 
                             className={`px-3 py-1 border text-[7px] transition-all duration-300 sharp-edge font-sans disabled:opacity-50 ${isAutoRiskStandard ? 'bg-broker-green border-broker-green text-black shadow-[0_0_10px_rgba(29,240,150,0.3)]' : 'border-white/10 text-gray-500'}`}
                           >
                             {t.autoRisk}
                           </button>
                         </div>
                         <input 
                           type="range" 
                           disabled={isAutoRiskStandard || loading} 
                           min="0" max="100" 
                           value={riskScore} 
                           onChange={(e) => setRiskScore(parseInt(e.target.value))} 
                           className={`w-full h-1 appearance-none transition-all disabled:opacity-30 ${isAutoRiskStandard ? 'bg-broker-cyan shadow-[0_0_15px_rgba(130,234,255,1)] cursor-default' : 'bg-white/10 cursor-pointer accent-broker-pink'}`} 
                         />
                      </div>
                    ) : (
                      <div className="space-y-2 border-t border-white/5 pt-3">
                        <p className="text-[7px] font-black text-gray-600 uppercase mb-2">AI-DRIVEN DIVERSIFICATION // USER RISK CONTROL</p>
                        {[0,1,2].map(idx => (
                          <div key={idx} className="bg-black/20 border border-white/5 p-2 sharp-edge flex flex-col gap-2">
                             <div className="flex-grow flex flex-col gap-1">
                               <div className="flex justify-between items-center text-[7px] font-black font-sans">
                                 <button 
                                    disabled={loading}
                                    onClick={() => updateComboSlot(idx, { isAuto: !comboSettings[idx].isAuto })} 
                                    className={`px-1.5 py-0.5 border disabled:opacity-50 ${comboSettings[idx].isAuto ? 'border-broker-green text-broker-green' : 'border-white/10 text-gray-600'}`}
                                  >
                                    SLOT {idx+1} AUTO
                                  </button>
                                 <span className={comboSettings[idx].isAuto ? 'text-broker-green' : 'text-broker-pink'}><span className="num-font font-mono">{comboSettings[idx].isAuto ? 'AUTO' : comboSettings[idx].risk}</span></span>
                               </div>
                               <input 
                                  type="range" 
                                  disabled={comboSettings[idx].isAuto || loading} 
                                  min="0" max="100" 
                                  value={comboSettings[idx].risk} 
                                  onChange={(e) => updateComboSlot(idx, { risk: parseInt(e.target.value) })} 
                                  className={`w-full h-[1px] disabled:opacity-30 ${comboSettings[idx].isAuto ? 'bg-broker-green shadow-[0_0_8px_rgba(29,240,150,0.5)]' : 'bg-white/10 accent-broker-pink'}`} 
                                />
                             </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          </aside>

          <section className="flex-grow flex flex-col gap-6 min-w-0">
            <div className="bg-[#242325] border border-white/10 shadow-xl overflow-hidden sharp-edge">
              <div className="flex">
                {[
                  { id: 'predict', icon: <Command size={14}/>, label: t.tabPredictor },
                  { id: 'search', icon: <Search size={14}/>, label: t.tabSearch },
                ].map(tab => (
                  <button
                    key={tab.id}
                    disabled={loading}
                    onClick={() => setViewMode(tab.id as any)}
                    className={`flex-1 py-4 text-[10px] font-black tracking-widest uppercase flex items-center justify-center gap-2 transition-all font-sans disabled:opacity-50 ${viewMode === tab.id ? 'bg-[#1A1A1C] text-white border-b-2 border-broker-cyan' : 'bg-transparent text-gray-600 hover:text-white'}`}
                  >
                    {tab.icon} {tab.label}
                  </button>
                ))}
              </div>

              <div className="p-6">
                {viewMode === 'predict' ? (
                  <motion.button 
                    onClick={handleExecute} 
                    disabled={loading} 
                    animate={!loading ? { scale: [1, 1.01, 1] } : {}}
                    transition={{ repeat: Infinity, duration: 4 }}
                    className="w-full py-5 bg-white text-black font-black text-lg tracking-[0.2em] sharp-edge hover:bg-broker-cyan transition-all disabled:opacity-50 flex justify-center items-center gap-4 group font-sans"
                  >
                    {loading ? <Activity size={24} className="animate-spin" /> : <ArrowRight size={24} className="group-hover:translate-x-2 transition-transform" />}
                    {loading ? t.loading : t.predict}
                  </motion.button>
                ) : (
                  <div className="flex gap-2">
                    <input 
                      disabled={loading}
                      type="text" 
                      value={searchQuery} 
                      onChange={(e) => setSearchQuery(e.target.value)} 
                      onKeyDown={(e) => e.key === 'Enter' && handleSearch()} 
                      placeholder={t.searchPlaceholder} 
                      className="flex-grow bg-white/5 border border-white/10 p-4 text-sm font-sans outline-none focus:border-broker-cyan/50 focus:shadow-[0_0_15px_rgba(130,234,255,0.05)] sharp-edge transition-all text-white shimmer-focus disabled:opacity-50" 
                    />
                    <button 
                      onClick={handleSearch} 
                      disabled={loading} 
                      className="px-8 bg-broker-cyan text-black font-black tracking-widest text-xs uppercase sharp-edge hover:bg-white transition-all disabled:opacity-50 font-sans"
                    >
                      {loading ? '...' : t.searchButton}
                    </button>
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-6">
              <AnimatePresence mode="popLayout">
                {activePredictions.map((pred, idx) => (
                  <PredictionCard key={idx} data={pred} t={t} index={idx} loading={loading} />
                ))}
              </AnimatePresence>

              {activePredictions.length === 0 && !loading && (
                <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="py-24 text-center border border-white/5 bg-white/[0.02] sharp-edge">
                  <LayoutDashboard size={48} className="mx-auto mb-4 text-gray-800" />
                  <p className="text-[10px] font-black uppercase tracking-[0.5em] text-gray-700 font-sans">QUANTUM TERMINAL // FEED IDLE</p>
                  <p className="text-[8px] font-black uppercase tracking-widest text-gray-800 mt-2 font-sans">AWAITING EXECUTION COMMAND</p>
                </motion.div>
              )}
            </div>
          </section>

          <aside className="lg:w-[300px] flex-shrink-0">
             <div className="bg-[#242325] border border-white/10 sharp-edge p-6 shadow-xl sticky top-24">
                <Ticker data={marketData} />
             </div>
          </aside>
        </main>
      </div>

      <AnimatePresence>
        {loading && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed top-0 left-0 w-full h-1 z-[60] bg-broker-cyan/10">
            <motion.div 
              initial={{ width: '0%' }} 
              animate={{ width: '100%' }} 
              transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }}
              className="h-full bg-broker-cyan shadow-[0_0_15px_rgba(130,234,255,0.8)]"
            />
          </motion.div>
        )}
      </AnimatePresence>

      <Dictionary />
    </div>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Prediction, Translation } from '../types';
import { ShieldCheck, Scale, PieChart, Star, Wallet, TrendingUp, AlertTriangle, TrendingDown, ArrowUpRight, Activity } from 'lucide-react';
import SmartText from './SmartText';

interface Props {
  data: Prediction;
  t: Translation;
  index: number;
  loading?: boolean;
}

const MotionDiv = motion.div as any;

const PredictionCard: React.FC<Props> = ({ data, t, index, loading = false }) => {
  const isCombo = !!data.holdings && Array.isArray(data.holdings) && data.holdings.length > 0;
  const accentColor = isCombo ? 'text-[#FFD700]' : 'text-broker-cyan';
  const borderColor = isCombo ? 'border-[#FFD700]/30' : 'border-broker-cyan/30';
  const bgColor = isCombo ? 'bg-[#FFD700]/[0.02]' : 'bg-broker-cyan/[0.02]';

  const safeWithdraw = (data.withdraw || 'HOLD').toUpperCase() === 'BUY' ? 'HOLD' : (data.withdraw || 'HOLD').toUpperCase();

  return (
    <MotionDiv
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ 
        type: 'spring',
        stiffness: 90,
        damping: 18,
        delay: index * 0.1 
      }}
      className={`relative ${bgColor} border-l-2 ${borderColor} border-y border-r border-white/5 p-6 sharp-edge shadow-lg group hover:bg-[#242325] transition-all duration-500`}
    >
      <div className="flex flex-col md:flex-row justify-between items-start mb-6 gap-6">
        <div className="space-y-2 flex-grow">
          <div className="flex flex-wrap items-center gap-3">
            <span className={`text-[8px] font-black px-2 py-0.5 bg-black border border-white/5 ${accentColor} uppercase tracking-widest font-sans`}>
              {data.type}
            </span>
            <div className="flex items-center gap-2">
              <span className="text-[8px] text-gray-500 font-black uppercase font-sans">TRUST</span>
              <div className="w-16 h-[2px] bg-white/5 overflow-hidden">
                <motion.div 
                   initial={{ width: 0 }} 
                   animate={{ width: `${data.confidence || 0}%` }} 
                   transition={{ duration: 1.5, delay: index * 0.1 + 0.5 }}
                   className={`h-full ${isCombo ? 'bg-[#FFD700]' : 'bg-broker-cyan'}`} 
                />
              </div>
              <span className={`text-[8px] font-mono num-font font-black ${accentColor}`}>{data.confidence || 0}%</span>
            </div>
            <div className="flex items-center gap-2 bg-white/5 px-2 py-0.5 border border-white/5">
              <span className="text-[8px] text-gray-500 font-black uppercase font-sans">EXIT</span>
              <span className={`text-[8px] font-black uppercase font-sans ${safeWithdraw === 'SELL' ? 'text-broker-red' : 'text-broker-green'}`}>
                {safeWithdraw}
              </span>
            </div>
          </div>
          <div>
            <h3 className="text-2xl md:text-3xl font-black italic text-white uppercase tracking-tighter leading-none font-sans">
              {data.name || 'Global Strategy'}
            </h3>
            {/* Tickers removed to show real names only and prevent confusion */}
            <p className="text-[8px] text-gray-700 font-black tracking-widest mt-1 uppercase font-sans">
              IDENTIFIED GLOBAL OPPORTUNITY // MARKET ANALYSIS VERIFIED
            </p>
          </div>
        </div>

        <div className="p-3 border border-white/10 sharp-edge bg-black/40 hidden md:block">
           {isCombo ? <Star size={24} className="text-[#FFD700]" /> : <Activity size={24} className="text-broker-cyan" />}
        </div>
      </div>

      {isCombo && Array.isArray(data.holdings) && (
        <div className="mb-6 p-5 bg-black/40 border-y border-white/5 sharp-edge">
          <div className="flex items-center gap-2 text-[9px] font-black text-[#FFD700] uppercase tracking-widest mb-4 pb-2 border-b border-[#FFD700]/10 font-sans">
            <PieChart size={14} /> 3-IN-1 COMBO STRATEGY // ALLOCATION
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {data.holdings.slice(0, 3).map((h, i) => (
              <div key={i} className="bg-white/5 p-4 border border-white/5 sharp-edge relative group/slot transition-all hover:bg-white/10">
                <div className="absolute top-0 right-0 p-1">
                  <span className="text-[7px] text-gray-700 font-black">SLOT {i+1}</span>
                </div>
                {/* Displaying real name clearly */}
                <div className="text-[10px] font-black text-white uppercase truncate mb-2 font-sans">{h.name}</div>
                <div className="flex flex-col gap-1">
                  <div className="flex justify-between items-end">
                    <div className="flex flex-col">
                       <span className="text-[7px] text-gray-600 uppercase font-sans">STRATEGY</span>
                       <span className="text-[9px] font-mono num-font text-broker-cyan font-bold">OPTIMAL</span>
                    </div>
                    <div className="flex flex-col items-end">
                      <span className="text-[7px] text-gray-600 uppercase font-sans">WEIGHT</span>
                      <span className="text-xl font-mono num-font font-black text-white">{h.weight}%</span>
                    </div>
                  </div>
                  <div className="w-full h-[1px] bg-white/5 mt-2 overflow-hidden">
