        </main>
      </div>

      <AnimatePresence>
        {loading && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed top-0 left-0 w-full h-[2px] z-[60] bg-broker-cyan/10">
            <motion.div 
              initial={{ width: '0%' }} 
              animate={{ width: '100%' }} 
              transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }}
              className="h-full bg-broker-cyan shadow-[0_0_10px_rgba(130,234,255,0.8)]"
            />
          </motion.div>
        )}
      </AnimatePresence>

      <Dictionary />
    </div>
  );
}

import React from 'react';
