import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { TRANSLATIONS } from './constants';
import { Language, MarketType, Prediction, TimeInput, HorizonMode, ComboAssetConfig } from './types';
import { fetchPredictions, searchAssets, fetchLiveMarketData } from './services/geminiService';
import PredictionCard from './components/PredictionCard';
import Dictionary from './components/Dictionary';
import { Activity, Globe, Wallet, Clock, Filter, Search, ShieldCheck, X, Command, Cpu, ArrowRight, Settings, LayoutDashboard } from 'lucide-react';

const MotionDiv = motion.div as any;

export default function App() {
  const [lang, setLang] = useState<Language>('es');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [predictorResults, setPredictorResults] = useState<Prediction[]>([]);
  const [searchResults, setSearchResults] = useState<Prediction[]>([]);
  const [viewMode, setViewMode] = useState<'predict' | 'search'>('predict');
  const [searchQuery, setSearchQuery] = useState('');

  const [budget, setBudget] = useState<number | null>(null);

  // Master risk for COMBO mode
  const [comboRisk, setComboRisk] = useState(50);
  const [isComboAuto, setIsComboAuto] = useState(true);

  const [horizonMode, setHorizonMode] = useState<HorizonMode>('precise');
  const [time, setTime] = useState<TimeInput>({ h: 0, d: 24, w: 0, m: 0, y: 0 });
  const [dates, setDates] = useState({ 
    start: new Date().toISOString().split('T')[0], 
    end: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] 
  });

  const [riskScore, setRiskScore] = useState(50);
  const [isAutoRiskStandard, setIsAutoRiskStandard] = useState(true);
  const [type, setType] = useState<MarketType>(MarketType.GENERAL);

  const t = TRANSLATIONS[lang];
  const isComboMode = type === MarketType.COMBO;

  const sortedMarketTypes = useMemo(() => {
    return Object.values(MarketType).sort((a, b) => {
      const labelA = (t[a as keyof typeof t] || a).toUpperCase();
      const labelB = (t[b as keyof typeof t] || b).toUpperCase();
      return labelA.localeCompare(labelB, lang);
    });
  }, [t, lang]);

  const totalHours = useMemo(() => {
    if (horizonMode === 'precise') {
      return (time.h * 1) + (time.d * 24) + (time.w * 168) + (time.m * 720) + (time.y * 8760);
    } else {
      const s = new Date(dates.start);
      const e = new Date(dates.end);
      const diff = e.getTime() - s.getTime();
      return Math.max(0, Math.floor(diff / (1000 * 60 * 60)));
    }
  }, [time, dates, horizonMode]);

  const autoRiskCalculated = useMemo(() => {
    if (totalHours <= 24) return 85; 
    if (totalHours <= 168) return 65; 
    if (totalHours <= 720) return 50; 
    if (totalHours <= 4320) return 30; 
    return 15; 
  }, [totalHours]);

  useEffect(() => {
    if (isAutoRiskStandard) {
      setRiskScore(autoRiskCalculated);
    }
  }, [autoRiskCalculated, isAutoRiskStandard]);

  const handleExecute = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const tickerData = await fetchLiveMarketData();
      const context = Array.isArray(tickerData) ? tickerData.map(i => `${i.symbol}: ${i.price}`).join(', ') : '';

      // Map master combo risk to the 3 internal slots for the service
      const mappedComboSettings = [
        { risk: comboRisk, isAuto: isComboAuto, type: MarketType.GENERAL },
        { risk: comboRisk, isAuto: isComboAuto, type: MarketType.GENERAL },
        { risk: comboRisk, isAuto: isComboAuto, type: MarketType.GENERAL }
      ];

      const results = await fetchPredictions(
        totalHours || 24, 
        isAutoRiskStandard ? 'AUTO' : riskScore, 
        type, 
        lang, 
        budget, 
        isComboMode ? mappedComboSettings : null, 
        context
      );
      setPredictorResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError(err?.message || 'Execution failed');
    } finally { setLoading(false); }
  }, [totalHours, riskScore, isAutoRiskStandard, type, lang, budget, isComboMode, comboRisk, isComboAuto]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) return;
    setLoading(true);
    setError(null);
    try {
      const results = await searchAssets(`${searchQuery}`, lang);
      setSearchResults(Array.isArray(results) ? results : []);
    } catch (err: any) {
      setError('Search Error');
    } finally { setLoading(false); }
  };

  return (
    <div className="min-h-screen relative font-sans text-broker-text bg-[#141415] selection:bg-broker-pink selection:text-white overflow-x-hidden">
      <div className="relative z-10 flex flex-col min-h-screen">
        <header className="px-6 py-3 flex justify-between items-center max-w-full mx-auto w-full border-b border-white/5 bg-[#141415]/80 backdrop-blur-md sticky top-0 z-50">
          <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="flex items-center gap-3">
            <Cpu size={20} className="text-broker-cyan" />
            <h1 className="text-lg font-black italic tracking-tight uppercase text-white font-sans">
              {t.title} <span className="text-[9px] text-gray-500 font-black tracking-[0.2em] ml-3 hidden sm:inline">V5.0 BLOOM MODULE</span>
            </h1>
          </motion.div>

          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 bg-white/5 px-3 py-1 sharp-edge border border-white/5">
                <Globe size={12} className="text-broker-cyan" />
                <select 
                  disabled={loading}
                  value={lang} 
                  onChange={(e) => setLang(e.target.value as Language)} 
                  className="bg-transparent text-[9px] font-black uppercase outline-none cursor-pointer font-sans disabled:opacity-50"
                >
                  <option value="es" className="bg-[#141415]">ES</option>
                  <option value="en" className="bg-[#141415]">EN</option>
                  <option value="fr" className="bg-[#141415]">FR</option>
                </select>
             </div>
          </div>
        </header>

        <main className="flex-grow p-4 lg:px-8 flex flex-col md:flex-row gap-6 max-w-[1440px] mx-auto w-full">

          {/* Sidebar Config - Only visible in Oracle tab */}
          <AnimatePresence mode="wait">
            {viewMode === 'predict' && (
              <motion.aside 
                initial={{ opacity: 0, x: -30 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -30 }}
                className={`md:w-[300px] flex-shrink-0 space-y-5 transition-opacity duration-300 ${loading ? 'opacity-60 pointer-events-none' : ''}`}
              >
                <div className={`bg-[#242325] border border-white/10 sharp-edge p-5 shadow-xl relative overflow-hidden transition-all duration-700 ${isComboMode ? 'shadow-[0_0_30px_rgba(130,234,255,0.15)] border-broker-cyan/40' : ''}`}>
