                exit={{ opacity: 0, x: -30 }}
                className={`md:w-[300px] flex-shrink-0 space-y-5 transition-opacity duration-300 ${loading ? 'opacity-60 pointer-events-none' : ''}`}
              >
                <div className={`bg-[#242325] border border-white/10 sharp-edge p-5 shadow-xl relative overflow-hidden transition-all duration-700 ${isComboMode ? 'border-broker-cyan/40' : ''}`}>
                  <div className={`absolute top-0 left-0 w-1 h-full bg-broker-cyan`} />

                  <div className="space-y-6 relative z-10">
                    {/* Horizon */}
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
