                    <div className="space-y-3">
                      <span className="text-[9px] font-black tracking-widest text-broker-cyan uppercase flex items-center gap-2 font-sans">
                        <Filter size={12}/> {t.strategy}
                      </span>
                      <div className="space-y-3">
                        <div className="flex flex-col gap-1.5 relative group">
