                                 }}
                                 transition={{ repeat: Infinity, duration: 2 }}
                                 className="absolute inset-0 pointer-events-none sharp-edge border border-broker-cyan"
                               />
                             )}

                             <select 
                                value={type} 
                                onChange={(e) => setType(e.target.value as MarketType)} 
                                className={`w-full bg-black/40 border p-2 text-[9px] font-sans uppercase outline-none cursor-pointer sharp-edge transition-all relative z-10 ${isComboMode ? 'border-broker-cyan text-white' : 'border-white/10 text-gray-400'}`}
                              >
