                                 className={`px-2 py-0.5 border text-[7px] transition-all sharp-edge font-sans ${isAutoRiskStandard ? 'bg-broker-green border-broker-green text-black' : 'border-white/10 text-gray-500'}`}
                               >
                                 {t.autoRisk}
                               </button>
                             </div>
                             <input 
                               type="range" 
                               disabled={isAutoRiskStandard} 
                               min="0" max="100" 
                               value={riskScore} 
                               onChange={(e) => setRiskScore(parseInt(e.target.value))} 
                               className={`w-full h-1 appearance-none ${isAutoRiskStandard ? 'bg-broker-cyan shadow-[0_0_10px_rgba(130,234,255,0.5)] cursor-default' : 'bg-white/10 accent-broker-pink cursor-pointer'}`} 
                             />
                          </div>
                        ) : (
                          <div className={`space-y-2 border-t border-white/5 pt-3 transition-all ${isComboMode ? 'opacity-100' : 'opacity-0'}`}>
                            <p className="text-[7px] font-black text-broker-cyan uppercase tracking-tighter">AI DIVERSIFIED COMBO // MASTER RISK</p>
