                                    className={`px-2 py-1 border transition-all ${isComboAuto ? 'border-broker-green text-broker-green bg-broker-green/10' : 'border-white/10 text-gray-500'}`}
                                  >
                                    {isComboAuto ? 'AUTO' : 'MANUAL'}
