      riskRewardRatio: { type: Type.STRING, description: "R/R ratio." },
      pros: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Alpha factors in the target language." },
      cons: { type: Type.ARRAY, items: { type: Type.STRING }, description: "Beta factors in the target language." },
      withdraw: { type: Type.STRING, description: "Target Language exit label (e.g. 'SALIDA', 'VENDRE', 'EXIT')." },
      confidence: { type: Type.NUMBER, description: "Trust percentage (0-100)." },
      holdings: {
        type: Type.ARRAY,
