const tickerSchema = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      symbol: { type: Type.STRING, description: "Asset ticker symbol." },
      price: { type: Type.STRING, description: "Current price formatted as string." },
      change: { type: Type.STRING, description: "Price change formatted as string (e.g., +2.5%)." },
      isUp: { type: Type.BOOLEAN, description: "True if price is up, false otherwise." }
    },
    required: ["symbol", "price", "change", "isUp"]
  }
};

export const fetchLiveMarketData = async (): Promise<TickerItem[]> => {
  const cachedRaw = localStorage.getItem(TICKER_CACHE_KEY);
  if (cachedRaw) {
    try {
      const { timestamp, data } = JSON.parse(cachedRaw);
      if (Date.now() - timestamp < TICKER_CACHE_TTL) return data;
    } catch (e) { localStorage.removeItem(TICKER_CACHE_KEY); }
  }

  try {
    const response = await callWithRetry({
      model: "gemini-3-flash-preview",
      contents: "Return a JSON array of current market data for top global assets. JSON array only.",
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction: "Global Quant Scraper. JSON array only.",
        responseMimeType: "application/json",
        responseSchema: tickerSchema,
      },
    });

    const data = extractJson(response.text || '[]');
    if (Array.isArray(data) && data.length) {
      localStorage.setItem(TICKER_CACHE_KEY, JSON.stringify({ timestamp: Date.now(), data }));
      return data;
    }
    return Array.isArray(data) ? data : MOCK_TICKER_DATA;
  } catch (error) { 
    return MOCK_TICKER_DATA; 
  }
};

export const fetchPredictions = async (
  totalHours: number,
  riskScore: number | string,
  type: string,
  lang: string,
  budget: number | null,
  comboSettings: ComboAssetConfig[] | null,
  context?: string
): Promise<Prediction[]> => {
  const isCombo = type === 'combo';
  const comboInfo = comboSettings 
    ? `COMBO MODE: Correlated 3-asset plan. Risk: ${riskScore}.`
    : `SINGLE MODE: Market: ${type}, Risk: ${riskScore}.`;

  const prompt = `
    LANGUAGE REQUIREMENT: EVERYTHING MUST BE IN ${lang.toUpperCase()}. All descriptions, labels, and analysis.
    GLOBAL MARKET CONTEXT: ${context}
    BUDGET: ${budget ? `$${budget}` : 'N/A'}
    HORIZON: ${totalHours}h
    PROFILE: ${comboInfo}

    TASK: Generate 5 deep quant predictions.
    STRICT: Use REAL NAMES. 
    STRICT: All text parts must be in ${lang.toUpperCase()}.
    STRICT: Withdraw field must be a translated exit label (e.g., 'HOLD', 'VENDER', 'VENDRE').
  `;

  const response = await callWithRetry({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      tools: [{ googleSearch: {} }],
      systemInstruction: SYSTEM_INSTRUCTION + ` Respond exclusively in the language: ${lang}. JSON strictly.`,
      responseMimeType: "application/json",
      responseSchema: predictionSchema,
      thinkingConfig: { thinkingBudget: 4000 },
    },
  });

  const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];
  const sources = chunks.filter((c: any) => c.web).map((c: any) => ({ title: c.web.title, uri: c.web.uri }));

  let data = extractJson(response.text || '[]');
  if (!Array.isArray(data)) data = data.predictions || [data];

  return Array.isArray(data) ? data.map((item: any) => ({ 
    ...item, 
    groundingSources: sources,
    pros: Array.isArray(item.pros) ? item.pros : [],
    cons: Array.isArray(item.cons) ? item.cons : []
  })) : [];
};

